Ceviri.ekle("el","olay",{
"OLAYLAR_EK16:1944-07-27:1":{"b": ["Το Νταουγκάβπιλς απελευθερώθηκε από τον Κόκκινο Στρατό", "b4ee6622"], "d": ["Η 360ή Μεραρχία Πεζικού του 2ου Μετώπου της Βαλτικής κατέλαβε το Νταουγκάβπιλς (Ντύναμπουργκ)· η δεύτερη μεγαλύτερη πόλη της Λατγκάλε βγήκε από τη γερμανική διοίκηση.", "b8a7bd0d"]},
"OLAYLAR_EK16:1944-07-27:2":{"b": ["Το Σιαουλιάι καταλήφθηκε από τον Κόκκινο Στρατό — Επιχείρηση του Σιαουλιάι", "ccb20729"], "d": ["Το 1ο Μέτωπο της Βαλτικής κατέλαβε το Σιαουλιάι, τον σιδηροδρομικό κόμβο της βόρειας Λιθουανίας· η επιχείρηση διήρκεσε από τις 5 Ιουλίου έως τις 29 Αυγούστου 1944 και έφτασε στον Κόλπο της Ρίγας.", "444f3101"]},
"OLAYLAR_EK16:1944-07-28:0":{"b": ["Ο Κόκκινος Στρατός απελευθέρωσε το Μπρεστ-Λιτόφσκ από τη γερμανική κατοχή", "6d5a837a"], "d": ["Ανατολικό Μέτωπο: Επιχείρηση Μπαρμπαρόσα του 1941 και Επιχείρηση Μπαγκρατιόν του 1944.", "c6101096"]},
"OLAYLAR_EK16:1944-08-01:0":{"b": ["Το Κάουνας καταλήφθηκε από τον Κόκκινο Στρατό — η προσωρινή πρωτεύουσα της Λιθουανίας βγήκε από τη γερμανική διοίκηση", "5c2b2c16"], "d": ["Το 3ο Μέτωπο της Λευκορωσίας κατέλαβε το Κάουνας· η ημερήσια διαταγή του Στάλιν της 1ης Αυγούστου ανήγγειλε την κατάληψη. Η πόλη ήταν η προσωρινή πρωτεύουσα της Λιθουανίας το 1919-1939.", "795fab27"]},
"OLAYLAR_EK16:1944-08-25:0":{"b": ["Το Τάρτου καταλήφθηκε από τον Κόκκινο Στρατό — Επιχείρηση του Τάρτου", "cc8069ab"], "d": ["Το 3ο Μέτωπο της Βαλτικής διέλυσε την άμυνα της γερμανικής 18ης Στρατιάς και κατέλαβε το Τάρτου· η πόλη παρέμεινε για μερικές εβδομάδες στη γραμμή του μετώπου και η Επιχείρηση του Τάρτου έληξε στις 6 Σεπτεμβρίου 1944.", "3e9ef2ba"]},
"OLAYLAR_EK16:1944-09-22:0":{"b": ["Ο Κόκκινος Στρατός μπήκε στο Ταλίν — οι γερμανικές δυνάμεις εγκατέλειψαν την πόλη", "41ae1ec5"], "d": ["Κατά την Επιχείρηση του Ταλίν οι Γερμανοί εγκατέλειψαν την πόλη· η κυβέρνηση της Εθνικής Επιτροπής της Εσθονίας, που στις 18 Σεπτεμβρίου κατέλαβε τα κυβερνητικά κτίρια, δεν μπόρεσε να διατηρήσει τη διοίκηση καθώς ο Κόκκινος Στρατός έμπαινε. Η Εσθονία περιήλθε ξανά σε σοβιετική διοίκηση.", "a229e09c"]},
"OLAYLAR_EK16:1945-01-28:0":{"b": ["Ο Κόκκινος Στρατός κατέλαβε το Μέμελ (Κλαϊπέντα)", "d01ad3dc"], "d": ["Στη σοβιετική επιχείρηση προς την Ανατολική Πρωσία και την ακτή της Βαλτικής, το λιμάνι του Μέμελ (Κλαϊπέντα) ελήφθη από τη Γερμανία και υπήχθη στη Λιθουανική ΣΣΔ. Η περιοχή που είχε παραχωρηθεί στη Γερμανία το 1939 βγήκε έτσι από τη γερμανική διοίκηση.", "65cf6a00"]},
"OLAYLAR_EK16:1945-05-08:0":{"b": ["Η Τσέπη της Κουρλάνδης παραδόθηκε — η Courland Army Group υπέγραψε παράδοση στον Γκοβόροφ", "3c88889b"], "d": ["Η γερμανική Ομάδα Στρατιών Κουρλάνδης, που από τον Οκτώβριο του 1944 ήταν περικυκλωμένη γύρω από τη Λιεπάγια-Βεντσπίλς, παραδόθηκε· η δυτική Λετονία πέρασε σε σοβιετικό έλεγχο.", "a7bfcc52"]},
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Οι δυνάμεις του Σουλτάνου του Ομάν εισήλθαν στα κύρια κέντρα του εσωτερικού Ομάν· η ιμαμάτη των Ιμπαδιτών έληξε de facto", "9a9962a5"], "d": ["Τον Δεκέμβριο του 1955 ο Σουλτάνος του Ομάν κινήθηκε για να αποκαταστήσει την εξουσία του και οι δυνάμεις του εισήλθαν στα κύρια κέντρα κατοίκησης του εσωτερικού Ομάν (Μπαχλά, Ιζκί, Νιζβά)· η διοίκηση της ιμαμάτης των Ιμπαδιτών επί του εσωτερικού Ομάν έληξε de facto. Η πηγή δίνει μόνο τον μήνα· στον χάρτη εμφανίζεται η 1η Δεκεμβρίου 1955.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Το Κουβέιτ βγήκε από το βρετανικό προτεκτοράτο και απέκτησε πλήρη ανεξαρτησία", "e9a86d04"], "d": ["Με τις διακοινώσεις που ανταλλάχθηκαν στις 19 Ιουνίου 1961 μεταξύ Κουβέιτ και Ηνωμένου Βασιλείου, το βρετανικό προτεκτοράτο που διαρκούσε από τη συμφωνία του 1899 έληξε και το Κουβέιτ έγινε πλήρως ανεξάρτητο. Στον χάρτη το βρετανικό στρώμα στο Κουβέιτ λήγει αυτή την ημέρα.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Το Κατάρ ανακήρυξε την ανεξαρτησία του με τη λήξη των συνθηκών με τη Βρετανία", "8f288cc6"], "d": ["Μετά τη λήξη των συνθηκών προτεκτοράτου με τη Μεγάλη Βρετανία, το Κατάρ ανακήρυξε την ανεξαρτησία του στις 3 Σεπτεμβρίου 1971. Στον χάρτη το βρετανικό στρώμα στη Ντόχα λήγει αυτή την ημέρα.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Τα φρούρια της Ιστράντζας: κατάκτηση των Πινάρχισαρ, Κιρκλισέ (Κιρκλαρέλι) και Βίζε", "c6b1a9c1"], "d": ["Ο Μουράτ Α΄, που πέρασε τον χειμώνα του 1369 στο Παλάτι της Αδριανούπολης, την άνοιξη κινήθηκε ξανά εναντίον του Βυζαντίου και κατέλαβε τα φρούρια Πινάρχισαρ, Κιρκλισέ και Βίζε στους πρόποδες των βουνών της Ιστράντζας. Οι κατακτήσεις αυτές προκάλεσαν πανικό στην Κωνσταντινούπολη και ο αυτοκράτορας Ιωάννης Ε΄ αποφάσισε να μεταβεί στον πάπα για να ζητήσει βοήθεια.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Η Τασκένδη περιήλθε στη διοίκηση του χάνου του Μογγολιστάν Γιουνούς Χαν", "a37ee010"], "d": ["Κατά τον αγώνα για τον θρόνο μεταξύ των Τιμουριδών πριγκίπων, η Τασκένδη και τα περίχωρά της περιήλθαν στον χάνο του Ανατολικού Τσαγατάι (Μογγολιστάν) Γιουνούς Χαν. Όταν δύο χρόνια αργότερα πέθανε ο Γιουνούς Χαν, τον διαδέχθηκε ο γιος του Μαχμούτ Χαν· η πόλη έμεινε στους Μογγόλους χάνους έως ότου το 1503 την πήραν οι Ουζμπέκοι του Σεϊμπανί Χαν.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Ο Μπαμπούρ άφησε τη Φεργκανά στους Ουζμπέκους και πήγε στην Καμπούλ", "69df593c"], "d": ["Ο Τιμουρίδης Μπαμπούρ, γιος του Ουμάρ Σεΐχ Μίρζα, μετά τους πολέμους με τον Μουχαμμάντ Σεϊμπανί Χαν άφησε στους Ουζμπέκους τη Φεργκανά, όπου βασίλευε από το 1494, και διασχίζοντας τον Ινδοκαυκάσιο εγκαταστάθηκε στην Καμπούλ.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Ο Πιρί Ρέις σχεδίασε τον αρχαιότερο σωζόμενο παγκόσμιο χάρτη", "6ef941f5"], "d": ["Ο Πιρί Ρέις σχεδίασε στην Καλλίπολη τον παγκόσμιο χάρτη του έτους 919 της Εγίρας (1513)· σύμφωνα με την Ισλαμική Εγκυκλοπαίδεια του TDV, ανάμεσα στις πηγές του χάρτη περιλαμβάνονται «παλιοί χάρτες που έφτασαν σε αυτόν από τον ανατολικό και τον δυτικό κόσμο και ο χάρτης του Χριστόφορου Κολόμβου» — δηλαδή θεωρείται ότι φέρει ίχνη του πρωτότυπου ναυτικού χάρτη του Κολόμβου, που εκείνη την εποχή θεωρούνταν χαμένος. Παρουσίασε τον χάρτη στον Γιαβούζ Σουλτάνο Σελίμ στο Κάιρο το 923 (1517). Έχει σωθεί μόνο ένα τμήμα του που δείχνει τις δυτικές/ατλαντικές ακτές (Ισπανία, Πορτογαλία, Δυτική Αφρική, ανατολική ακτή της Νότιας Αμερικής)· το τμήμα αυτό ανακαλύφθηκε εκ νέου στο Παλάτι Τοπκαπί το 1929 και περιλαμβάνεται στον κατάλογο Μνήμη του Κόσμου της UNESCO.", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Η ενοποίηση της περιοχής του Καρς: η ένταξη των Σιρεγκέλ, Αρπατσάι και Ντιγκόρ στην οθωμανική διοίκηση", "10f16b5c"], "d": ["Κατά την Εκστρατεία των Δύο Ιράκ τα φρούρια Πασίν, Σιρεγκέλ και Ολτού περιήλθαν στους Οθωμανούς· είναι πολύ πιθανό ότι το Φρούριο του Καρς συνδέθηκε επίσης εκείνη την περίοδο. Η περιοχή του Αρπατσάι και του Ντιγκόρ, στα βόρεια και ανατολικά του Καρς, περιήλθε με την ίδια επιχείρηση υπό οθωμανικό έλεγχο.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Το τέλος των Σιρβανσάχ: ο Ελκάς Μίρζα αιχμαλώτισε τον Σαχρούχ, η Σιρβάν έγινε σαφαβιδική επαρχία", "e6d64114"], "d": ["Ο Ελκάς Μίρζα, που εστάλη από τον Σαχ Ταχμάσπ, λεηλάτησε τη Σιρβάν και κατέλαβε το Φρούριο του Μπαϊκούρντ και αιχμαλωτίζοντας τον δεκαπεντάχρονο Σιρβανσάχ Σαχρούχ τον οδήγησε στην Ταυρίδα. Η διοίκηση των Σιρβανσάχ, που επί μακρόν διατηρούσε την κυριαρχία στην περιοχή, έληξε έτσι· η Σιρβάν έγινε επαρχία του Σαφαβιδικού Κράτους.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Η επέκταση του Οτζακίου του Αλγερίου προς τη Σαχάρα — υποτέλεια του Τουγκούρτ-Ουαργκλά, οριστική κατάκτηση της Τλεμσέν", "705ec920"], "d": ["Σύμφωνα με το λήμμα Τλεμσέν του TDV, ένας μεγάλος στρατός που εστάλη από το Αλγέρι το 960 (1553) υπό τη διοίκηση του Σαλίχ Ρέις κατέλαβε οριστικά την πόλη και έβαλε τέλος στη τρεις αιώνων δυναστεία των Ζαγιανιδών. Την ίδια περίοδο (1552) ο Σαλίχ Ρέις οργάνωσε εκστρατεία εναντίον των ανεξάρτητων σουλτανάτων Τουγκούρτ και Βαργλά· οι οθωμανικές δυνάμεις κατέλαβαν το Τουγκούρτ, προέλασαν στη Βαργλά και τα δύο σουλτανάτα έγιναν φόρου υποτελή· στη Μπισκρά, στον δρόμο, αφέθηκε μόνιμη οθωμανική φρουρά. Έτσι τα σύνορα του Οτζακίου του Αλγερίου ξεπέρασαν για πρώτη φορά τον Άτλαντα του Τελ και έφτασαν στην ακτή της Σαχάρας. Η μεγάλη μάχη μπροστά στο Μουσταγανέμ δεν έγινε φέτος, αλλά το 1558: ο Χασάν Πασάς νίκησε εκεί τον Ισπανό κόμη Αλκαουδέτε και έβαλε τέλος στις ισπανικές επιθέσεις στη Βόρεια Αφρική.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Η ίδρυση του Εγιαλετίου της Αβησσυνίας — η ακτή της Ερυθράς Θάλασσας περνά στην οθωμανική διοίκηση", "7dd470ec"], "d": ["Το εγιαλέτι, που ιδρύθηκε για να αποτραπεί η διείσδυση της Πορτογαλίας στην Ερυθρά Θάλασσα μέσω της Αβησσυνίας, ιδρύθηκε επίσημα, σύμφωνα με το λήμμα Εγιαλέτι της Αβησσυνίας του TDV, στις 15 Σααμπάν 962 (5 Ιουλίου 1555) και έδρα του σαντζακιού έγινε το Σεβακίν. Ο Οζντεμίρ Πασάς άρχισε τις επιχειρήσεις το φθινόπωρο του 1555· κατέλαβε τα νησιά Ντέχλακ που ελέγχουν το λιμάνι της Μασαουά και στις 2 Απριλίου 1557 την πόλη της Μασαουά και στη συνέχεια το Αρκίκο. Η συνέχεια της κατάκτησης προχώρησε με την ένταξη του εγιαλετίου του Τίγκρε το 1558 και του Ντεμπαρβά το 1559 στην οθωμανική κυριαρχία.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Ο Σεντεφκιάρ Μεχμέτ Αγάς διορίστηκε αρχιαρχιτέκτονας — ο αρχιτέκτονας του Τεμένους του Σουλτάν Αχμέτ", "27b66fce"], "d": ["Ο Μεχμέτ Αγάς, που είχε μπει στο παλάτι ως παιδομάζωμα από την πόλη Ιλμπασάν της Αλβανίας γύρω στο 1562-63, εκπαιδεύτηκε δίπλα στον Μιμάρ Σινάν και διορίστηκε αρχιαρχιτέκτονας της Οθωμανικής Αυτοκρατορίας στις 11 Οκτωβρίου 1606. Η Ισλαμική Εγκυκλοπαίδεια του TDV μεταφέρει ότι μια σύγχρονη πηγή τον περιγράφει ως «ήπιου χαρακτήρα, ταπεινό, άνθρωπο του λόγου του, ευσεβή και ευφυή». Ο Μεχμέτ Αγάς, που τρία χρόνια αργότερα θα ξεκινούσε με διαταγή του Αχμέτ Α΄ την ανέγερση του Τεμένους του Σουλτάν Αχμέτ, άφησε ευρύ έργο, από τις επισκευές στην Κάαμπα έως πολυάριθμες κρήνες και τζαμιά στην Κωνσταντινούπολη και την Αδριανούπολη. Ότι τα έξι μιναρέδες προκάλεσαν διαμάχη περί «ισότητας» με την Κάαμπα της Μέκκας είναι ευρέως διαδεδομένη λαϊκή αφήγηση· οι εγκυκλοπαιδικές πηγές δεν την επιβεβαιώνουν και χαρακτηρίζουν τη διάταξη μόνο ως «μέχρι τότε αδοκίμαστη».", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Ο νέος σουλτάνος Μουσταφά Α΄: ένας χλωμός και αφηρημένος «φυλακισμένος του κλουβιού» στον θρόνο", "c487b0d1"], "d": ["Ο Μουσταφά Α΄, που ανέβηκε στον θρόνο με τον θάνατο του Αχμέτ Α΄, ως ο πρώτος πρίγκιπας που άφησε ζωντανό ο αδελφός του είχε ζήσει επί χρόνια κλεισμένος στο παλάτι υπό αυστηρή επιτήρηση· η Ισλαμική Εγκυκλοπαίδεια του TDV τον περιγράφει ως «χλωμό, με αραιά γένια, με μεγάλα μαύρα μάτια και θολό βλέμμα» και σημειώνει ότι η μακρά αυτή φυλάκιση επιδείνωσε την ψυχολογική του κατάσταση. Στην πρώτη αυτή βασιλεία του, που διήρκεσε ενενήντα έξι ημέρες, δεν μπόρεσε να χειριστεί τις κρατικές υποθέσεις· αντίθετα, λέγεται ότι έβγαινε συχνά για κυνήγι, επισκεπτόταν το ναυπηγείο και μάλιστα έριχνε χρυσό στο νερό και παρακολουθούσε τα ψάρια. Οι γενίτσαροι και οι ουλεμάδες, θεωρώντας τον ακατάλληλο για την ηγεμονία, τον καθαίρεσαν στις 26 Φεβρουαρίου 1618 και έβαλαν στη θέση του τον δεκατετράχρονο ανιψιό του Οσμάν Β΄.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Το όνειρο ταξιδιού του Εβλιγιά Τσελεμπί — το «Σεγιαχάτ» αντί για «Σεφαάτ»", "2d863e22"], "d": ["Σύμφωνα με την Ισλαμική Εγκυκλοπαίδεια του TDV, ο Εβλιγιά Τσελεμπί συνδέει την αρχή της ταξιδιωτικής ζωής του, που θα διαρκούσε σαράντα χρόνια, με ένα όνειρο που είδε τη νύχτα της Ασούρα του μήνα Μουχαρράμ του έτους 1040 (19 Αυγούστου 1630): στο όνειρό του βλέπει τον Προφήτη στο τζαμί Αχί Τσελεμπί στην Κωνσταντινούπολη μαζί με πολυπληθή κοινότητα και, από τη συγκίνησή του, αντί να πει «σεφαάτ γιά Ρεσουλουλλάχ» λέει «σεγιαχάτ γιά Ρεσουλουλλάχ». Σύμφωνα με την αφήγηση, ο Προφήτης χαμογελώντας στο παραστράτημα αυτό της γλώσσας του δίνει το μήνυμα της μεσιτείας, του ταξιδιού και της προσκύνησης. Δεν παντρεύτηκε ποτέ και αφιέρωσε τη ζωή του σε αυτή την υπόσχεση του «ταξιδιού».", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Οι αντιφάσεις του Μουράτ Δ΄: ο σουλτάνος που αγαπούσε το ποτό και απαγόρευσε το ποτό, καρπός παλαιστή, αυτί συνθέτη", "3d2ea5e0"], "d": ["Στα πρώτα χρόνια του Μουράτ Δ΄, που ανέβηκε στον θρόνο σε ηλικία έντεκα ετών, καθοριστική ήταν η επιρροή της μητέρας του Κιοσέμ Σουλτάνας· η Ισλαμική Εγκυκλοπαίδεια του TDV μεταφέρει ότι η Κιοσέμ, φοβούμενη την τάση του γιου της προς την εξουσία, τον «παρέσυρε στη διασκέδαση, τον απασχολούσε με δώρα και εορτασμούς». Όταν σε ηλικία περίπου είκοσι ετών ανέλαβε de facto τη διοίκηση, ήταν ένας ψηλός, πλατύς στους ώμους, επιβλητικός ηγεμόνας — λέγεται ότι έπιανε έναν δυνατό άνδρα από τη ζώνη, τον σήκωνε και τον περιέφερε αρκετές φορές στο Χας Οντά. Η εντυπωσιακή αντίφαση που καταγράφει το TDV είναι η εξής: ο σουλτάνος, που λέγεται ότι απεχθανόταν τον καπνό και το όπιο, ήταν υπερβολικά εθισμένος στο ποτό, και παρ' όλα αυτά πριν από εκστρατεία απαγόρευσε τον καφέ, τον καπνό και αργότερα το ίδιο το ποτό· ταυτόχρονα διέθετε τόση γνώση μουσικής ώστε να συνθέτει σύμφωνα με την παράδοση των μακάμ.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Η πτήση του Λαγκαρί Χασάν Τσελεμπί με πύραυλο — αφήγηση της οποίας μόνη πηγή είναι ο Εβλιγιά Τσελεμπί", "1f02e3f2"], "d": ["Σύμφωνα με το Σεγιαχατνάμε του Εβλιγιά Τσελεμπί, ο Λαγκαρί Χασάν Τσελεμπί κατασκεύασε ενώπιον του Μουράτ Δ΄ στο Σαραϊμπουρνού μια συσκευή επτά πυραύλων με πενήντα οκάδες μπαρουτιού και, λέγοντας «Σουλτάνε μου, σε εμπιστεύομαι στον Θεό, πηγαίνω να μιλήσω με τον προφήτη Ιησού», ανέβηκε στον πύραυλο. Σύμφωνα με την αφήγηση, ο Χασάν Τσελεμπί ανυψώθηκε περίπου 250 μέτρα, γλίστρησε προς τη θάλασσα με όργανα που έμοιαζαν με φτερά γερακιού, κολύμπησε και επέστρεψε στον σουλτάνο και σε αντάλλαγμα έλαβε θέση σπαχή με ημερήσιο μισθό εβδομήντα ακτσέδων.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Ο Κεμανκές Κιαρά Μουσταφά Πασάς έγινε μέγας βεζίρης — άρχισε η περίοδος της οικονομικής μεταρρύθμισης", "583846a4"], "d": ["Ο Κεμανκές Κιαρά Μουσταφά Πασάς, που έγινε μέγας βεζίρης στις 17 του Σααμπάν 1048 (24 Δεκεμβρίου 1638) μετά τον θάνατο του Τάγιαρ Μεχμέτ Πασά στην Εκστρατεία της Βαγδάτης, εφάρμοσε στην περίοδο του σουλτάνου Ιμπραήμ αυστηρή οικονομική πειθαρχία: μείωσε στο ένα τρίτο τον αριθμό των γενιτσάρων και των σπαχήδων, διόρθωσε τον τίτλο των νομισμάτων και έσφιξε το σύστημα των τιμών (ναρχ). Με τον αριθμό που δίνει το TDV, η εξοικονόμηση αυτή έφτασε τα 6000 κεσέδες τον χρόνο — όμως ο αυστηρός αυτός έλεγχος του δημιούργησε εχθρούς στους κύκλους του παλατιού.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Ο Μουσταφά Α΄ πέθανε έπειτα από δεκαπέντε χρόνια λησμονιάς", "b4c872cd"], "d": ["Ο Μουσταφά Α΄, που καθαιρέθηκε για δεύτερη φορά στις 10 Σεπτεμβρίου 1623, έζησε επί δεκαπέντε χρόνια έως τον θάνατό του σε ένα δωμάτιο όπου κρατούνταν κλεισμένος· για τα χρόνια αυτά δεν υπάρχει καμία πληροφορία στις πηγές. Πέθανε στις 15 του Ραμαζανιού 1048 (20 Ιανουαρίου 1639) — μέρος των πηγών το θεωρεί φυσικό θάνατο, ενώ μέρος υποστηρίζει ότι είχε το χέρι του ο Μουράτ Δ΄.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«Τρελός Ιμπραήμ» ή μια διακυμαινόμενη ασθένεια;", "2abc230f"], "d": ["Η Ισλαμική Εγκυκλοπαίδεια του TDV απορρίπτει ρητά τον χαρακτηρισμό «Τρελός Ιμπραήμ» που διαδόθηκε τον 20ό αιώνα· μεταφέρει ότι ο σουλτάνος στις δικές του επιστολές παραπονιόταν για πόνους, έλλειψη όρεξης, αδυναμία στα πόδια, αίσθηση ομίχλης στο κεφάλι, σφίξιμο στο στήθος και κρίσεις λιποθυμίας. Αντίθετα, οι συνεπείς και λογικές απαντήσεις του κατά τη διαδικασία της καθαίρεσης έρχονται σε αντίφαση με τον ισχυρισμό μόνιμης ψυχικής αστάθειας· καταλήγει στο συμπέρασμα ότι η κατάστασή του ακολουθούσε πορεία «όχι σταθερή, με μεταβαλλόμενη ένταση». Την περίοδο αυτή οι ευθύνες της Κιοσέμ Σουλτάνας αυξάνονταν σταδιακά και ο Τζιντζί Χότζα, που κλήθηκε στο παλάτι, προσφέροντας στον σουλτάνο πνευματική παρηγοριά με «αποτελεσματικές προσευχές», αύξησε τη δύναμή της να παρεμβαίνει στην πολιτική.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Το Επεισόδιο της Ζιβελίνας — ο φόρος γούνας του Μεγάλου Βεζίρη Αχμέτ Πασά προετοίμασε το τέλος του Ιμπραήμ", "a2a47d62"], "d": ["Ενώ η μανία του σουλτάνου Ιμπραήμ για γούνες ζιβελίνας και αμπάρι μεγάλωνε στο παλάτι, ο Μεγάλος Βεζίρης Αχμέτ Πασάς γύρω στο 1647-1648 ξεκίνησε μια πρακτική που εισέπραττε με το ζόρι από τους κρατικούς αξιωματούχους την αξία γούνας ζιβελίνας· η Ισλαμική Εγκυκλοπαίδεια του TDV καταγράφει ότι οι αξιωματούχοι το έβλεπαν ως ξεκάθαρο «χαράτσι». Όταν οι αξιωματικοί των γενιτσάρων αρνήθηκαν συλλογικά να πληρώσουν, η αντίσταση αυτή έγινε ο άμεσος πυροδότης της διαδικασίας που οδήγησε στην καθαίρεση του σουλτάνου — το πρωί της 7ης Αυγούστου 1648 οι συγκεντρωμένοι αξιωματούχοι σκότωσαν πρώτα τον Αχμέτ Πασά και την επομένη καθαίρεσαν τον Ιμπραήμ.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["«Το κράτος το διοικούν γυναίκες» — η εξέγερση του Βαρβάρ Αλή Πασά από τη Σεβάστεια", "5b027357"], "d": ["Ο μπεηλέρμπεης της Σεβάστειας Βαρβάρ Αλή Πασάς αρνήθηκε να πληρώσει τα 30.000 γρόσια που ζητούσε η Κωνσταντινούπολη με το όνομα «μπαϊραμιγιέ», λέγοντας «το ετήσιο εισόδημα της Σεβάστειας δεν καλύπτει αυτό το ποσό»· σύμφωνα με την Ισλαμική Εγκυκλοπαίδεια του TDV, η αιτιολογία της εξέγερσής του ήταν ο ισχυρισμός ότι, λόγω της ασθένειας του σουλτάνου, οι κρατικές υποθέσεις είχαν περάσει στα χέρια γυναικών και ότι αυτό προκαλούσε αστάθεια με τις συχνές αλλαγές διοικητών. Αν και τον Μάιο του 1648 πέτυχε αρχικά στρατιωτική επιτυχία, ηττήθηκε από τον Ιπσίρ Μουσταφά Πασά, εκτελέστηκε στις 20 Μαΐου 1648 και το κεφάλι του στάλθηκε στην Κωνσταντινούπολη.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Η απώλεια του Ανάπλιου (Ναύπλιο) από τη Βενετία — κομβικό σημείο του Πολέμου του Μοριά", "9d400557"], "d": ["Σύμφωνα με το λήμμα Αναμπολού του TDV, όσοι από τον μουσουλμανικό πληθυσμό της πόλης επέζησαν κατά την πολιορκία κατέφυγαν στα γειτονικά νησιά και στην Ανατολία (1686). Σύμφωνα με την πρότυπη ακαδημαϊκή πηγή (Setton, Venice, Austria, and the Turks in the Seventeenth Century), οι δυνάμεις του Κένιγκσμαρκ απέκρουαν επί δύο εβδομάδες τις επιθέσεις του οθωμανικού στρατού ανακούφισης· όταν η επίθεση του Ισμαήλ Πασά στις 29 Αυγούστου κατέληξε σε βαριά ήττα, το φρούριο παραδόθηκε μέσα σε λίγες ημέρες. Το Ανάπλι ήταν οθωμανικό έδαφος που είχε παραληφθεί με συνθήκη το 1540· με την απώλειά του επιταχύνθηκε το πέρασμα της χερσονήσου του Μοριά στη Βενετία.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Ο Μεχμέτ Δ΄ εγκατέλειψε το κυνήγι — η τελευταία προσπάθεια παραμονή της καθαίρεσής του", "7daa904b"], "d": ["Μετά την ήττα του Μοχάτς (Αύγουστος 1687) ο στρατός, του οποίου δεν πληρώθηκε το ουλουφέ, εξεγέρθηκε και βάδισε προς την Κωνσταντινούπολη. Ο Μεχμέτ Δ΄ έβαλε να θανατώσουν τον Σουλεϊμάν Πασά, που είχε διαφύγει με τη σφραγίδα του μεγάλου βεζίρη, και έδειξε το κεφάλι του στον στρατό και, διαλύοντας τα σύνεργα του κυνηγιού και τα λαγωνικά του, δήλωσε ότι μετανοεί — όμως η χειρονομία αυτή δεν αρκούσε για να σώσει τον θρόνο του και λίγους μήνες αργότερα καθαιρέθηκε.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Παράδοση του φρουρίου του Μουνκάτς (Μουκατσέβε) στην Αυστρία μετά από τριετή πολιορκία", "ca2efc3d"], "d": ["Το φρούριο του Μουνκάτς, που πολιορκήθηκε από αυτοκρατορικές δυνάμεις στα τέλη του 1685, αντιστάθηκε επί τρία χρόνια υπό τη διοίκηση της Ιλόνα Ζρίνι, συζύγου του Ίμρε Τέκελι· σύμφωνα με πολλά δημοσιευμένα έργα αναφοράς, το φρούριο παραδόθηκε στις 17 Ιανουαρίου 1688 στον στρατηγό Αντόνιο Καράφα. Ήταν η πτώση ενός από τα τελευταία μεγάλα φρούρια της φιλοοθωμανικής αντίστασης στην Ουγγαρία στο οθωμανο-αψβουργικό μέτωπο.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Ο Μπαλτατζί Μεχμέτ Πασάς και η αφήγηση για την τσαρίνα Αικατερίνη", "c1b739f1"], "d": ["Η λαϊκή αφήγηση που αποδίδει τη σωτηρία του πολιορκημένου στον Προυτ ρωσικού στρατού στα δώρα/τη δωροδοκία που έστειλε η Αικατερίνη Α΄ στον Μπαλτατζί Μεχμέτ Πασά επαναλαμβανόταν επί αιώνες.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["Η συζήτηση για την «χαμένη ευκαιρία» στον Προυτ — δύο απόψεις", "61ee699c"], "d": ["Ότι, ενώ ο οθωμανικός στρατός είχε περικυκλώσει πλήρως τον ρωσικό στρατό, περιορίστηκε σε ειρήνη, έγινε αμέσως μετά τη συνθήκη θέμα συζήτησης μεταξύ των ιστορικών — με τη δική του διατύπωση του TDV, «έγινε κατανοητό ότι χάθηκε μια μεγάλη ευκαιρία και η θέση αυτή υποστηρίχθηκε έντονα από όσους είχαν αντίθετη γνώμη.» Σύμφωνα με τους επικριτές, ο τσάρος μπορούσε να αιχμαλωτιστεί και τα όπλα του ρωσικού στρατού να παραληφθούν· σύμφωνα με τους υπερασπιστές, αντίθετα, για να αποτραπεί η ενίσχυση της Σουηδίας στη Βόρεια Ευρώπη, η περιορισμένη αποδυνάμωση της Ρωσίας ήταν «σοφότερη πολιτική». Το TDV μεταφέρει και τις δύο απόψεις και δεν παίρνει θέση.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Ιδρύθηκε επιτροπή λογίων/μεταφραστών τριάντα δύο ατόμων", "0e3a713c"], "d": ["Στην περίοδο του μεγάλου βεζίρη Νταμάτ Ιμπραήμ Πασά ιδρύθηκε στην Κωνσταντινούπολη, κατά την έκφραση του TDV, μια επιτροπή λογίων-γραμματέων τριάντα δύο ατόμων που «θα μπορούσε να θεωρηθεί η ακαδημία της εποχής». Η επιτροπή μετέφερε στα τουρκικά έργα ιστορίας, φιλοσοφίας και γεωγραφίας από τα αραβικά, περσικά, ελληνικά και λατινικά — ανάμεσά τους ήταν η μετάφραση της Φυσικής του Αριστοτέλη από τον Γιαννιώτη Εσάτ Εφέντη με ομάδα είκοσι πέντε ατόμων και η προεδρία του ποιητή Νεντίμ σε επιτροπή μετάφρασης ιστορίας. Η ημέρα δεν αναφέρεται στο TDV, το έτος δηλώνεται.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Ο Μαχμούτ Α΄ προσκάλεσε τον Πατρονά Χαλίλ στο παλάτι και τον παγίδευσε", "6147059f"], "d": ["Επτά εβδομάδες μετά την άνοδό του στον θρόνο, ο Μαχμούτ Α΄, μέσω των έμπιστων ανθρώπων του — μέσα στο παλάτι ο Χατζή Μπεσίρ Αγάς, έξω ο Χάνος της Κριμαίας Α΄ Καπλάν Γκιράι —, προσεταιρίστηκε τους προύχοντες του στρατού και έσπασε την επιρροή του Πατρονά Χαλίλ. Στις 25 Νοεμβρίου 1730 ο Πατρονά Χαλίλ, ο Μουσλού Μπεσέ και ο Κελ Μεχμέτ Αγάς, που κλήθηκαν σε σύσκεψη στο Δωμάτιο της Περιτομής στο Παλάτι Τοπκαπί, εισήλθαν· με νεύμα του μεγάλου βεζίρη Σιλαχντάρ Μεχμέτ Πασά εμφανίστηκαν τριάντα δύο ένοπλοι άνδρες που είχαν κρυφτεί εκ των προτέρων και σκότωσαν και τους τρεις. Ο Μαχμούτ Α΄ κατέλαβε έτσι πλήρως τον έλεγχο της εξέγερσης.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Ο Χουμπαρατζί Αχμέτ Πασάς (Μπονβάλ) τέθηκε επικεφαλής του Σώματος των Χουμπαρατζήδων", "27b0b1d7"], "d": ["Ο αξιωματικός γαλλικής καταγωγής, με πραγματικό όνομα Κλοντ-Αλεξάντρ κόμης ντε Μπονβάλ, αφού υπηρέτησε αρχικά στους στρατούς της Γαλλίας και της Αυστρίας, ασπάστηκε το Ισλάμ στο Σεράγεβο, πήρε το όνομα Αχμέτ και το 1729 κατέφυγε στο Οθωμανικό Κράτος. Ο Αχμέτ Πασάς, που τέθηκε το 1731 στην περίοδο του Μαχμούτ Α΄ επικεφαλής του Σώματος των Χουμπαρατζήδων, εκπαίδευσε σε στρατώνα που έστησε στο Αγιάσμα του Ουσκουντάρ περίπου 300 στρατιώτες που έφερε από τη Βοσνία· ο αριθμός τους σύντομα ξεπέρασε τους 600 και ο ίδιος δίδαξε και μαθήματα μαθηματικών. Η απόπειρα εξέγερσης που επιχείρησε στην Ουγγαρία με τον Ράκοτσι υπέρ της Γαλλίας κλόνισε την επιρροή του και το 1738 εξορίστηκε στην Καστάμονου. Πέθανε στην Κωνσταντινούπολη στις 23 Μαΐου 1747 και ο τάφος του βρίσκεται στο νεκροταφείο του Μεβλεβιχανέ του Γαλατά.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Η ανάκτηση της Σμεντερέβου από τους Αψβούργους (στέμμα του Βασιλείου της Ουγγαρίας) — Πόλεμος του 1737-39", "63dcf604"], "d": ["Σύμφωνα με το λήμμα Σμεντερέβο του TDV, το φρούριο που παραχωρήθηκε το 1717 στην Αυστρία με την Πασάροβιτς ανακτήθηκε με την οθωμανική προέλαση στο μέτωπο Δούναβη-Σάβα του Οθωμανοαυστριακού Πολέμου που άρχισε το 1737· οι δυνάμεις των Αψβούργων (στέμμα του Βασιλείου της Ουγγαρίας) κατάφεραν να κρατηθούν στην περιοχή έως τον Αύγουστο του 1738 και μετά από την ημερομηνία αυτή η Σμεντερέβο περιήλθε ξανά στην οθωμανική διοίκηση. Η Συνθήκη του Βελιγραδίου (18 Σεπτεμβρίου 1739), που υπογράφηκε ένα χρόνο αργότερα, θα επικύρωνε το κέρδος αυτό — μαζί με το Βελιγράδι και τη βόρεια Σερβία.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Η επιστροφή της κοιλάδας του Μοράβα στην οθωμανική διοίκηση — Γιαγκοντίνα, Κραγκούγιεβατς και Τσάτσακ", "b219d3c9"], "d": ["Με την ανάκτηση της Σμεντερέβου τον Αύγουστο του 1738 επέστρεψε στην οθωμανική διοίκηση και η κοιλάδα του Μοράβα που βρισκόταν ανάμεσα στη Σμεντερέβο και το κύριο σώμα των Οθωμανών: Γιαγκοντίνα, Κραγκούγιεβατς και Τσάτσακ θεωρούνται οθωμανικά από την ημερομηνία αυτή. Οι πηγές δεν χρονολογούν ούτε αναφέρουν ξεχωριστά την επιστροφή των τριών αυτών τόπων· ο χάρτης λειτουργεί με την ημέρα της Σμεντερέβου. Η Συνθήκη του Βελιγραδίου (18 Σεπτεμβρίου 1739) επικύρωσε την κατάσταση αυτή.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Ο Αμπντουλχαμίτ Α΄ υπέστη εγκεφαλικό και πέθανε διαβάζοντας την είδηση της πτώσης του Οζί", "6ac60365"], "d": ["Σύμφωνα με το λήμμα abdulhamid της Ισλαμικής Εγκυκλοπαίδειας του TDV, ο Αμπντουλχαμίτ Α΄, του οποίου η υγεία είχε επιδεινωθεί πολύ με τη βαριά πορεία του ρωσοαυστριακού πολέμου, πέθανε από ξαφνικό εγκεφαλικό ενώ διάβαζε το έγγραφο του μεγάλου βεζίρη που ανήγγελλε ότι το Φρούριο του Οζί είχε καταληφθεί από τους Ρώσους (11 Ρατζάμπ 1203 / 7 Απριλίου 1789). Η σορός του ετάφη στον τάφο που είχε ο ίδιος κατασκευάσει στο Μπαχτσεκαπί της Κωνσταντινούπολης. Την ίδια ημέρα ο ανιψιός του Σελίμ Γ΄ ανέβηκε στον θρόνο.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Οθωμανο-ρωσική Αμυντική Συμμαχία — κοινή άμυνα εναντίον της Γαλλίας", "c87079d1"], "d": ["Με την εισβολή του Ναπολέοντα στην Αίγυπτο, ο Σελίμ Γ΄ και ο Ρώσος Τσάρος Παύλος Α΄ συνήψαν αμυντική συμμαχία δεκατεσσάρων άρθρων και οκτώ ετών. Τα μέρη ανέλαβαν να έχουν κοινούς φίλους και εχθρούς, να παρέχουν αμοιβαία βοήθεια και να μη συνάπτουν χωριστή ειρήνη.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Οθωμανο-σικελική (Νάπολη) Αμυντική Συμμαχία — κοινός αγώνας εναντίον της Γαλλίας", "1d2be816"], "d": ["Ενόψει της γαλλικής κατοχής της Ιταλίας, της Μάλτας και της Αιγύπτου, το Οθωμανικό Κράτος και το Βασίλειο των Δύο Σικελιών συνήψαν αμυντική συμμαχία εννέα άρθρων. Τα μέρη ανέλαβαν να διεξάγουν κοινό πόλεμο, να μη συνάπτουν χωριστή ειρήνη και να παρέχουν το ένα στο άλλο βοήθεια από ξηρά και θάλασσα.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Ιδρύθηκε η Επτάνησος Πολιτεία — τα Ιόνια νησιά υπό ρωσο-οθωμανική προστασία", "08839694"], "d": ["Το 1799 ο κοινός ρωσο-οθωμανικός στόλος είχε εκδιώξει τους Γάλλους από τα Ιόνια νησιά (το φρούριο της Κέρκυρας έπεσε στις 5 Μαρτίου 1799)· με σύμβαση δώδεκα άρθρων της 21ης Μαρτίου 1800 τα νησιά συστάθηκαν ως Cezâyir-i Seb'a-i Müctemia Cumhuru (Επτάνησος Πολιτεία), αυτόνομη στα εσωτερικά και εξαρτημένη από την Οθωμανική Αυτοκρατορία στα εξωτερικά. Η περίοδος από την 5η Μαρτίου 1799 έως αυτή την ημέρα είναι περίοδος κοινής κατοχής.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Τιλσίτ — τα ρωσικά δικαιώματα επί της Επτανήσου Πολιτείας μεταβιβάστηκαν στη Γαλλία", "98a78beb"], "d": ["Με τη συμφωνία που επιτεύχθηκε στο Τιλσίτ μεταξύ Ρωσίας και Γαλλίας, η Ρωσία άφησε στη Γαλλία τα δικαιώματά της επί των Επτανήσων· γαλλικά στρατεύματα εγκαταστάθηκαν στα νησιά το καλοκαίρι του 1807 και η Επτάνησος Πολιτεία καταργήθηκε.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Η Αγία Μαύρα και τα Ιόνια νησιά περιέρχονται υπό βρετανική προστασία — τάξη μετά τον Ναπολέοντα", "0af821dc"], "d": ["Η Αγία Μαύρα και τα άλλα Ιόνια νησιά, που είχαν περάσει στη Γαλλία το 1797, μετά την οριστική ήττα του Ναπολέοντα αφέθηκαν υπό βρετανική προστασία με την ονομασία «Ηνωμένο Κράτος των Ιονίων Νήσων» με ιδιαίτερη συνθήκη που υπογράφηκε στο Παρίσι στις 5 Νοεμβρίου 1815 μεταξύ Αγγλίας, Ρωσίας, Αυστρίας και Πρωσίας — πρόκειται για έγγραφο ξεχωριστό από τη γενική Συνθήκη του Παρισιού της 20ής Νοεμβρίου 1815. Η προστασία θα διαρκούσε έως το 1864 και στη συνέχεια τα νησιά θα παραχωρούνταν στην Ελλάδα.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Η κατάκτηση του Πρίζρεν — οθωμανική έδρα σαντζακιού στο Κοσσυφοπέδιο", "f84c220f"], "d": ["Στις 4 Ρατζάμπ 859 (20 Ιουνίου 1455) ο οθωμανικός στρατός υπό τον Φατίχ Σουλτάν Μεχμέτ κατέλαβε το Πρίζρεν μετά τον πόλεμο με τον Σέρβο δεσπότη Γκιόργκι Μπράνκοβιτς — στις οθωμανικές πηγές Βιλκογλού. Η πόλη είχε περάσει στα μέσα του 13ου αιώνα από το Βυζάντιο στο Βασίλειο της Σερβίας και είχε γίνει βασιλική κατοικία στις περιόδους του βασιλιά Μιλούτιν, του τσάρου Ντούσαν και του βασιλιά Ούρος· μετά τον θάνατο του Ντούσαν η σημασία της μειώθηκε. Μετά την κατάκτηση έγινε έδρα σαντζακιού και διατήρησε την ιδιότητα αυτή επί τεσσεράμισι αιώνες έως το 1912. Το Πρίζρεν ήταν, πριν από τη διάλυση της Γιουγκοσλαβίας, η μόνη πόλη των Βαλκανίων όπου μιλιούνταν μαζί οι τρεις γλώσσες — αλβανικά, τουρκικά και σερβικά.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Η πτώση της Βαστίλης — η αρχή της Γαλλικής Επανάστασης", "96e931f1"], "d": ["Εν μέσω της οργής που προκάλεσε η καθαίρεση του υπουργού Οικονομικών Νεκέρ από τον βασιλιά Λουδοβίκο ΙΣΤ΄ (11 Ιουλίου 1789) και της οικονομικής κρίσης, ο λαός του Παρισιού βάδισε προς το φρούριο της Βαστίλης ζητώντας όπλα και μπαρούτι. Στη σύγκρουση που άρχισε το απόγευμα, με περισσότερους από τρεις χιλιάδες εξεγερμένους απέναντι σε μόλις εκατό περίπου φρουρούς, το φρούριο παραδόθηκε γύρω στις 17:00· σκοτώθηκαν μερικοί αξιωματούχοι, μεταξύ αυτών ο διοικητής του φρουρίου Μπερνάρ-Ρενέ ντε Λονέ, και ελευθερώθηκαν επτά κρατούμενοι. Το φρούριο, σχεδόν άδειο και που ήδη σχεδιαζόταν να κατεδαφιστεί, ήταν σύμβολο της βασιλικής τυραννίας — για την πτώση του λέγεται ότι ανακοινώθηκε στον Λουδοβίκο ΙΣΤ΄ ως «Όχι, κύριε, αυτό δεν είναι εξέγερση, είναι επανάσταση». Η 14η Ιουλίου είναι σήμερα η εθνική εορτή της Γαλλίας και το γεγονός θεωρείται η συμβολική αρχή του λαϊκού κινήματος που σύντομα εξαπλώθηκε σε όλη τη χώρα και της Γαλλικής Επανάστασης (1789-1799) — η επανάσταση, στην επόμενη δεκαετία, ανατρέποντας την απόλυτη μοναρχία, θα άλλαζε μόνιμα τον πολιτικό χάρτη της Ευρώπης και τις διεθνείς ισορροπίες, στις οποίες συμπεριλαμβανόταν και η Οθωμανική Αυτοκρατορία.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Ο στρατός των Μαμελούκων εισήλθε στη Μελιτηνή — η πόλη πέρασε από τους Ιλχανίδες στη διοίκηση των Μαμελούκων", "2540363d"], "d": ["Οι Μαμελούκοι έστειλαν εναντίον της Μελιτηνής στρατό υπό τον αντιβασιλέα της Δαμασκού Σεϊφεντίν Τενγκίζ· ο στρατός εισήλθε στην πόλη στις 22 Μουχαρράμ 715 (28 Απριλίου 1315). Η Μελιτηνή ήταν μέχρι τότε υπό ιλχανική κυριαρχία και ήταν το κομβικό σημείο της γραμμής όπου εφάπτονταν οι σφαίρες επιρροής των Ιλχανίδων και των Μαμελούκων δυτικά του Ευφράτη. Η αλλαγή χεριών της πόλης δείχνει την προέλαση των Μαμελούκων προς τον Άνω Ευφράτη στη μακρά διαμάχη μεταξύ των δύο κρατών. Η Μελιτηνή από την ημερομηνία αυτή θα περνούσε για ένα διάστημα στη διοίκηση των Ερετναογουλλαρί και από το 1338 θα επέστρεφε πάλι στην κυριαρχία των Μαμελούκων.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Το τέλος του Μπεηλικίου των Εσρεφογουλλαρί — Μπεϊσεχίρ και Σεϊντισεχίρ περνούν στους Χαμιντογουλλαρί", "e4e70846"], "d": ["Ο Ντεμιρτάς, γιος του Εμίρ Τσομπάν, γενικού διοικητή της Ανατολίας του Ιλχανικού Κράτους, κινήθηκε εναντίον των τουρκμενικών μπεηλικίων που είχαν ανακηρύξει την ανεξαρτησία τους και μπαίνοντας στο Μπεϊσεχίρ έβαλε να σκοτώσουν τον Εσρεφογλού Σουλεϊμάν Σαχ, που κάποτε τον είχε καταγγείλει (9 Οκτωβρίου 1326). Το Μπεηλίκι των Εσρεφογουλλαρί, που είχε ιδρυθεί στα τέλη του 13ου αιώνα στην περιοχή Μπεϊσεχίρ και Σεϊντισεχίρ, έληξε έτσι. Το λήμμα Χαμιντογουλλαρί του TDV δίνει τη συνέχεια: το Μπεϊσεχίρ, το Σεϊντισεχίρ, το Ακσεχίρ και το Ντογανχισάρ, που ανήκαν στους Εσρεφογουλλαρί τους οποίους εξάλειψε ο Ντεμιρτάς, προσαρτήθηκαν στα σύνορα του μπεηλικίου των Χαμίντ. Την ίδια χρονιά ο Χαμιντογλού Ντουντάρ Μπέης παραδόθηκε επίσης στον Ντεμιρτάς και θανατώθηκε. Τα εδάφη αυτά θα πωλούνταν το 1381 στον Μουράτ Α΄ έναντι 80.000 χρυσών και θα περνούσαν στην οθωμανική διοίκηση.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Η Μελιτηνή περιήλθε ξανά στην κυριαρχία των Μαμελούκων — τέλος της διοίκησης των Ερετναογουλλαρί", "08b80aa2"], "d": ["Η Μελιτηνή, που είχε περάσει στη διοίκηση των Μαμελούκων το 1315, στα χρόνια της διάλυσης του Ιλχανικού Κράτους είχε περάσει για ένα διάστημα στα χέρια των Ερετναογουλλαρί. Το λήμμα Μελιτηνή του TDV δίνει την επιστροφή με μία πρόταση: από το 1338 την πόλη κυριάρχησαν πάλι οι Μαμελούκοι. Αυτό είναι ένα στιγμιότυπο των χρόνων που το μεταϊλχανικό κενό στη νοτιοανατολική Ανατολία μοιραζόταν μεταξύ Μαμελούκων και Ερετνά.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Απώλεια του λιμανιού της Σμύρνης στον στόλο των Σταυροφόρων — κάμφθηκε η ναυτική δύναμη των Αϊδινογουλλαρί", "775c65fe"], "d": ["Ο στόλος των Σταυροφόρων, που αποτελούνταν από πλοία της Βενετίας, της Γένοβας, του Βασιλείου της Κύπρου, των Ιπποτών της Ρόδου και του δούκα της Νάξου με την ενθάρρυνση του πάπα Κλήμη ΣΤ΄, πήρε το λιμάνι της Σμύρνης από τους Αϊδινογουλλαρί (28 Οκτωβρίου 1344). Το λιμάνι είχε ληφθεί το 1328-1329 από τον Μεχμέτ Μπέη, πατέρα του Ουμούρ Μπέη, από τον Γενοβέζο Μαρτίνο Τζακαρία και ήταν η βάση της ναυτικής δύναμης των Αϊδινογουλλαρί στο Αιγαίο. Τον Σεπτέμβριο του 1334 ένας στόλος Σταυροφόρων που είχε έρθει με τον ίδιο σκοπό είχε αναγκαστεί να υποχωρήσει· η δεύτερη αυτή εκστρατεία πέτυχε. Ο Ουμούρ Μπέης συνέχισε την αντίσταση και, ενωμένος με τα άλλα τουρκικά μπεηλίκια, νίκησε τον στόλο των Σταυροφόρων στις 17 Ιανουαρίου 1345, αλλά το λιμάνι δεν ανακτήθηκε.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Ο Καραμανογλού Αλαεντίν Μπέης προσάρτησε στα εδάφη των Καραμάν το Ικόνιο, το Ακσεράι και το Νίγδε", "2b8b0f70"], "d": ["Ο Καραμανογλού Αλαεντίν Μπέης, θέλοντας να επωφεληθεί από το γεγονός ότι το Σουλτανάτο των Μαμελούκων έβαλε τέλος στο Βασίλειο της Αρμενίας και προσάρτησε ολόκληρη την Κιλικία και από τις αναταραχές στο Κράτος των Ερετνά στην Κεντρική Ανατολία, προσάρτησε στα εδάφη των Καραμάν, κυρίως το Ικόνιο (1366-1367), καθώς και το Νίγδε Καραχισάρι (Γιεσιλχισάρ), το Ακσεράι, το Ακσεχίρ, το Ιλγκίν, το Ισχακλί και την Καισάρεια. Το Ικόνιο, λόγω του βάρους που έφερε ως πρωτεύουσα των Σελτζούκων, ήταν για τους Καραμανογουλλαρί όχι απλώς μια πόλη, αλλά διεκδίκηση νομιμότητας.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Ο Ουζούν Χασάν τερμάτισε το Κράτος των Καρακογιουνλού — η λεκάνη της λίμνης Βαν περιήλθε στους Ακκογιουνλού", "d8d6c2e8"], "d": ["Ο ηγεμόνας των Ακκογιουνλού Ουζούν Χασάν, πιάνοντας απροετοίμαστο τον αδυσώπητο εχθρό του, τον ηγεμόνα των Καρακογιουνλού Τζιχάν Σαχ, που βάδιζε εναντίον του το 1467, τερμάτισε το Κράτος των Καρακογιουνλού. Με την εξαφάνιση του Τζιχάν Σαχ, που βασίλευε από το 1438, η λεκάνη της λίμνης Βαν — Βαν, Μπιτλίς, Μπαργκιρί (Μουραντιγιέ), Χοσάπ και Κοτούρ — πέρασε από τους Καρακογιουνλού στη διοίκηση των Ακκογιουνλού. Η νίκη αυτή έκανε το Κράτος των Ακκογιουνλού τη μοναδική μεγάλη δύναμη στην Ανατολική Ανατολία και στο Ιράν και έβαλε τον Ουζούν Χασάν στον δρόμο που μια γενιά αργότερα θα τον έφερνε αντιμέτωπο με τους Οθωμανούς.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Ο Τζεμ Σουλτάν μεταφέρθηκε στη Ρώμη — διπλωματία ομήρου και 40.000 δουκάτα ετησίως", "1c6715a8"], "d": ["Ο πάπας Ιννοκέντιος Η΄, συμφωνώντας με τον Πιερ ντ' Ωμπυσόν, αρχηγό των Ιπποτών της Ρόδου, έφερε τον Τζεμ Σουλτάν στη Ρώμη (4 Μαρτίου 1489). Ο Τζεμ είχε καταφύγει στη Ρόδο στις 29 Ιουλίου 1482, από εκεί πέρασε σε εδάφη της Σαβοΐας και τελικά υπό παπική επιτήρηση. Ο Βαγιαζήτ Β΄ είχε δεχθεί να πληρώνει στους ιππότες 40.000 δουκάτα ετησίως και να τους παραχωρήσει δικαίωμα ελεύθερου εμπορίου στα οθωμανικά εδάφη με αντάλλαγμα να κρατούν τον αδελφό του υπό κράτηση. Η πληρωμή αυτή δεν ήταν φόρος υποτέλειας, αλλά το τίμημα για να διατηρείται ακίνητος στην Ευρώπη ο νόμιμος αντίπαλος για τον θρόνο: αν ο Τζεμ ελευθερωνόταν, θα μπορούσε να συγκεντρώσει στρατό στην Ανατολία και μάλιστα να γίνει πηγή νομιμότητας για μια σταυροφορία. Έτσι ένα δυναστικό ζήτημα έγινε επί τριάντα χρόνια ο κύριος περιορισμός της οθωμανικής εξωτερικής πολιτικής — αυτός είναι ο λόγος που ο Βαγιαζήτ ενεργούσε επιφυλακτικά στη Δύση. Με τον θάνατο του Τζεμ το 1495 ο περιορισμός αυτός αίρεται.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Το Βασίλειο της Γεωργίας διαιρέθηκε σε τρία — Καρτλί, Κακέτι και Ιμερέτι με κέντρο το Κουταΐσι", "f9c5f798"], "d": ["Το ενιαίο Βασίλειο της Γεωργίας, που κυβερνούσε η δυναστεία των Μπαγκρατιδών, μετά από μακρά εσωτερική διαμάχη διαιρέθηκε επίσημα σε τρία βασίλεια: στα ανατολικά το Καρτλί με κέντρο την Τιφλίδα, στα βορειοανατολικά το Κακέτι και στα δυτικά το Ιμερέτι με κέντρο το Κουταΐσι. Το λήμμα Γεωργία του TDV επιβεβαιώνει τη διαίρεση — «η Γεωργία διαιρέθηκε σε τρία βασίλεια (Καρτλίγια, Καχέτια, Ιμερέτια) και πέντε μπεηλίκια». Η διαίρεση έγινε καθοριστική στην οθωμανο-σαφαβιδική αντιπαλότητα του επόμενου αιώνα: σύμφωνα με τη Συνθήκη της Αμάσειας του 1555, το Ιμερέτι, το Νταντιάν, το Γκουριέλ και το Νταβέλι παραχωρήθηκαν στους Οθωμανούς· το Καρτλί, το Κακέτι και το Μοσούκ στους Σαφαβίδες. Δηλαδή το ότι ο άτλας συνδέει τη δυτική και την ανατολική Γεωργία με διαφορετικούς κυρίους πηγάζει από τη διαίρεση αυτή. Ο Γιαβούζ Σουλτάν Σελίμ, ήδη ως διοικητής της Τραπεζούντας, είχε υποτάξει το 1508 το Βασίλειο του Ιμερέτι (Ακτσίκμπας) και το είχε καταστήσει φόρου υποτελές.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Η κατάληψη της Τρίπολης της Λιβύης από τους Ισπανούς — τέλος της κυριαρχίας των Χαφσιδών", "de319d23"], "d": ["Μετά τους Αμμαρογουλλαρί, η κυριαρχία των Χαφσιδών στην Τρίπολη της Λιβύης διήρκεσε έως το έτος 1510. Εκείνη τη χρονιά η πόλη καταλήφθηκε από τους Ισπανούς υπό τη διοίκηση του κόμη της Ολιβέτο Δον Πέδρο Ναβάρο· οι μουσουλμάνοι που επέζησαν της σφαγής εγκατέλειψαν την πόλη. Η κατάληψη ήταν το ανατολικό άκρο της αλυσίδας φρουρίων της Ισπανίας στις ακτές της Βόρειας Αφρικής από τη Μελίλια έως την Τρίπολη. Ο λαός της Τρίπολης θα έστελνε το 925 (1519) αντιπροσωπεία στην Κωνσταντινούπολη και θα ζητούσε βοήθεια από τους Οθωμανούς εναντίον της ισπανικής εισβολής και η πόλη θα καταλαμβανόταν το 1551 από τον Τουργκούτ Ρέις και τον Σινάν Πασά και θα περνούσε στην οθωμανική διοίκηση.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Η Μάλτα και η Τρίπολη δόθηκαν στους ιππότες του Αγίου Ιωάννη — η νέα βάση του τάγματος που εκδιώχθηκε από τη Ρόδο", "2595729e"], "d": ["Οι ιππότες του Αγίου Ιωάννη (Νοσοκομειακοί), που ο Σουλτάνος Σουλεϊμάν ο Νομοθέτης έβγαλε από τη Ρόδο το 928 (1522), αφού έμειναν οκτώ χρόνια χωρίς πατρίδα, εγκαταστάθηκαν στη Μάλτα από τον βασιλιά της Ισπανίας-Γερμανίας Κάρολο Ε΄· με την ίδια δωρεά η άμυνα της Τρίπολης της Λιβύης δόθηκε επίσης στο τάγμα. Η Μάλτα, με τα ιδανικά λιμάνια που διέθετε, έγινε κατάλληλη βάση για τους ιππότες που ήταν δραστήριοι στις θάλασσες: εγκαταστάθηκαν πρώτα στο Μπίργκου, οχύρωσαν το Φρούριο του Αγίου Αγγέλου και έχτισαν το Φρούριο του Αγίου Μιχαήλ στην άκρη της Σεγκλέα. Η εγκατάσταση αυτή δημιούργησε, στη μέση της Μεσογείου, μια μόνιμη εχθρική βάση που έκοβε τους οθωμανικούς θαλάσσιους δρόμους· οι συγκρούσεις που άρχισαν με την επιδρομή του Τουργκούτ Ρέις στο Γκόζο το 947 (1540) θα συνεχίζονταν έως την πολιορκία της Μάλτας το 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Ειρήνη της Βεστφαλίας — έληξαν οι πόλεμοι των Τριάντα Ετών, διαλύθηκε η ενότητα της Αγίας Ρωμαϊκής Αυτοκρατορίας", "d7719f05"], "d": ["Οι συνθήκες που τερμάτισαν τους πολέμους των Τριάντα Ετών (1618-1648) υπογράφηκαν την ίδια ημέρα στο Μύνστερ και το Οσναμπρίκ (24 Οκτωβρίου 1648). Περίπου τριακόσια πριγκιπάτα της Αγίας Ρωμαϊκής Αυτοκρατορίας απέκτησαν το δικαίωμα να ασκούν δική τους εξωτερική πολιτική· η αυτοκρατορία έπαψε να είναι κράτος και έγινε μια στέγη. Η Σουηδία πήρε τη Δυτική Πομερανία και το Στέτιν, το Βρανδεμβούργο κέρδισε την Ανατολική Πομερανία και την προοπτική της αρχιεπισκοπής του Μαγδεμβούργου — εδώ αρχίζει η εδαφική συσσώρευση των Χοεντσόλερν που το 1701 θα οδηγούσε στη βασιλεία. Η ανεξαρτησία της Ολλανδίας και της Ελβετίας αναγνωρίστηκε επίσημα. Για τους Οθωμανούς η σημασία είναι έμμεση αλλά μεγάλη: όταν οι Αψβούργοι αποσύρθηκαν από το δυτικό μέτωπο, γεννήθηκε στην Κεντρική Ευρώπη μια δύναμη που μπορούσε να στραφεί ξανά προς την ανατολή.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Ανακηρύχθηκε το Βασίλειο της Πρωσίας — ο Φρειδερίκος Α΄ στέφθηκε στο Κένιγκσμπεργκ", "337a9f74"], "d": ["Ο εκλέκτορας του Βρανδεμβούργου Φρειδερίκος Γ΄, στεφόμενος στο Κένιγκσμπεργκ με την έγκριση του αυτοκράτορα Λεοπόλδου Α΄, πήρε τον τίτλο «Βασιλιάς στην Πρωσία» (18 Ιανουαρίου 1701). Ο τίτλος είχε ληφθεί από την Ανατολική Πρωσία, επειδή αυτή βρισκόταν εκτός της Αγίας Ρωμαϊκής Αυτοκρατορίας και ένας εκλέκτορας εξαρτημένος από τον αυτοκράτορα μπορούσε να γίνει βασιλιάς μόνο εκτός των συνόρων της αυτοκρατορίας. Τα διάσπαρτα εδάφη της δυναστείας των Χοεντσόλερν άρχισαν από την ημερομηνία αυτή να αναφέρονται με ένα ενιαίο όνομα κράτους.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Η Σαρδηνία πέρασε από την Ισπανία στη δυναστεία της Σαβοΐας — γεννήθηκε το Βασίλειο της Σαρδηνίας", "adf778b7"], "d": ["Στον τελευταίο κρίκο των ρυθμίσεων που έκλεισαν τον Πόλεμο της Ισπανικής Διαδοχής, το νησί της Σαρδηνίας πάρθηκε από την Ισπανία και δόθηκε στη δυναστεία της Σαβοΐας· ο δούκας της Σαβοΐας άφησε σε αντάλλαγμα τη Σικελία και πήρε τον τίτλο του βασιλιά της Σαρδηνίας. Το Κάλιαρι και το Σάσσαρι βγήκαν έτσι από την ισπανική διοίκηση δύο αιώνων. Το Βασίλειο της Σαρδηνίας που γεννήθηκε είναι ο πυρήνας του κράτους που ενάμιση αιώνα αργότερα θα δημιουργούσε την ιταλική ενοποίηση — δηλαδή η ρίζα του Βασιλείου της Ιταλίας που εισήλθε στη Ρώμη το 1870 φτάνει εδώ.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["Η Κορσική πουλήθηκε από τη Γένοβα στη Γαλλία — Συνθήκη των Βερσαλλιών", "770343df"], "d": ["Η Δημοκρατία της Γένοβας παραχώρησε στη Γαλλία την Κορσική, που κατείχε επί αιώνες αλλά λόγω εξεγέρσεων δεν μπορούσε de facto να ελέγξει. Το λήμμα Κορσική του TDV δίνει το γεγονός με μία πρόταση: η Γένοβα πούλησε το 1768 στη Γαλλία το νησί αυτό, που δεν μπορούσε να οικειοποιηθεί αρκετά. Η παραχώρηση σηματοδοτεί την αποχώρηση της Γένοβας από την τελευταία μεγάλη εδαφική της κατοχή στη Μεσόγειο· το νησί θα περνούσε το 1796 για ένα διάστημα στα χέρια των Βρετανών και στη συνέχεια θα επιστρεφόταν ξανά στη Γαλλία. Το ότι το νησί ήταν γαλλικό έδαφος έκανε τον Ναπολέοντα Βοναπάρτη, που θα γεννιόταν ένα χρόνο αργότερα στο Αζάκιο, Γάλλο υπήκοο. Φέτος (1768) η Κορσική, μαζί με το Μπαστιά, πουλήθηκε από τη Γένοβα στη Γαλλία (TDV Κορσική· η ημέρα δεν είναι επιβεβαιωμένη).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Συνθήκη του Τιλσίτ — η Πρωσία έχασε το μισό των εδαφών της, ιδρύθηκε το Δουκάτο της Βαρσοβίας", "d30bb2cc"], "d": ["Μετά την ήττα της Ιένας-Άουερσταντ η Πρωσία αναγκάστηκε να δεχθεί μια βαριά ειρήνη με τον Ναπολέοντα στο Τιλσίτ (9 Ιουλίου 1807). Άφησε όλα τα εδάφη δυτικά του Έλβα και τα πολωνικά εδάφη που είχε πάρει στις διανομές του 1793 και του 1795· από τα δεύτερα ιδρύθηκε το Δουκάτο της Βαρσοβίας και η περιοχή του Μπιαλιστόκ δόθηκε στη Ρωσία. Η Πρωσία έχασε περίπου το μισό του πληθυσμού και του εδάφους της, ο στρατός της περιορίστηκε στους 42.000. Στον άτλαντα το Πόζναν και το Τορούν περνούν από την ημέρα αυτή στο Δουκάτο της Βαρσοβίας και το Μπιαλιστόκ στη Ρωσία. Με τη συνθήκη αυτή το Λοτζ και η Τσεστοχόβα (πολωνικές επαρχίες που πέρασαν στην Πρωσία μετά το 1772) πέρασαν στο Δουκάτο της Βαρσοβίας· το Γκντανσκ (Ντάντσιχ) έγινε ανεξάρτητη ελεύθερη πόλη.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Τα ιταλικά στρατεύματα εισήλθαν στη Ρώμη — τέλος του Παπικού Κράτους και ολοκλήρωση της ιταλικής ενοποίησης", "a3689f2e"], "d": ["Όταν με την ανατροπή του Ναπολέοντα Γ΄ στον Γαλλοπρωσικό Πόλεμο αποσύρθηκε η γαλλική φρουρά που προστάτευε τη Ρώμη, τα ιταλικά στρατεύματα εισήλθαν στην πόλη και ο πάπας αποσύρθηκε στο Βατικανό. Έτσι έληξε το Παπικό Κράτος, που διατηρούσε την ύπαρξή του επί περισσότερα από χίλια χρόνια, και το Βασίλειο της Ιταλίας, που προσάρτησε και τη Ρώμη στην ένωση, εμφανίστηκε ως πολιτική δύναμη στην ευρωπαϊκή και παγκόσμια σκηνή. Αυτό είναι ένα γεγονός που έχει άμεση συνέπεια για το τελευταίο μισό αιώνα του άτλαντα: η ενωμένη Ιταλία είναι το κράτος που το 1911 θα έπαιρνε από τους Οθωμανούς την Τρίπολη της Λιβύης και τα Δωδεκάνησα.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Μάχη του Τσελένκο — τέλος του Εμιράτου του Χαράρ και αβησσυνιακή κατάληψη", "5671a0d9"], "d": ["Όταν ο Νταβούντ έγινε ιμάμης της Αουσά, το Χαράρ, που είχε μείνει στη μέση εδαφών υπό τη διοίκηση των Ορόμο, έγινε πάλι ανεξάρτητο εμιράτο και διατήρησε την κατάσταση αυτή έως την αβησσυνιακή κατάληψη του 1887. Ο Εμίρης Αμπντουλλάχ, που κήρυξε τζιχάντ, αντιμετώπισε στις 7 Ιανουαρίου 1887 τους Αβησσυνούς στη Σελένεκο (Τσελένκο) με 5000 άνδρες· όταν κατάλαβε ότι θα νικηθεί, κατέφυγε στην περιοχή Ογκαντέν στο νότιο Χαράρ. Η μάχη έδειξε την ανισορροπία μεταξύ του αβησσυνιακού στρατού, εξοπλισμένου με πυροβόλα όπλα, και των δυνάμεων του εμιράτου και εξάλειψε ένα από τα τελευταία ανεξάρτητα μουσουλμανικά εμιράτα πέραν της Ερυθράς Θάλασσας. Το Χαράρ, η Τζιτζίγκα και το Νταγκαχμπούρ προσαρτήθηκαν έτσι στην Αβησσυνία.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Η κατάληψη του Ντερμπέντ από τον Σαχ Ισμαήλ — η σαφαβιδική κυριαρχία έφτασε στην πύλη του Καυκάσου", "305542c4"], "d": ["Με την ήττα και τον θάνατο του Σιρβανσάχ Φερρούχ Γεσάρ το 1500, το Μπακού και η Σεμαχά είχαν περάσει στους Σαφαβίδες, ενώ το Ντερμπέντ είχε μείνει για ένα διάστημα ακόμη χωριστά. Ο Σαχ Ισμαήλ το 1509 κατέλαβε την πόλη και εγκατέστησε εκεί μία από τις φυλές των Ρουμλού· έτσι η σαφαβιδική κυριαρχία έφτασε στη βόρεια πύλη του Καυκάσου, στο στενό αυτό πέρασμα ανάμεσα στην Κασπία και τα βουνά. Με την ένταξη της Σιρβάν στο άμεσο σαφαβιδικό καθεστώς το 1538 ο δεσμός έγινε μόνιμος. Το Ντερμπέντ θα περνούσε στην εκστρατεία του 1578 σε οθωμανικά χέρια και θα ήταν έως το 1607 το κέντρο ενός μπεηλέρμπεηλικίου επτά σαντζακιών. Η καταγραφή του TDV έχει ως εξής: «Η ίδρυση και η ανάπτυξη του Σαφαβιδικού Κράτους αποτέλεσε την αρχή μιας νέας περιόδου στο Ντερμπέντ. Ο Σαχ Ισμαήλ το 1509 κατέλαβε την πόλη και εγκατέστησε εκεί μία από τις φυλές των Ρουμλού. Όταν το 1538 η Σιρβάν περιήλθε στην άμεση σαφαβιδική κυριαρχία...»", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Η οριστική ένταξη του Καρς στα οθωμανικά εδάφη — το καρφί των ανατολικών συνόρων", "6235c85a"], "d": ["Μετά την κατάρρευση του Κράτους των Ακκογιουνλού από τους Σαφαβίδες, το Καρς είχε μείνει για ένα διάστημα στα χέρια του Σεβουντούκ Χαν Κουρτσιμπασί από τους Αφσάρ Τουρκμένους. Κατά την Εκστρατεία των Δύο Ιράκ του Νομοθέτη (940/1534), όταν καταλαμβάνονταν τα φρούρια Πασίν, Σιρεγκέλ και Ολτού, είναι πολύ πιθανό ότι και το Φρούριο του Καρς συνδέθηκε με τους Οθωμανούς· όμως η οριστική ένταξη της πόλης έγινε τρία χρόνια αργότερα. Η καταγραφή του TDV έχει ως εξής: «Το Καρς εντάχθηκε οριστικά στα οθωμανικά εδάφη το 944 (1537) από τον Ντουλκαντιρλί Μεχμέτ Χαν, που είχε περάσει στην οθωμανική υπηρεσία.» Επειδή η πόλη και το φρούριο είχαν ερειπωθεί σε μεγάλο βαθμό από τους μακρούς αγώνες, ξεκίνησε γρήγορη επισκευή· το 955 (1548), ενώ το φρούριο επισκευαζόταν, οι Σαφαβίδες επιτέθηκαν στην πόλη και κατέστρεψαν ξανά το φρούριο. Το Καρς θα παρέμενε στη συνέχεια επί τριακόσια σαράντα χρόνια το κλειδί των βορειοανατολικών συνόρων των Οθωμανών και μετά τον πόλεμο του 1877-78 θα παραχωρούνταν στη Ρωσία.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Η ανάκτηση του Νικοπόλεως — έληξε η εξάμηνη ρωσική κατοχή", "7fb299d7"], "d": ["Οι ρωσικές δυνάμεις, που στον οθωμανο-ρωσικό πόλεμο του 1806-1812 είχαν περάσει στη νότια όχθη του Δούναβη, είχαν καταλάβει το Νικόπολη τον Οκτώβριο του 1810 υπό τη διοίκηση του στρατηγού Κουτούζοφ. Έξι μήνες αργότερα, βλέποντας ότι δεν θα μπορούσαν να κρατήσουν τη γραμμή του Δούναβη, εκκένωσαν την πόλη· πριν φύγουν ανατίναξαν σημαντικό μέρος του φρουρίου. Η καταγραφή του TDV έχει ως εξής: «Τον Οκτώβριο του 1810 (περίοδος του τουρκο-ρωσικού πολέμου 1808-1812) το Νικόπολη καταλήφθηκε από τις δυνάμεις του διάσημου Ρώσου στρατηγού Μιχαήλ Κουτούζοφ. Οι Ρώσοι, πριν εγκαταλείψουν την πόλη, τον Απρίλιο του 1811 ανατίναξαν σημαντικό μέρος του φρουρίου και προκάλεσαν μεγάλη ζημιά στην πόλη.» Μετά την αποχώρηση των ρωσικών δυνάμεων οι Οθωμανοί ανακατασκεύασαν το φρούριο· η επιγραφή των ετών 1813-1814 είναι η καταγραφή της επισκευής αυτής.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Η εκκένωση του Σιλίστρα — το μεσαίο φρούριο του Δούναβη εγκαταλείφθηκε με γκρεμισμένα τείχη", "561628bb"], "d": ["Το Σιλίστρα, ένα από τα ισχυρότερα οθωμανικά φρούρια του Δούναβη, είχε υποστεί το 1810 βομβαρδισμό από ρωσικό πυροβολικό και με την έκρηξη μιας αποθήκης όπλων το φρούριο και το προάστιο είχαν υποστεί βαριές ζημιές. Αφού κατέλαβαν την πόλη, οι Ρώσοι, αντί να την κρατήσουν, προτίμησαν να καταστρέψουν τις οχυρώσεις της: ο στρατηγός Κουτούζοφ διέταξε την κατεδάφιση των τειχών και τον Μάιο του 1811 ανέφερε στον τσάρο ότι τα τείχη του Σιλίστρα ανατινάχθηκαν. Η καταγραφή του TDV: «Το 1810 η πόλη βομβαρδίστηκε από τους Ρώσους… Μετά την κατάληψη της πόλης από τους Ρώσους και πριν από την υποχώρησή τους ο στρατηγός Κουτούζοφ διέταξε την καταστροφή του Σιλίστρα. Τον Μάιο του 1811 ανέφερε στον τσάρο ότι τα τείχη του Σιλίστρα ανατινάχθηκαν.» Το ίδιο φρούριο θα καταλαμβανόταν ξανά από τους Ρώσους στον πόλεμο του 1827-1828 και την πολιορκία εκείνη θα την περιέγραφε λεπτομερώς ο Χέλμουτ φον Μόλτκε.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Το τέλος της δυναστείας των Ζαντ — κυριαρχία των Κατζάρ στο Ιράν", "5dda30a4"], "d": ["Με την ήττα του τελευταίου ηγεμόνα της δυναστείας των Ζαντ, του Λουτφ Αλί Χαν, έληξε η δυναστεία που ιδρύθηκε το 1751 και ολόκληρο το Ιράν περιήλθε στον Αγά Μουχαμμάντ Χαν. Η επίσημη ίδρυση του Κράτους των Κατζάρ χρονολογείται δύο χρόνια αργότερα, στην ανάληψη του στέμματος του σαχινσάχ από τον Αγά Μουχαμμάντ Χαν στην Τεχεράνη (1796)· όμως η εξουσία είχε μεταβιβαστεί το 1794.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Διαφορές Λωζάνης–Σεβρών: από την επιβληθείσα ειρήνη στην ισότιμη ειρήνη", "4b578583"], "d": ["Οι Σέβρες (10 Αυγούστου 1920) ήταν ένα έγγραφο που επιβλήθηκε στην κυβέρνηση της Κωνσταντινούπολης και δεν τέθηκε ποτέ σε ισχύ· η Λωζάνη (24 Ιουλίου 1923) είναι η ειρήνη που η Άγκυρα υπέγραψε ως ισότιμο μέρος και που η ΜΤΕΤ (Μεγάλη Εθνοσυνέλευση της Τουρκίας) επικύρωσε στις 23 Αυγούστου 1923 (Λωζάνη άρθρ. 1, 143). Στα σύνορα, οι Σέβρες φέρνουν το ευρωπαϊκό σύνορο της Τουρκίας στη γραμμή της Τσατάλτζα και δίνουν στην Ελλάδα την Ανατολική Θράκη, μαζί με την Αδριανούπολη, και την Ίμβρο και την Τένεδο (Σέβρες άρθρ. 27, 84)· η Σμύρνη και τα περίχωρά της μένουν με το όνομα υπό τουρκική κυριαρχία αλλά η διοίκησή τους αφήνεται στην Ελλάδα και μετά από πέντε χρόνια το τοπικό κοινοβούλιο μπορεί να ζητήσει προσάρτηση (άρθρ. 65-83). Η Λωζάνη χαράσσει τη γραμμή Έβρου-Άρδα, η Αδριανούπολη και το Καραγάτς μένουν στην Τουρκία, η Ίμβρος και η Τένεδος γίνονται τουρκικές (Λωζάνη άρθρ. 2, 12, 14· Πρωτόκολλο του Καραγάτς). Στα Στενά, οι Σέβρες ιδρύουν μια διεθνή επιτροπή που εκτείνεται σε όλα τα ύδατα και στην οποία το τουρκικό μέλος έχει μόνο μία ψήφο· οι οχυρώσεις κατεδαφίζονται και η περιοχή ανοίγει στη χρήση των Συμμάχων (Σέβρες άρθρ. 36-61, 178-180). Η Λωζάνη διατηρεί την αρχή της ελεύθερης διέλευσης, αλλά αφήνει επιτροπή υπό τουρκική προεδρία, αποστρατιωτικοποιημένες ζώνες και φρουρά 12.000 ανδρών στην Κωνσταντινούπολη (Λωζάνη άρθρ. 23· Σύμβαση των Στενών). Η αναγνώριση της Αρμενίας και η διαιτησία του προέδρου των ΗΠΑ για τα σύνορα, καθώς και το σχέδιο κουρδικής αυτονομίας (Σέβρες άρθρ. 62-64, 88-93) δεν περιλαμβάνονται στη Λωζάνη. Για τα αραβικά εδάφη, την Αίγυπτο, το Σουδάν και την Κύπρο, οι Σέβρες θεσπίζουν λεπτομερείς διατάξεις μεταβίβασης (Σέβρες άρθρ. 94-97 εντολές, άρθρ. 98-100 Χιτζάζ, άρθρ. 101-122 παραίτηση από Αίγυπτο, Σουδάν, Κύπρο, Μαρόκο, Τυνησία και Λιβύη· οι περιοχές άρθρων του TDV είναι επίσης τέτοιες)· η Λωζάνη γράφει την παραίτηση πιο σύντομα, τα Δωδεκάνησα μένουν στην Ιταλία, η Κύπρος στην Αγγλία, το σύνορο της Μοσούλης αναβάλλεται (Λωζάνη άρθρ. 3, 15-21). Οι Σέβρες επανιδρύουν και διευρύνουν τις καπιτουλάσιες, ελέγχουν με Οικονομική Επιτροπή τον τουρκικό προϋπολογισμό και τον δανεισμό, η ένοπλη δύναμη (χωροφυλακή και ενισχυτικά στοιχεία) δεν μπορεί να ξεπεράσει τα 50.000 άτομα, η στρατιωτική και ναυτική αεροπορία απαγορεύονται (Σέβρες άρθρ. 155, 164, 191-195, 231-264, 261-263). Η Λωζάνη καταργεί τις καπιτουλάσιες, μοιράζει τα χρέη και δεν θέτει χωριστό περιορισμό στον στρατό (Λωζάνη άρθρ. 28, 46-63· το άρθρ. 113 καταργεί και τα ξένα ταχυδρομεία). Οι διατάξεις για τις μειονότητες στις Σέβρες είναι ευρύτερες και ανοιχτές σε επέμβαση των Συμμάχων, ενώ στη Λωζάνη είναι εγγυημένες από την Κοινωνία των Εθνών και αμοιβαίες (Σέβρες άρθρ. 140-151· Λωζάνη άρθρ. 37-45).\n\nΣύγκριση ανά άξονα:\n• Ανατολική Θράκη, Αδριανούπολη, Τσατάλτζα — Σέβρες: Η γραμμή της Τσατάλτζα είναι σύνορο· η Ανατολική Θράκη και η Αδριανούπολη στην Ελλάδα (άρθρ. 27, 84-85) | Λωζάνη: Σύνορο κατά μήκος του Έβρου και του Άρδα· η Αδριανούπολη και το Καραγάτς στην Τουρκία (άρθρ. 2· Πρωτόκολλο του Καραγάτς)\n• Περιοχή της Σμύρνης — Σέβρες: Κυριαρχία τουρκική, διοίκηση και στρατός ελληνικός, αίτηση προσάρτησης μετά από πέντε χρόνια (άρθρ. 65-83) | Λωζάνη: Δεν υπάρχει ειδικό άρθρο καθεστώτος για τη Σμύρνη· η Ανατολία είναι εντός των τουρκικών συνόρων (άρθρ. 2-3 γενικό σύνορο· ειδική απόδειξη άρθρου για τη Σμύρνη δεν υπάρχει)\n• Στενά και Κωνσταντινούπολη — Σέβρες: Διεθνής Επιτροπή Στενών, Τούρκος με 1 ψήφο· κατεδάφιση οχυρώσεων, περιοχή υπό χρήση των Συμμάχων· η Κωνσταντινούπολη σε τουρκικά χέρια αλλά υπό τον όρο των μειονοτήτων (άρθρ. 36-61, 178-180) | Λωζάνη: Αρχή ελεύθερης διέλευσης· επιτροπή υπό τουρκική προεδρία, αποστρατιωτικοποιημένες ζώνες, φρουρά 12.000 ανδρών στην Κωνσταντινούπολη (άρθρ. 23· Σύμβαση των Στενών)\n• Αρμενία και Κουρδιστάν — Σέβρες: Η Αρμενία αναγνωρίζεται, το σύνορό της το καθορίζει ο πρόεδρος των ΗΠΑ· κουρδική αυτονομία, αίτηση ανεξαρτησίας μετά από ένα χρόνο (άρθρ. 62-64, 88-93) | Λωζάνη: Δεν υπάρχει σχετική διάταξη (δεν αναφέρεται στις περιλήψεις των άρθρ. 1-143)\n• Νησιά του Αιγαίου, Δωδεκάνησα — Σέβρες: Ίμβρος, Τένεδος και νησιά του Αιγαίου στην Ελλάδα· Δωδεκάνησα και Καστελλόριζο στην Ιταλία (άρθρ. 84, 122) | Λωζάνη: Ίμβρος και Τένεδος στην Τουρκία, νησιά του Ανατολικού Αιγαίου ελληνικά, Δωδεκάνησα και Καστελλόριζο στην Ιταλία (άρθρ. 12-15)\n• Κύπρος, Αίγυπτος, Σουδάν, αραβικά εδάφη — Σέβρες: Εντολή Συρίας/Μεσοποταμίας και Παλαιστίνης, ανεξάρτητο Χιτζάζ· αναγνωρίζονται το προτεκτοράτο της Αιγύπτου, το Σουδάν, η προσάρτηση της Κύπρου (άρθρ. 94-98, 101-117) | Λωζάνη: Το σύνορο της Συρίας με τη γαλλο-τουρκική συμφωνία του 1921, το σύνορο του Ιράκ αργότερα· παραίτηση από Αίγυπτο, Σουδάν, Κύπρο (άρθρ. 3, 16-20)\n• Καπιτουλάσιες — Σέβρες: Επανιδρύονται και διευρύνονται· σχέδιο δικαστικής μεταρρύθμισης στην επιτροπή των Συμμάχων (άρθρ. 136, 261-263, 308-309) | Λωζάνη: Καταργούνται εντελώς· καταργούνται τα ξένα ταχυδρομεία και το Ανώτατο Συμβούλιο Υγείας (άρθρ. 28, 113-114)\n• Οικονομικός έλεγχος και χρέη — Σέβρες: Η Οικονομική Επιτροπή των Συμμάχων ελέγχει τον προϋπολογισμό και τον δανεισμό, η Δημόσια Οθωμανική Χρέη επεκτείνεται, οι πόροι τίθενται ως εγγύηση (άρθρ. 231-264) | Λωζάνη: Η Δημόσια Οθωμανική Χρέη μοιράζεται μεταξύ των μεριδίων των κρατών· οι πολεμικές ζημιές αφήνονται αμοιβαία (άρθρ. 46-63, 58)\n• Στρατιωτικοί περιορισμοί — Σέβρες: Στρατός 50.000 ανδρών, απαγόρευση αεροπορίας και αρμάτων, Επιτροπές Ελέγχου των Συμμάχων (άρθρ. 152-207) | Λωζάνη: Δεν υπάρχει γενικός περιορισμός· αφοπλισμός μόνο στα ελληνικά νησιά και στις περιοχές των Στενών-Θράκης (άρθρ. 13· συμβάσεις Στενών και Θράκης)\n• Μειονότητες — Σέβρες: Εγγύηση και δικαίωμα επέμβασης των Συμμάχων, ακύρωση των Εμβάλ-ι Μετρούκε, επιστροφή (άρθρ. 140-151, 86, 142-144) | Λωζάνη: Δικαιώματα εγγυημένα από την Κοινωνία των Εθνών για τις μη μουσουλμανικές μειονότητες, αμοιβαία δικαιώματα των μουσουλμάνων στην Ελλάδα· ανταλλαγή πληθυσμών Ελλήνων-Τούρκων (άρθρ. 37-45· Σύμβαση Ανταλλαγής)\n• Νομικό καθεστώς — Σέβρες: Υπογράφηκαν από την κυβέρνηση της Κωνσταντινούπολης, η Άγκυρα τις απέρριψε, δεν τέθηκαν σε ισχύ (TDV) | Λωζάνη: Ισότιμο μέρος· επικύρωση της ΜΤΕΤ στις 2 Αυγούστου 1923, 213 υπέρ 14 κατά (TDV· άρθρ. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Ο Σουλεϊμάν μπ. Κουταλμίς ηττήθηκε και σκοτώθηκε στο Αϊνουσεΐλεμ· η Αντιόχεια βγήκε από τους Σελτζούκους της Ανατολίας", "0412dfa1"], "d": ["Ο Σουλεϊμάν μπ. Κουταλμίς, που είχε πάρει την Αντιόχεια από το Βυζάντιο το 1084, σκοτώθηκε στη μάχη του Αϊνουσεΐλεμ (Aynüseylem) που έδωσε με τον ηγεμόνα των Σελτζούκων της Συρίας Τουτούς· η πόλη πέρασε στον έλεγχο του Σουλτάνου των Μεγάλων Σελτζούκων Μαλίκσαχ και διορίστηκε βαλής ο Γιαγισιγιάν.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Ο Μαλίκσαχ πέθανε· η Αντιόχεια μαζί με τον Γιαγισιγιάν εξαρτήθηκε από τον Τουτούς των Σελτζούκων της Συρίας", "c61da1b4"], "d": ["Μετά τον θάνατο του Σουλτάνου των Μεγάλων Σελτζούκων Μαλίκσαχ, το κράτος διαιρέθηκε ανάμεσα στους κληρονόμους· ο βαλής της Αντιόχειας Γιαγισιγιάν εξαρτήθηκε από τον κυρίαρχο της Συρίας Τουτούς.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Η Νίκαια παραδόθηκε στους Σταυροφόρους· το κέντρο των Σελτζούκων αποσύρθηκε στο Ικόνιο, το Βυζάντιο άρχισε να ανακτά τη δυτική Ανατολία", "8a4e90fa"], "d": ["Μετά την πολιορκία της Νίκαιας από τους Σταυροφόρους, η πόλη παραδόθηκε στο Βυζάντιο στις 19 Ιουνίου 1097· ο σουλτάνος των Σελτζούκων Κιλίτς Αρσλάν Α' απέσυρε το κέντρο του στην ενδοχώρα, στο Ικόνιο, ενώ το Βυζάντιο ανέκτησε μέρη των δυτικών ακτών της Ανατολίας, όπως την Έφεσο.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Ο Κιλίτς Αρσλάν Β' πήρε από το Βυζάντιο το Δορύλαιο (Εσκίσεχιρ) και την Κιουτάχεια", "3ddee6c2"], "d": ["Μετά το Μυριοκέφαλο (1176), τα φρούρια του Βυζαντίου στο εσωτερικό της Ανατολίας, το Δορύλαιο και η Κιουτάχεια, περιήλθαν στα χέρια του Κιλίτς Αρσλάν Β' τα τελευταία χρόνια του Μανουήλ/μετά τον θάνατό του το 576/1180.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Ο Καραμανογλου Μεχμέτ Μπέης διορίστηκε σουμπασής του Ερμενέκ και ανέλαβε τη διοίκηση του Iç İl", "6d62be11"], "d": ["Ο Καραμανογλου Μεχμέτ Μπέης το έτος 675 (1276) διορίστηκε σουμπασής του Ερμενέκ και ανέλαβε τη διοίκηση του Iç İl· το Ερμενέκ έγινε το πρώτο κέντρο των Καραμανογλου, οι οποίοι την επόμενη χρονιά επρόκειτο να βαδίσουν κατά του Ικονίου.", "dc2f3a25"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Η Χίος πέρασε στον έλεγχο της γενοβέζικης οικογένειας Ζακαρία (Zaccaria)", "9eebe4de"], "d": ["Μπροστά στην απειλή των Αϊδινογλού, ο βυζαντινός αυτοκράτορας ζήτησε βοήθεια από τον Γενοβέζο Μπενεντέτο Ζακαρία (Benedetto Zaccaria)· το νησί πέρασε στον έλεγχό του (ονομαστική βυζαντινή υποτέλεια). Η κυριαρχία των Ζακαρία διήρκεσε έως το 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Η Σάμος πέρασε στην κυριότητα των Γενοβέζων (Ζακαρία) της Χίου", "0e6f51e3"], "d": ["Η γενοβέζικη οικογένεια Ζακαρία, που πήρε υπό τον έλεγχό της τη Χίο, πρόσθεσε στην κυριότητά της και τη σχεδόν ερημωμένη Σάμο (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Η Χίος αφαιρέθηκε από τους Ζακαρία και υπήχθη στο Βυζάντιο", "f6741b26"], "d": ["Ο αυτοκράτορας Ανδρόνικος Γ' απομάκρυνε τους Ζακαρία από το νησί και υπήγαγε το νησί στο Βυζάντιο με διοικητή τον Μπενεντέτο Γ'. Το νησί θα καταληφθεί το 1346 από τον Γενοβέζο Σιμόνε Βινιόζι (Simone Vignosi).", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Η Σάμος επέστρεψε από τους Ζακαρία στο Βυζάντιο (αλυσίδα της Χίου)", "08034974"], "d": ["Με την κατάρρευση της λορδίας των Ζακαρία (την υπαγωγή της Χίου στο Βυζάντιο το 1329) έληξε και η γενοβέζικη κυριότητα στη Σάμο.", "314dce74"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Η Σαμοθράκη πέρασε από τους Βενετούς στη γενοβέζικη οικογένεια Γατελούζι (Gattilusio)", "c499ed5f"], "d": ["Οι Βενετοί, που κρατούσαν το νησί από το 1204, εκδιώχθηκαν από το νησί από τη γενοβέζικη οικογένεια Γατελούζι.", "97a996b3"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Η Σάμος πέρασε στην κυριότητα της Μαόνας της Χίου", "01628b2f"], "d": ["Με την κατάληψη της Χίου από τον Γενοβέζο Σιμόνε Βινιόζι και την παράδοση της διοίκησης στην εταιρεία Μαόνα (Maona), πέρασε και η Σάμος στην κυριότητα των Γενοβέζων της Χίου (Μαόνα) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Το Μους πέρασε από τη διοίκηση των Καρακογιουνλού στη διοίκηση του Ταμερλάνου (789/1387)", "ed2e7a11"], "d": ["Το Μους, που μετά τη μογγολική περίοδο πέρασε στη διοίκηση των Καρακογιουνλού, το 789 (1387) περιήλθε στη διοίκηση του Ταμερλάνου, ο οποίος κατείχε τα εδάφη των Καρακογιουνλού. Στον άτλαντα το Μους καταγράφεται αυτό το έτος ως μεταβαίνον από τους Καρακογιουνλού στους Τιμουρίδες.", "9475520a"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Η περιοχή του Νεβσεχίρ και του Ουργκιούπ πέρασε από τους Καραμανογλού στους Οθωμανούς", "06ff59e8"], "d": ["Στις εκστρατείες του Γιλντιρίμ Μπαγιαζήτ κατά των Καραμανογλού, η περιοχή του Νεβσεχίρ (Muşkara) και του Ουργκιούπ πέρασε το 800/1398 στην οθωμανική διοίκηση· το 1402, μετά τη Μάχη της Άγκυρας, ο Ταμερλάνος (Timur) επέστρεψε την περιοχή στους Καραμανογλού.", "5faa82e5"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Θάνατος του Μεχμέτ Α' και ανάρρηση του Μουράτ Β'", "98acac77"], "d": ["Ο Μεχμέτ Α', που έβαλε τέλος στην Εποχή του Interregnum (Fetret Devri) και συγκέντρωσε ξανά τα οθωμανικά εδάφη σε ένα χέρι, πέθανε στις 25 Ιουνίου 1421 στην Αδριανούπολη και ο γιος του Μουράτ ανέβηκε στον θρόνο στη Προύσα. Σύμφωνα με τη ρύθμιση που είχε γίνει με το Βυζάντιο πριν από τον θάνατό του, οι μικροί γιοι του θα στέλνονταν ως όμηροι στον αυτοκράτορα και ο αυτοκράτορας δεν θα απελευθέρωνε τον διεκδικητή του θρόνου Μουσταφά Τσελεμπή που κρατούσε· ο Μουράτ Β' αρνήθηκε να στείλει τα αδέλφια του στον αυτοκράτορα.", "c8093fa8"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Παραχώρηση του Βελιγραδίου στην Ουγγαρία — Συνθήκη της Τάτα (Tata)", "62481183"], "d": ["Με τον θάνατο του Σέρβου δεσπότη Στέφαν Λάζαρεβιτς, σύμφωνα με τη Συνθήκη της Τάτα που έγινε ανάμεσα στον Ούγγρο βασιλιά Σιγισμούνδο και τον διάδοχο Γκέοργκ Μπράνκοβιτς, το φρούριο του Βελιγραδίου παραχωρήθηκε στην Ουγγαρία. Το φρούριο, που βρισκόταν στο σημείο συνάντησης του Δούναβη και του Σάβα, ως τότε βρισκόταν στα χέρια του σερβικού δεσποτάτου και ήταν για τους Οθωμανούς το κλειδί της πύλης που άνοιγε προς την Κεντρική Ευρώπη. Η παραχώρηση αυτή έκανε το Βελιγράδι για εκατό χρόνια το σκληρότερο εμπόδιο μπροστά στην οθωμανική προέλαση: οι πολιορκίες του 1440 και του 1456 θα αποτύχουν, το φρούριο θα πέσει μόλις το 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Οι εμπροσθοφυλακές των Ακκογιουνλού κατέλαβαν το κάστρο του Μπιγκιόλ από τους Καρακογιουνλού", "51b94cbc"], "d": ["Στις τελευταίες εβδομάδες της εκστρατείας του Τζιχάν Σαχ εναντίον του Ουζούν Χασάν, οι εμπροσθοφυλακές των Ακκογιουνλού κατέλαβαν το κάστρο του Μπιγκιόλ· με τη δολοφονία του Τζιχάν Σαχ στις 10 Νοεμβρίου 1467, η κυριαρχία των Καρακογιουνλού στην περιοχή έληξε.", "c150063d"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Εγκαθιδρύθηκε οθωμανική διοίκηση στην Καισάρεια: ο Γκεντίκ Αχμέτ Πασάς τερμάτισε τους Καραμανογλού", "33cf35fc"], "d": ["Με τον τερματισμό των Καραμανογλού από τον Γκεντίκ Αχμέτ Πασά το 1474, η Καισάρεια πέρασε στην οθωμανική διοίκηση· η πόλη κατά τον 15ο αιώνα είχε αλλάξει χέρια μεταξύ των Ντουλκαντιρογλού, των Ραμαζανογλού και των Καραμανογλού. Με την οθωμανική διοίκηση η Καισάρεια έγινε κέντρο σαντζακιού του μπεηλέρμπεηλικιού του Καραμάν.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Η Σάμος εγκαταλείφθηκε: έληξε η γενοβέζικη (Μαόνα) κυριότητα", "5bdc380c"], "d": ["Σύμφωνα με το TDV το νησί εγκαταλείφθηκε μετά το 1475· το 1479 ο Μωάμεθ ο Πορθητής κατέκτησε το νησί και έχτισε φρούριο.", "4e48c423"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Είσοδος της Σάμου στην οθωμανική διοίκηση (Πορθητής)", "c877bc14"], "d": ["Ο Μωάμεθ ο Πορθητής κατέκτησε τη Σάμο, έχτισε φρούριο και αναδιοργάνωσε την απογραφή· το φρούριο κατεδαφίστηκε το 1483 από τον Βαγιαζήτ Β' για πολιτικούς λόγους.", "2965b1d9"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Η Νικαρία (Ικαρία) μπήκε στη διοίκηση των Ιπποτών του Αγίου Ιωάννη της Ρόδου", "5cbc2669"], "d": ["Η Νικαρία, ανάμεσα στη Σάμο και τη Χίο, βρισκόταν από το 1481 έως το 1521 υπό τη διοίκηση των Ιπποτών του Αγίου Ιωάννη της Ρόδου.", "9d387479"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Παραχώρηση της Ζακύνθου (Zaklise) στη Βενετία με ετήσιο φόρο υποτέλειας", "268a691a"], "d": ["Στο τέλος της εποχής του Πορθητή, η Ζάκυνθος, ένα από τα νησιά του Ιονίου που είχαν ληφθεί από την οικογένεια Τόκκο (Tocco), αφέθηκε στη Βενετία από τον νέο σουλτάνο, ο οποίος, καθώς ασχολούνταν με το ζήτημα του Τζεμ Σουλτάν, αναζητούσε ηρεμία στη Δύση. Το νησί παραδόθηκε σε βενετική διοίκηση που αναγνώριζε την οθωμανική κυριαρχία και κατέβαλλε ετήσιο φόρο πεντακοσίων δουκάτων. Έτσι στο Ιόνιο Πέλαγος η άμεση οθωμανική διοίκηση παρέμεινε μόνο στην Αγία Μαύρα.", "0773761c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Απώλεια της Κεφαλονιάς και της Ιθάκης", "60f0f687"], "d": ["Η Βενετία, κλονισμένη από την κατάληψη της Μεθώνης και της Κορώνης, ενώθηκε με την Ισπανία και πέρασε στην αντεπίθεση και πολιόρκησε την Κεφαλονιά, που βρισκόταν στα οθωμανικά χέρια από το 1479. Μετά από αντίσταση σαράντα επτά ημερών το φρούριο έπεσε, το νησί πέρασε μαζί με την Ιθάκη στη Βενετία και δεν επέστρεψε στην οθωμανική διοίκηση επί τριακόσια χρόνια. Η απώλεια αυτή δημιούργησε μια ισορροπία όπου ό,τι κερδήθηκε στον Μοριά επιστράφηκε στο Ιόνιο.", "a61731e0"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Κατάκτηση του Φρουρίου Σιν (Sinj)", "83271ea5"], "d": ["Οι οθωμανικές ακιντζίδικες δυνάμεις στα σύνορα της Βοσνίας κατέλαβαν από το Βασίλειο της Ουγγαρίας το Φρούριο Σιν (Sinj), που εκτείνεται στην ενδοχώρα της Δαλματίας. Ήταν ένας πρώιμος κρίκος της συνοριακής γραμμής της Δαλματίας, η οποία εννέα χρόνια αργότερα θα διευρυνόταν με την κατάκτηση του Κνιν και της γύρω περιοχής από τον Γαζή Χουσρέβ Μπέη· το φρούριο θα χανόταν στη Βενετία το 1686.", "28c20426"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Το Μους και το Μπινγκιόλ (Çapakçur) πέρασαν από τους Σαφαβίδες στην οθωμανική διοίκηση", "b0a53b5a"], "d": ["Με την ανάκτηση της Ανατολικής Ανατολίας από τους Σαφαβίδες μετά το Τσαλντιράν, το Μους μπήκε το 921/1515 στην οθωμανική διοίκηση· το γειτονικό Çapakçur (Μπινγκιόλ) προσαρτήθηκε στους Οθωμανούς στην ίδια διαδικασία.", "9c979b3f"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Είσοδος του νησιού Νικαρία (Ικαρία) στην οθωμανική διοίκηση", "6afa972b"], "d": ["Η Νικαρία, ανάμεσα στη Σάμο και τη Χίο, βρισκόταν από το 1481 έως το 1521 υπό τη διοίκηση των Ιπποτών του Αγίου Ιωάννη της Ρόδου· η πρώτη οθωμανική περίοδος στο νησί ξεκίνησε το 1522 και διήρκεσε έως το 1822. Κατά την περίοδο αυτή υπεύθυνος για τη συλλογή και την καταβολή των φόρων ήταν ο καϊμακάμης· όπως και στα υπόλοιπα νησιά του Αιγαίου, συνέχισε να υπάρχει και το τοπικό συμβούλιο προεστών (δημογεροντία) και κατά καιρούς συγκρουόταν με την οθωμανική διοίκηση.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Προσάρτηση της χώρας του Ντουλκαντίρ — έγιαλετ του Ντουλκαντίρ με κέντρο το Μαράς", "595c3c30"], "d": ["Η χώρα του Ντουλκαντίρ, που συνέχιζε ως οθωμανικό υποτελές μπεηλίκι μετά την ήττα του Τουρνανταγ το 1515, προσαρτήθηκε απευθείας στα οθωμανικά εδάφη μετά τη δολοφονία του Σεχσουβαρογλού Αλή Μπέη μαζί με τα παιδιά του στην Αρτούκοβα και έγινε έγιαλετ με κέντρο το Μαράς. Η περιοχή Μπόζοκ του μπεηλικιού υπήχθη στην οθωμανική διοίκηση ως ξεχωριστό σαντζάκι. Έτσι έκλεισε η περίπου διακοσίων ετών περίοδος του Ντουλκαντίρ για το Μαράς, το Ελμπιστάν, το Γκιοκσούν, το Γκιουρούν, το Ζαμάντι και το Νταρεντέ· το μπεηλίκι-ζώνη ανάσχεσης στα σύνορα των Μαμελούκων εξαφανίστηκε εντελώς.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Κατάκτηση του Κνιν", "a46d3117"], "d": ["Με τις επιδρομές του σαντζάκμπεη της Βοσνίας Γαζή Χουσρέβ Μπέη τα έτη 927-928 (1521-1522), μια σειρά βενετικών φρουρίων, με πρώτα το Κνιν, το Σκράντιν και το Οστρόβιτσα, πέρασαν στην οθωμανική διοίκηση· τα σύνορα ωθήθηκαν πέρα από τη δεύτερη οροσειρά. Η αλυσίδα αυτή των κατακτήσεων έθεσε τα θεμέλια του σαντζακιού της Δαλματίας, που θα ολοκληρωνόταν δεκαπέντε χρόνια αργότερα με την κατάληψη του Κλις.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Αποχώρηση των Ιπποτών: παράδοση του Μπόντρουμ, της Κω και της Δωδεκανήσου", "ea01666e"], "d": ["Σύμφωνα με τους όρους παράδοσης της Ρόδου, οι ιππότες του Αγίου Ιωάννη εκκένωσαν όχι μόνο το κέντρο του νησιού αλλά όλες τις θέσεις που κρατούσαν εδώ και διακόσια χρόνια. Το φρούριο του Μπόντρουμ (Άγιος Πέτρος) στην ακτή της Ανατολίας και τα νησιά Κως (İstanköy), Κάλυμνος (Kelemez) και Λέρος (İleryoz) πέρασαν έτσι χωρίς σύγκρουση στην οθωμανική διοίκηση. Με την παράδοση αυτή, που ολοκληρώθηκε δύο εβδομάδες μετά την πτώση της Ρόδου, η λατινική παρουσία στη νοτιοανατολική γωνία του Αιγαίου έληξε εντελώς.", "bcbe8fa8"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Προσάρτηση της Βόρειας Βοσνίας: Γιάιτσε και Μπάνια Λούκα", "8ec86cfa"], "d": ["Όταν κατέρρευσε η ουγγρική αμυντική γραμμή μετά το Μοχάτς, ο σαντζάκμπεης της Βοσνίας Γαζή Χουσρέβ Μπέης βάδισε στην κοιλάδα του Βρμπάς και κατέλαβε τα τελευταία βοσνιακά φρούρια που απέμεναν στο ουγγρικό βασίλειο. Με την πτώση του Γιάιτσε και της Μπάνια Λούκα το έγιαλετ της Βοσνίας έφτασε βόρεια έως τον ποταμό Σάβα και γεννήθηκε το μέτωπο της Κροατίας. Η Μπάνια Λούκα έγινε σύντομα το δεύτερο κέντρο του έγιαλετ.", "1f634005"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Κατάληψη του Καρς και άνοιγμα των βορειοανατολικών συνόρων", "742e3101"], "d": ["Καθώς το προπορευόμενο τμήμα της Εκστρατείας των Δύο Ιράκ (Irakeyn Seferi) κινούνταν από το Ερζερούμ προς τα ανατολικά, το φρούριο του Καρς, που βρισκόταν στα χέρια του γεωργιανού αταμπεγάτου και ερειπωνόταν από την εποχή του Ταμερλάνου (Timur), παραδόθηκε χωρίς αντίσταση. Η πόλη, επειδή κρατούσε το πέρασμα ανάμεσα στο τόξο του Αράξη και το Τσίλντιρ, θεωρούνταν το κλειδί της βόρειας πύλης που άνοιγε προς το Ιράν. Το κέρδος αυτό υπήρξε ο πρώτος κρίκος του μπεηλέρμπεηλικιού του Καρς και της γραμμής του Καυκάσου που θα ιδρύονταν τριάντα χρόνια αργότερα.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Πρώτη είσοδος στην Ταμπρίζ — έναρξη της Εκστρατείας των Δύο Ιράκ", "cf7ed4e3"], "d": ["Ο Ιμπραήμ Πασάς, που κινήθηκε μπροστά με την ιδιότητα του αρχιστράτηγου (serdar-ı ekrem), μπήκε χωρίς αντίσταση στην Ταμπρίζ, πρωτεύουσα των Σαφαβιδών, καθώς ο Σάχης Ταχμάσπ απέφυγε την ανοιχτή μάχη και αποσύρθηκε προς το εσωτερικό. Ο Σουλεϊμάν ο Μεγαλοπρεπής έφτασε στην πόλη τον Σεπτέμβριο· ωστόσο, λόγω του χειμώνα που πλησίαζε και του υπερβολικά μακριού δρόμου ανεφοδιασμού, ο στρατός στράφηκε προς τη Βαγδάτη και η Ταμπρίζ δεν μπόρεσε να κρατηθεί για μεγάλο διάστημα. Η πόλη, που καταλήφθηκε για δεύτερη φορά μετά το Τσαλντιράν, έγινε ο τόπος όπου οι Οθωμανοί έμαθαν ότι στην ανατολή η κατάκτηση είναι εύκολη, αλλά η διατήρηση δύσκολη.", "a303a9e4"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Επιχείρηση του Γαζή Χουσρέβ Μπέη κατά μήκος του Σάβα: Μπόσνα Μπροντ και Γιασένοβατς", "3740ec83"], "d": ["Μετά την κατάληψη του Γιάιτσε και της Μπάνια Λούκα το 1528, τα φρούρια κατά μήκος του ποταμού Σάβα παρέμειναν για λίγο ακόμη στα κροατο-σλαβονικά σύνορα που εξαρτώνταν από το στέμμα των Αψβούργων. Ο Γαζή Χουσρέβ Μπέης, που το 1536 έγινε για τρίτη φορά σαντζάκμπεης της Βοσνίας, την ίδια χρονιά, ενώ κατέλαβε το Ποζέγκα και τη γύρω περιοχή, πρόσθεσε στην οθωμανική διοίκηση και τα φρούρια Μπροντ και Γιασένοβατς στην όχθη του Σάβα. Έτσι τα βόρεια σύνορα της Βοσνίας έφτασαν στον Σάβα· η περιοχή ολοκληρώθηκε δύο χρόνια αργότερα με την κατάληψη του Ντουμπίτσα.", "415f0592"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Εκστρατεία του Μπαρμπαρόσα στο Αιγαίο: κατάληψη των νησιών που διοικούνταν απευθείας από τη Βενετία", "1b32ed96"], "d": ["Ο στόλος που επέστρεψε από την πολιορκία της Κέρκυρας, εκμεταλλευόμενος το ότι είχε κηρυχθεί πόλεμος στη Βενετία, παρέλαβε ένα προς ένα στο Αιγαίο τα νησιά που εξαρτώνταν απευθείας από τη Βενετία και όχι από το δουκάτο. Η Αίγινα καταλήφθηκε έπειτα από σφοδρή αντίσταση, η Αστυπάλαια, που βρισκόταν στα χέρια της οικογένειας Κουερίνι (Querini), η Κάρπαθος και η Κάσος παραδόθηκαν, και η Πάτμος, που βρισκόταν υπό μοναστηριακή διοίκηση, αποδέχθηκε την οθωμανική προστασία. Το Δουκάτο της Νάξου, αντίθετα, υπήχθη σε φόρο και αφέθηκε στη θέση του· η προσάρτησή του θα περίμενε το 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Εκστρατεία του Μπαρμπαρόσα στο Βόρειο Αιγαίο: κατάληψη της Σκύρου και των Βορείων Σποράδων", "20ab688e"], "d": ["Στον δρόμο προς την Πρέβεζα, ο στόλος παρέλαβε ένα προς ένα τα νησιά του Βορείου Αιγαίου που είχαν καταφύγει στη Βενετία μετά την άλωση της Κωνσταντινούπολης. Η Σκύρος βόρεια της Εύβοιας (Eğriboz) και η Σκιάθος, η Σκόπελος και ο Αλόννησος που κρατούν την είσοδο του κόλπου της Θεσσαλονίκης πέρασαν έτσι στην οθωμανική διοίκηση. Τα νησιά αυτά έκλεισαν το τελευταίο κενό του Βορείου Αιγαίου που παρέμεινε στα βενετικά χέρια για άλλα εξήντα οκτώ χρόνια, αν και η Εύβοια είχε καταληφθεί το 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Κατάληψη του Άντεν και προσάρτηση της ακτής της Υεμένης", "e7d46d8f"], "d": ["Ο στόλος που σάλπαρε από το Σουέζ για την ινδική εκστρατεία στράφηκε πρώτα προς την ακτή της Υεμένης, επειδή δεν μπορούσε να βγει στον ωκεανό χωρίς να εξασφαλίσει την Ερυθρά Θάλασσα. Ο Χαντίμ Σουλεϊμάν Πασάς μπήκε στο λιμάνι του Άντεν στις 3 Αυγούστου 1538· ο ηγεμόνας των Ταχιρίδων Αμίρ μπ. Νταούντ, που έκλινε προς τους Πορτογάλους, οδηγήθηκε στην πύλη του πλοιάρχου και εκτελέστηκε και στην πόλη αφέθηκε φρουρά 500 ατόμων. Κατά την ίδια εκστρατεία παραδόθηκαν και η Μόχα και τα νησιά Καμαράν και Φερασάν, που κυριαρχούν στο στενό, και τέθηκαν τα θεμέλια του μπεηλέρμπεηλικιού της Υεμένης. Έτσι το Οθωμανικό Κράτος απέκτησε για πρώτη φορά ολόκληρη τη βόρεια ακτή του Μπαμπ ελ-Μαντέμπ· η Σανάα και οι εσωτερικές περιοχές θα έπρεπε να περιμένουν άλλα εννέα χρόνια.", "495e1991"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Παραλαβή του Ναυπλίου (Nauplion) με συνθήκη", "104d0937"], "d": ["Ο τριετής πόλεμος με τη Βενετία μετά την Πρέβεζα έληξε όταν η δημοκρατία δέχθηκε να εγκαταλείψει τα δύο τελευταία φρούρια της στον Μοριά. Το Ναύπλιο (Anabolu) και η Μονεμβασιά (Benefşe), που δεν μπόρεσαν να καταληφθούν με πολιορκία, παραδόθηκαν στους Οθωμανούς στο τραπέζι των διαπραγματεύσεων, μαζί με πολεμική αποζημίωση τριακοσίων χιλιάδων δουκάτων. Έτσι η χερσόνησος του Μοριά ενοποιήθηκε χωρίς να μείνει ούτε ένα βενετικό αποτύπωμα.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Είσοδος του Σέγκεντ (Segedin) στην οθωμανική διοίκηση και ίδρυση του λιβά του Σέγκεντ", "019aa000"], "d": ["Μετά την πλήρη εγκαθίδρυση της οθωμανικής διοίκησης στη Βούδα το 1541, οι προύχοντες του Σέγκεντ αποδέχθηκαν την κυριαρχία του Φερδινάνδου Α' και ετοιμάστηκαν για ένοπλη άμυνα. Ο μπεηλέρμπεης της Βούδας Κιουτσούκ Μπαλί Πασάς, στις αρχές του 1543, κάλεσε κοντά του τους διοικούντες της πόλης και τους εκτέλεσε με την αιτιολογία της προδοσίας, και έπειτα έστειλε δύναμη για να καταλάβει την πόλη. Στο μεταξύ ιδρύθηκε το λιβά του Σέγκεντ και στο πρώτο σαντζάκμπεηλίκι διορίστηκε ο Ντερβίς Μπέης, γιος του Μπαλί Πασά· το λιβά αρχικά εκτεινόταν ανάμεσα στον Δούναβη και τον Τίσα.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Κατάκτηση του Βάλπο (Valpo), του Σίκλος (Şikloş) και του Πετς (Peçuy)", "2ca030a3"], "d": ["Ο πρώτος στόχος της εκστρατείας στην Ουγγαρία, που ξεκίνησε δύο χρόνια μετά την προσάρτηση της Βούδας, ήταν η εξασφάλιση του νότιου πλευρού της νέας επαρχίας ανάμεσα στον Δράβο και τον Δούναβη. Αφού καταλήφθηκαν τα φρούρια του Βάλπο και του Σίκλος, παραδόθηκε το Πετς, το κέντρο της Μπαράνυα. Η πόλη θα γινόταν το πιο πολυάνθρωπο και πιο ανοικοδομημένο κέντρο της Οθωμανικής Ουγγαρίας και ο ιστορικός Ιμπραήμ Πετσουιλού (Peçuylu) θα έπαιρνε το όνομά του από εδώ.", "aacf43d3"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Βόρεια και δυτική αμυντική ζώνη της Βούδας: Βάτς (Vaç), Χάτβαν (Hatvan) και Σιμοντόρνυα (Şimontorna)", "733ee5ce"], "d": ["Αφού καταλήφθηκαν ο Έστεργκομ και το Ιστόλνι Μπέλγκραντ, ο μπεηλέρμπεης της Βούδας κινήθηκε χωρίς εκστρατεία του σουλτάνου για να ολοκληρώσει τον δακτύλιο φρουρίων που περιέβαλλε την πρωτεύουσα. Το Βάτς στη στροφή του Δούναβη, το Χάτβαν, η πύλη του Άλφελντ, και η Σιμοντόρνυα στη γραμμή του Σιό παραδόθηκαν ένα προς ένα. Τα κέρδη αυτής της σιωπηλής χρονιάς μετέτρεψαν τη Βούδα από πόλη των συνόρων σε κέντρο επαρχίας που θα άντεχε εκατόν σαράντα χρόνια.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Προσάρτηση της Βασόρας και έξοδος στον Περσικό Κόλπο", "02f87c11"], "d": ["Ο ηγεμόνας της Βασόρας Ρασίντ μπ. Μεγκάμις είχε δηλώσει υποταγή στον Σουλεϊμάν τον Μεγαλοπρεπή κατά την κατάκτηση της Βαγδάτης (1534) και το 1538 είχε στείλει τα κλειδιά της πόλης. Όταν ο διάδοχός του Σεΐχης Γιαχιά στράφηκε εναντίον των Οθωμανών, ο μπεηλέρμπεης της Βαγδάτης Αγιάς Πασάς βάδισε από την ξηρά και ο σαντζάκμπεης της Μοσούλης με 120 πλοία από τον Ευφράτη· ο Αγιάς Πασάς μπήκε στη Βασόρα στις 26 Δεκεμβρίου 1545 και η πόλη έγινε κέντρο μπεηλέρμπεηλικιού. Το λιμάνι αυτό στις εκβολές του Σατ ελ-Αράμπ ήταν η πύλη μέσω της οποίας η Οθωμανική Αυτοκρατορία άνοιξε στον Κόλπο που έλεγχε η Πορτογαλία από το Ορμούζ· με τη Συνθήκη της Αμάσειας το 1555 και το Ιράν αναγνώρισε αυτή την κατάσταση.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Κατάκτηση της Σανάα και της ενδοχώρας της Υεμένης", "d31ded85"], "d": ["Μετά την Ταΐζ καταλήφθηκε και η Σανάα και ολόκληρη η χώρα υπήχθη στο μπεηλέρμπεηλίκι. Ωστόσο, λόγω της απόκρημνης γεωγραφίας και της διαφοράς δόγματος, η κυριαρχία αυτή δεν υπήρξε ποτέ άνετη· η Υεμένη έγινε για τους Οθωμανούς ένα μέτωπο που συνεχώς κατάπινε στρατεύματα.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Κατάκτηση της Ταΐζ (Taiz)", "d4509df9"], "d": ["Στην Υεμένη, όπου εννέα χρόνια πριν είχαν περιοριστεί στη λωρίδα της ακτής, καθώς οι ιμάμηδες των Ζαϊντιτών ενισχύονταν σταδιακά στην ορεινή ενδοχώρα, οι δυνάμεις του Οζντεμίρ Πασά ανέβηκαν στο οροπέδιο και κατέλαβαν την Ταΐζ.", "46b811eb"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Δεύτερη Εκστρατεία στο Ιράν και ανακατάληψη της Ταμπρίζ", "e82365df"], "d": ["Στην εκστρατεία που έγινε με την παρότρυνση του Ελκάς Μιρζά, αδελφού του Σάχη Ταχμάσπ, ο οποίος είχε στασιάσει εναντίον του και είχε καταφύγει στην Κωνσταντινούπολη, ο στρατός μπήκε για δεύτερη φορά στην Ταμπρίζ. Επειδή οι Σαφαβίδες αποσύρθηκαν πάλι χωρίς να δώσουν ανοιχτή μάχη, καίγοντας τη γη, στην πόλη μπόρεσαν να μείνουν μόνο λίγες εβδομάδες. Η εκστρατεία κατέστησε βέβαιο ότι η Ταμπρίζ δεν θα μπορούσε να κρατηθεί και έστρεψε τη στρατηγική των Οθωμανών στη δημιουργία μιας μόνιμης γραμμής συνόρων, δηλαδή στην οχύρωση του Βαν.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Κατάκτηση του Βαν και σταθεροποίηση των ανατολικών συνόρων", "fc8f930b"], "d": ["Το φρούριο του Βαν, που πολιορκήθηκε στην επιστροφή από την Ταμπρίζ, με τη θέση του που υψωνόταν πάνω σε βράχο στην ανατολική όχθη της λίμνης ήταν αδιαφιλονίκητα το κλειδί της περιοχής και παραδόθηκε έπειτα από σύντομη πολιορκία. Η πόλη έγινε αμέσως κέντρο μπεηλέρμπεηλικιού· τα σαντζάκια του Ερτσίς, του Αντιλτζεβάζ και του Χακκιάρι υπήχθησαν σε αυτό. Σε αντίθεση με την Ταμπρίζ, το Βαν κρατήθηκε και παρέμεινε επί τετρακόσια χρόνια το πιο προωθημένο μόνιμο οχυρό των Οθωμανών στα ανατολικά.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Προσάρτηση της Λαχσά και του Κατίφ — η αραβική ακτή του Κόλπου", "f6701e60"], "d": ["Μετά την κατάληψη της Βασόρας καταλήφθηκε το Κατίφ, που είχε γίνει προωθημένο φυλάκιο της Πορτογαλίας στη δυτική ακτή του κόλπου, και μαζί με τις όασεις της Λαχσά στην ενδοχώρα ιδρύθηκε ένα νέο μπεηλέρμπεηλίκι. Από εδώ ξεκινούσαν οι επιχειρήσεις προς το Μπαχρέιν και το Ορμούζ. Έτσι το Οθωμανικό Κράτος απέκτησε λόγο ταυτόχρονα στις ακτές της Ερυθράς Θάλασσας και του Περσικού Κόλπου της αραβικής χερσονήσου.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Απώλεια του Σεχριζόρ — ο μπέης του Αρντελάν Σουχράμπ στράφηκε προς τους Σαφαβίδες", "5600efc9"], "d": ["Η περιοχή του Σεχριζόρ, που είχε αναγνωρίσει την οθωμανική διοίκηση κατά την Εκστρατεία των Δύο Ιράκ (1535), βρισκόταν υπό τη διοίκηση του εμίρη του Αρντελάν Μπιγκέ Μπέη, που κατοικούσε στο Φρούριο του Ζαλμ. Όταν ο Μπιγκέ Μπέης πέθανε το 1550, ο αδελφός του Σουχράμπ, που κατέλαβε το Φρούριο του Ζαλμ και κυριάρχησε στο μπεηλίκι, στράφηκε προς τους Σαφαβίδες και αποστάτησε από την υποταγή στους Οθωμανούς· έτσι η περιοχή του Σεχριζόρ βγήκε από την οθωμανική επιρροή. Η περιοχή ανακτήθηκε μόλις το 1554, κατά την εκστρατεία του Ναχτσιβάν, με την πολιορκία και κατάληψη του Φρουρίου του Ζαλμ.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Κατάληψη του Αρντάχαν και της λεκάνης του Τσίλντιρ", "14c9eb76"], "d": ["Ο μπεηλέρμπεης του Ερζερούμ, κατά τον πόλεμο που συνεχιζόταν με τους Σαφαβίδες, στράφηκε προς τα εδάφη των Γεωργιανών αταμπέηδων στο τόξο του Κουρ και υπήγαγε το Αρντάχαν και την περιοχή του Τσίλντιρ στην οθωμανική διοίκηση. Έτσι ενοποιήθηκε η γραμμή Καρς-Αρντάχαν και τέθηκαν υπό έλεγχο τα οροπέδια που ανοίγουν προς τη Γεωργία στα βορειοανατολικά. Η οριστική διοικητική τάξη της περιοχής θα ολοκληρωνόταν με το έγιαλετ του Τσίλντιρ που θα ιδρυόταν είκοσι επτά χρόνια αργότερα.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Ο Σοκολλού Μεχμέτ Πασάς πέρασε τον Δούναβη — έναρξη του πολέμου της Τρανσυλβανίας", "38fde931"], "d": ["Εξαιτίας των αναταραχών που προκάλεσε ο μοναχός Μαρτινούτσι (Martinuzzi), επίτροπος του βασιλιά της Τρανσυλβανίας του ανήλικου Ιάνος Ζίγκμοντ (János Zsigmond), και της παραχώρησης των φρουρίων του Μπανάτ από την Τρανσυλβανία στον Φερδινάνδο, κρίθηκε αναγκαία νέα εκστρατεία· η διοίκηση ανατέθηκε στον μπεηλέρμπεη της Ρούμελης Σοκολλού Μεχμέτ Πασά. Ο στρατός, παρά τις προσπάθειες του Μαρτινούτσι να τον καθυστερήσει, πέρασε τον Δούναβη και κατέλαβε το Μπετσέ, το Μπετσκερέκ, το Τσανάντ και το Λίπα· ωστόσο η πολιορκία του Τεμεσβάρ λύθηκε στις 16 Νοεμβρίου λόγω του ψύχους. Έτσι ξεκίνησε στην Ουγγαρία ένας νέος οθωμανο-αψβουργικός πόλεμος.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Η πόλη Λίπα (Lipova, Lippa) πέρασε στα χέρια του αυστριακού στρατού του Καστάλντο — το φρούριο παραδόθηκε στις 5 Δεκεμβρίου", "a0e1ff0d"], "d": ["Τη Λίπα (Lipova), που κατέλαβε ο Σοκολλού Μεχμέτ Πασάς τον Οκτώβριο του 1551, πολιόρκησε ο στρατός του στρατηγού Καστάλντο στις 4 Νοεμβρίου· δύο ημέρες αργότερα η πόλη πέρασε στα χέρια των Αυστριακών. Ο Ουλαμά Πασάς με φρουρά 5.000 ανδρών υπερασπίστηκε το φρούριο για άλλες εννέα ημέρες και αποχώρησε με συμφωνία στις 5 Δεκεμβρίου 1551. Έως την πτώση του Τεμεσβάρ το 1552 η Λίπα παρέμεινε στα χέρια των Αψβούργων.", "22c85b1c"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Κατάκτηση του Σόλνοκ και αποτυχία της πολιορκίας του Έγκρι", "a7156e8f"], "d": ["Οι δύο οθωμανικοί στρατοί που ενώθηκαν μετά την κατάληψη του Τεμεσβάρ κατέλαβαν σχεδόν χωρίς μάχη το Σόλνοκ στον Τίσα, καθώς οι μισθοφόροι φρουροί εγκατέλειψαν το φρούριο. Ακολούθως το φρούριο του Έγκρι (Eğri), που πολιορκήθηκε, δεν μπόρεσε να καταληφθεί μπροστά στην τριανταοκτάήμερη αντίσταση της φρουράς δύο χιλιάδων ανδρών υπό τον Ίστβαν Ντόμπο (István Dobó) και ο στρατός αποσύρθηκε με την έλευση του χειμώνα. Το ότι στην ίδια εκστρατεία ένα φρούριο έπεσε εύκολα ενώ ένα άλλο άντεξε ήταν το πρώτο ανοιχτό σημάδι ότι τα σύνορα στην Ουγγαρία δεν προχωρούσαν πλέον αυτομάτως υπέρ των Οθωμανών.", "354ed31f"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Μετατόπιση των συνόρων του Ιμπρίμ και της Νουβίας προς το νότο", "c57d5d77"], "d": ["Το νότιο σύνορο του μπεηλέρμπεηλικιού της Αιγύπτου μετατοπίστηκε πέρα από τον δεύτερο καταρράκτη, με την οχύρωση του φρουρίου του Ιμπρίμ (İbrim), που υψώνεται πάνω σε βραχώδες ακρωτήριο στον Νείλο, από τον Οζντεμίρ Μπέη και την πλήρη ένταξη της Κάτω Νουβίας στην Οθωμανική Αίγυπτο. (Η οθωμανική διοικητική οργάνωση στο Ιμπρίμ είχε ιδρυθεί μετά την κατάκτηση της Αιγύπτου· στον χάρτη το Ιμπρίμ εμφανίζεται οθωμανικό από το 1517. Η χρονιά αυτή είναι κατά προσέγγιση, η πηγή δεν δίνει έτος.) Το φρούριο ήταν όσο ένα ανάχωμα απέναντι στις επιδρομές από τη Νουβία, άλλο τόσο σημείο ελέγχου του δρόμου του χρυσού και των σκλάβων προς τη Σενάαρ. Η φρουρά Βοσνίων που τοποθετήθηκε εκεί έγινε τόσο μόνιμη, ώστε οι απόγονοί τους βρίσκονταν ακόμη στο φρούριο τριακόσια χρόνια αργότερα. Οι πηγές δίνουν δύο διαφορετικές αφηγήσεις για τον χρόνο εισόδου του Ιμπρίμ στην οθωμανική διοίκηση: το λήμμα Sudan του TDV συνδέει την ένταξη της Κάτω Νουβίας στην Οθωμανική Αίγυπτο με την επιχείρηση του Οζντεμίρ Πασά στα μέσα του 16ου αιώνα, ενώ το λήμμα Nûbe γράφει ότι η περιοχή έως την κοιλάδα του Χάλφα και η διοικητική οργάνωση στο Ιμπρίμ ιδρύθηκαν αμέσως μετά την κατάκτηση του 1517. Το σαντζάκι του Ιμπρίμ υπήχθη στο έγιαλετ της Αβησσυνίας (Habeş) στις 26 Ιουλίου 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Ανάκτηση της Μπιτζάγιε (Bicâye, Bougie) από τους Ισπανούς", "49691cda"], "d": ["Η Μπιτζάγιε, που βρισκόταν επί σαράντα τρία χρόνια στα χέρια της Ισπανίας και χώριζε στα δύο την ακτή ανάμεσα στο Αλγέρι και την Κωνσταντίνη, παραδόθηκε μετά από πολιορκία από ξηρά και θάλασσα. Με την πτώση του φρουρίου η ακτή του οτζακιού του Αλγερίου έγινε συνεχής έως το Ορράν (Vehran). Η απώλεια αυτή προκάλεσε στην Ισπανία τόσο μεγάλη αγανάκτηση, ώστε ο διοικητής Alonso de Peralta, που παρέδωσε το φρούριο, εκτελέστηκε στην πατρίδα του.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Ένταξη της Ζεϊλά στο Έγιαλετ της Αβησσυνίας", "7bbf369a"], "d": ["Στο νότιο άκρο του έγιαλετ της Αβησσυνίας, το λιμάνι της Ζεϊλά στην αφρικανική ακτή του Κόλπου του Άντεν υπήχθη στην οθωμανική διοίκηση. Η πόλη αυτή, που ήταν η πύλη του Σουλτανάτου του Αντάλ προς τη θάλασσα, ήταν το τελευταίο σημείο ανεφοδιασμού για τα πλοία που έβγαιναν πέρα από το Μπαμπ ελ-Μαντέμπ. Με την ένταξη της Ζεϊλά τα σύνορα του Οθωμανικού Κράτους στην Αφρική έφτασαν στο νοτιότερο σημείο τους.", "fe4597b7"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Κατάληψη της Χίου από τους Γενουάτες", "a4559b96"], "d": ["Η Χίος, που διοικούνταν επί διακόσια χρόνια ως εμπορική αποικία της οικογένειας Τζιουστινιάνι (Giustiniani) της Γένοβας και κατέβαλλε φόρο στους Οθωμανούς, παραδόθηκε στον Πιγιαλέ Πασά χωρίς να πέσει ούτε μία σφαίρα, με την αιτιολογία ότι καθυστερούσε τον φόρο και παρείχε λιμάνι σε εχθρικά πλοία. Μαζί με τη Χίο και τα Ψαρά εκκαθαρίστηκε και η τελευταία γενοβέζικη παρουσία στην ανατολική ακτή του Αιγαίου. Το νησί, διατηρώντας την παραγωγή μαστίχας και τα προνόμια των Χιωτών, υπήχθη στο έγιαλετ Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Προσάρτηση του Δουκάτου της Νάξου — το σύνολο των Κυκλάδων", "68f0ec0b"], "d": ["Το λατινικό Δουκάτο της Νάξου, που διαρκούσε από το 1207 και κατέβαλλε φόρο στους Οθωμανούς από το 1537, καταργήθηκε με αιτιολογία τα παράπονα που έφτασαν επειδή ο τελευταίος δούκας Τζάκομο Κρίσπο (Giacomo Crispo) καταπίεζε τον λαό του. Η Νάξος, η Πάρος, ο Αντίπαρος (Değirmenlik), η Άνδρος, η Σύρος, η Μύκονος, η Ίος (Nio), η Αμοργός (Yamurgi) και όλα τα Κυκλαδονήσια γύρω τους πέρασαν με μία μόνη απόφαση απευθείας στην οθωμανική διοίκηση. Ο Σουλεϊμάν ο Μεγαλοπρεπής ανέθεσε για ένα διάστημα τη διοίκηση των νησιών στον Γιασέφ Νάσι (Yasef Nasi)· η τριάμισι αιώνων λατινική κυριαρχία έληξε έτσι στο μέσο του Αιγαίου.", "d4d7a143"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Απόβαση στην Κύπρο: κατάληψη της Λεμεσού", "9074ccc9"], "d": ["Ο οθωμανικός στρατός που αποβιβάστηκε στο νησί κατέλαβε τη Λεμεσό χωρίς μεγάλη αντίσταση και την επομένη στράφηκε προς τη Λάρνακα. Χάρη στη δυσαρέσκεια του ντόπιου λαού με τη βενετική διοίκηση και στη βοήθεια που πρόσφερε στις οθωμανικές δυνάμεις, δεν συναντήθηκε σοβαρή αντίσταση ούτε στη Λάρνακα· η Σκάλα της Τούζλας (Tuzla İskelesi) έγινε βάση απόβασης στρατού και εξοπλισμού. Η Βενετία είχε συγκεντρώσει την άμυνά της στη Λευκωσία και την Αμμόχωστο· ο διοικητής της Πάφου δήλωσε υποταγή στον σερασκέρη μόνο αφού έπεσε η Λευκωσία.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Παράδοση της Κερύνειας — η βόρεια ακτή της Κύπρου", "39fdeea5"], "d": ["Η πτώση της Λευκωσίας στις 9 Σεπτεμβρίου, με σφαγή, έσπασε την αντίσταση στον βορρά της Κύπρου. Το φρούριο της Κερύνειας πίσω από το όρος Πενταδάκτυλος, όταν έμαθε την τύχη της πρωτεύουσας, παραδόθηκε υπό όρους οκτώ ημέρες αργότερα και η φρουρά του στάλθηκε εκτός του νησιού με άδεια αποχώρησης. Στο νησί η βενετική σημαία παρέμεινε μόνο στην Αμμόχωστο· και αυτή θα άντεχε ακόμη έντεκα μήνες.", "ecf762c9"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Δήλωση υποταγής των κατοίκων του Ντερμπέντ στον Λαλά Μουσταφά Πασά — η Σιδηρά Πύλη (Demirkapı) υπό οθωμανική διοίκηση", "9c55aeff"], "d": ["Κατά την εκστρατεία του Σιρβάν, μια επταμελής αντιπροσωπεία των κατοίκων του Ντερμπέντ πήγε στον σερασκέρη Λαλά Μουσταφά Πασά, που βρισκόταν στο Ερές, και δήλωσε υποταγή. Το Ντερμπέντ (Demirkapı), που φράζει το στενό πέρασμα ανάμεσα στο τείχος του Καυκάσου και την Κασπία Θάλασσα, ως υποχρεωτικό πέρασμα των χερσαίων δρόμων από τον βορρά έπαιξε κομβικό ρόλο στη διατήρηση του Σιρβάν. Η οθωμανική κυριαρχία εδώ διήρκεσε έως το 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Κατάκτηση του Σιρβάν: κατάληψη της Σαμαχί", "9afae4c1"], "d": ["Ο στρατός που άνοιξε προς τον Καύκασο μετά τη Νίκη του Τσίλντιρ μπήκε στο Σιρβάν, το πλουσιότερο έγιαλετ των Σαφαβιδών στην ακτή της Κασπίας, και κατέλαβε το κεντρικό της πόλη Σαμαχί. Ο Οζντεμιρόγλου Οσμάν Πασάς διορίστηκε εκεί μπεηλέρμπεης και ο βόρειος κλάδος του Δρόμου του Μεταξιού τέθηκε υπό οθωμανικό έλεγχο. Το Σιρβάν επρόκειτο να γίνει το μέτωπο που άλλαξε περισσότερες φορές χέρια και στοίχισε ακριβότερα στον δωδεκαετή ανατολικό πόλεμο.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Κατάληψη του Μπακού — έξοδος στην ακτή της Κασπίας", "eb5adab8"], "d": ["Ως τελευταίος κρίκος της επιχείρησης του Σιρβάν καταλήφθηκε το λιμάνι του Μπακού στη δυτική ακτή της Κασπίας Θάλασσας. Τα πηγάδια νάφθας γύρω από την πόλη ήταν ήδη τότε γνωστή πηγή εσόδων και το λιμάνι ήταν το σημείο εξόδου του περσικού μεταξιού που έφτανε μέσω της Κασπίας. Έτσι το Οθωμανικό Κράτος απέκτησε για πρώτη και μοναδική φορά στην ιστορία του ακτή στην Κασπία Θάλασσα.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Κατάκτηση του Ρεβάν (Ερεβάν) και κατασκευή φρουρίου", "7f623b7b"], "d": ["Ο Φερχάτ Πασάς, που έλαβε στο Καρς διαταγή να πάει στο Ρεβάν και να χτίσει εκεί φρούριο, βάδισε προς το Ρεβάν και η πόλη τέθηκε υπό οθωμανικό έλεγχο στις αρχές του Ραμαζανιού του 991 (στα μέσα Σεπτεμβρίου 1583). Στο Ρεβάν, που κρατά τη βόρεια πύλη της κοιλάδας του Αράξη, χτίστηκε ένα νέο και μεγάλο φρούριο· η πόλη έγινε κέντρο μπεηλέρμπεηλικιού. Το Ρεβάν, που βρίσκεται στο μέσον του στρατιωτικού δρόμου ανάμεσα στο Καρς και την Ταμπρίζ, ήταν η εφοδιαστική ραχοκοκαλιά του ανατολικού μετώπου. Το φρούριο χτίστηκε τόσο γερό, ώστε για τα επόμενα διακόσια χρόνια έγινε ο αμετάβλητος στόχος των οθωμανοπερσικών πολέμων.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Προσάρτηση του Καραμπάχ και της Γκιάντζα", "29abaead"], "d": ["Ως το τελευταίο κέρδος του δεκαετούς ανατολικού πολέμου, ο Φερχάτ Πασάς βάδισε το 1588 προς τη Γκιάντζα (Gence) και στην 1η Σεπτεμβρίου μπήκε στην πόλη· η περιοχή του Καραμπάχ ανάμεσα στον Κουρ και τον Αράξη και το κέντρο της Γκιάντζα υπήχθησαν στην οθωμανική διοίκηση. Έτσι το Σιρβάν, το Ρεβάν και το Καραμπάχ ενώθηκαν και σχηματίστηκε μια αδιάκοπη οθωμανική γραμμή στον Καύκασο. Η Συνθήκη του Φερχάτ Πασά, που υπογράφηκε το 1590, θα κατοχύρωνε αυτά τα σύνορα, ωστόσο το κέρδος μπόρεσε να κρατηθεί μόνο είκοσι χρόνια.", "67f1d89d"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Η ανάκτηση του Ορμούζ από τους Πορτογάλους", "93e5f6cf"], "d": ["Οι δυνάμεις των Σαφαβιδών πολιόρκησαν και ανακατέλαβαν το Ορμούζ, που βρισκόταν στα χέρια των Πορτογάλων από το 1515· το Κεσμ και το παράκτιο Γκαμρούν (Μπεντέρ Αμπάς) πέρασαν επίσης στη διοίκηση των Σαφαβιδών και το εμπόριο του Κόλπου μετατοπίστηκε στο νέο λιμάνι.", "cc55e4bf"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Κατάκτηση του Ρεθύμνου — διαίρεση της Κρήτης στα δύο", "8f2c4353"], "d": ["Ένα χρόνο μετά την κατάληψη των Χανίων έπεσε και το φρούριο του Ρεθύμνου στο κέντρο του νησιού και το δυτικό μισό της Κρήτης πέρασε εξ ολοκλήρου στην οθωμανική διοίκηση. Στη Βενετία απέμειναν μόνο η πρωτεύουσα Κάντια και το ανατολικό άκρο· το νησί έζησε επί είκοσι τρία χρόνια χωρισμένο στα δύο. Η κατάληψη του Ρεθύμνου ήταν το βήμα που ξεκίνησε την πολιορκία της Κάντιας — εδώ ξεκίνησε η μακρύτερη πολιορκία της ιστορίας.", "88ec9840"]},
"OLAYLAR_EK5:1657-11-15:0":{"b": ["Ανάκτηση της Λήμνου από τη Βενετία", "a4c3c69b"], "d": ["Η Λήμνος, που κατέλαβε η Βενετία τον Ιούλιο του 1656, επέστρεψε στους Οθωμανούς τον Νοέμβριο του 1657.", "1d61fe33"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Ανακατάληψη της Αθήνας — αποχώρηση της Βενετίας", "03393b46"], "d": ["Ο Μοροζίνι, που τον Σεπτέμβριο του 1687 βομβάρδισε την Ακρόπολη και ανατίναξε τον Παρθενώνα, αφού πέρασε τον χειμώνα στην Αθήνα, κατάλαβε ότι δεν θα μπορούσε να κρατηθεί στην πόλη. Με την επιδημία πανούκλας, τη δυσκολία ανεφοδιασμού και την ανασυγκρότηση των οθωμανικών δυνάμεων, η βενετική φρουρά εκκένωσε την πόλη και αποσύρθηκε στον Μοριά. Έτσι η Αθήνα επέστρεψε χωρίς μάχη στην οθωμανική διοίκηση, ωστόσο η καταστροφή που υπέστη ο Παρθενώνας δεν αναιρέθηκε.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Η Λίπα (Lipova, Lippa) παραδόθηκε στον Καράφα — πέρασε στα χέρια της Αυστρίας", "7f0a8d38"], "d": ["Μετά την τριήμερη πολιορκία του Αντόνιο Καράφα (Antonio Caraffa), η Λίπα παραδόθηκε μεταξύ 12 και 22 Ιουνίου 1688 και πέρασε στα χέρια της Αυστρίας. Οι Οθωμανοί αργότερα ανέκτησαν την πόλη, η Αυστρία την ξανακατέλαβε το 1691· στην εκστρατεία του 1695 οι Οθωμανοί εξασφάλισαν ξανά τον έλεγχο. Άλλοι οικισμοί που στον άτλαντα πέρασαν την ίδια ημερομηνία από τους Οθωμανούς στους Αψβούργους: Arad και Világos (Şiria). Για το Arad η πηγή δίνει μόνο το έτος (MKL, Arad: μεταξύ 1551-1688 στα οθωμανικά χέρια)· η ημέρα λαμβάνεται από τη Λίπα, το Világos ακολουθεί την αλυσίδα του Arad (δηλωμένη προσέγγιση).", "0dfcf5af"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Θάνατος του Σουλεϊμάν Β'", "d2478080"], "d": ["Ο Σουλεϊμάν Β', που ανέβηκε στον θρόνο το 1687 έπειτα από σαράντα περίπου χρόνια στο κλουβί (kafes), ενώ άρρωστος παρακολουθούσε τις προετοιμασίες του στρατού, πέθανε στην Αδριανούπολη προς το μεσημέρι της Παρασκευής 22 Ιουνίου 1691· η βασιλεία του διήρκεσε τρία χρόνια, οκτώ μήνες και δύο ημέρες. Ο Μέγας Βεζίρης είχε δώσει από πριν τις απαραίτητες οδηγίες ώστε σε περίπτωση θανάτου του σουλτάνου να ανέβει στον θρόνο ο αδελφός του Αχμέτ. Η νεκρώσιμη προσευχή έγινε την ίδια ημέρα στο Alay Köşkü· η σορός μεταφέρθηκε στην Κωνσταντινούπολη και τάφηκε στο μαυσωλείο του Σουλεϊμάν του Μεγαλοπρεπούς, στα δεξιά του.", "3cf4fcb1"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Θάνατος του Μεχμέτ Δ' στην Αδριανούπολη", "17388b7e"], "d": ["Ο Αβτζί Μεχμέτ, που καθαιρέθηκε το 1687, μεταφέρθηκε στην Αδριανούπολη κατά την ουγγρική εκστρατεία του Σουλεϊμάν Β' το 1689 και είδε και τη βασιλεία του άλλου αδελφού του, του Αχμέτ Β'. Πέθανε στην πόλη αυτή που αγαπούσε πολύ. Η σορός του μεταφέρθηκε στην Κωνσταντινούπολη και τάφηκε στο μαυσωλείο της μητέρας του Τουρχάν Σουλτάν δίπλα στο Γενί Τζαμί.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Θάνατος του Αχμέτ Β' στην Αδριανούπολη", "c6306c08"], "d": ["Ο Αχμέτ Β', του οποίου η τετραετής βασιλεία πέρασε μέσα σε πόλεμο, πέθανε στην Αδριανούπολη σε ηλικία πενήντα δύο ετών από istiskā (υδρωπικία). Η σορός του μεταφέρθηκε στην Κωνσταντινούπολη και τάφηκε στο μαυσωλείο του Σουλεϊμάν του Μεγαλοπρεπούς. Στη θέση του ανέβηκε ο ανιψιός του Μουσταφά Β'.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Κατάληψη της Βασόρας από τους Πέρσες", "a9cdf3a3"], "d": ["Ενώ το Οθωμανικό Κράτος ήταν απασχολημένο στα δυτικά με τους πολέμους της Ιεράς Συμμαχίας, η Βασόρα, μετά την επιδημία πανούκλας του 1690, είχε υποστεί λεηλασία πρώτα από τον σεΐχη των Μουντεφίκ Μανί και έπειτα από τον Φερεγουλλάχ, χάνη της Χουβεΐζε. Οι Πέρσες, εκμεταλλευόμενοι αυτή τη σύγχυση, κατέλαβαν την πόλη το 1696 και άφησαν στη Βασόρα μια φρουρά.", "2db76d27"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Ανακατάληψη της Κούρνα και της Βασόρας από τον Νταλταμπάν Μουσταφά Πασά", "7adb777d"], "d": ["Ο Νταλταμπάν Μουσταφά Πασάς, που διορίστηκε βαλής της Βαγδάτης και σεράσκερης της Βασόρας μετά τη Συνθήκη του Κάρλοβιτς, βάδισε προς τον νότο με δυνάμεις από το Χαλέπι, τη Ράκκα, τη Σεβάστεια και το Καραμάν και με έναν ποτάμιο στόλο που κατέβηκε από το Μπιρετζίκ. Οι σεΐχηδες των φυλών της περιοχής υποτάχθηκαν ένας ένας, ο Νταούντ Χαν, φρούραρχος του Ιράν στη Βασόρα, εγκατέλειψε την πόλη και η Κούρνα και η Βασόρα πέρασαν ξανά στην οθωμανική διοίκηση.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Θάνατος του Μουσταφά Β'", "626c394d"], "d": ["Ο Μουσταφά Β', που με το Επεισόδιο της Αδριανούπολης άφησε τον θρόνο στον αδελφό του Αχμέτ Γ', πέθανε στην Αδριανούπολη, που αγαπούσε πολύ, περίπου πέντε μήνες μετά την καθαίρεσή του. Στην ασθένειά του προστέθηκε και η θλίψη για τις τελευταίες εξελίξεις. Μερικές δυτικές πηγές γράφουν ότι ήταν διαδεδομένη στον λαό η πεποίθηση ότι δηλητηριάστηκε.", "8ce146e8"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Τήνος (İstendil): παράδοση του τελευταίου νησιού της Βενετίας στο Αιγαίο", "4abec891"], "d": ["Ο στόλος που ξεκίνησε για την εκστρατεία του Μοριά ναυλόχησε στον δρόμο μπροστά από την Τήνο (İstendil), το μοναδικό νησί που απέμενε στη Βενετία στο Αιγαίο. Το νησί, που χάρη στον λατινικό πληθυσμό του είχε κρατήσει τη βενετική σημαία για άλλα εκατόν πενήντα χρόνια, αν και το Δουκάτο της Νάξου είχε πέσει το 1566, παραδόθηκε χωρίς αίμα έπειτα από σύντομη πολιορκία. Έτσι σβήστηκε το τελευταίο αποτύπωμα της Βενετίας στο Αιγαίο Πέλαγος και η θάλασσα έγινε εξ ολοκλήρου οθωμανική εσωτερική θάλασσα.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Κατάκτηση του Ναυπλίου (Anabolu) — το κλειδί φρούριο του Μοριά", "62a5808a"], "d": ["Το Ναύπλιο (Anabolu), η πρωτεύουσα της Βενετίας στον Μοριά και το ισχυρότερο οχυρό της, έπεσε με την κατάληψη του προμαχώνα του Παλαμηδίου έπειτα από εννεαήμερο βομβαρδισμό. Η τόσο γρήγορη κατάληψη του φρουρίου έσπασε την αντίσταση στο υπόλοιπο της χερσονήσου. Η ανάκτηση του Μοριά, που χάθηκε στο Κάρλοβιτς, ολοκληρώθηκε ουσιαστικά εδώ. Άλλος οικισμός που στον άτλαντα πέρασε την ίδια ημερομηνία από τη Βενετία στους Οθωμανούς: Argos — ακολουθεί την αλυσίδα του αδελφού-κέντρου (abi-merkez) του Ναυπλίου (TDV anabolu· δηλωμένη προσέγγιση).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Παράδοση της Μεθώνης (Modon)", "43faa909"], "d": ["Μετά την πτώση του Ναυπλίου, το φρούριο της Μεθώνης στο νοτιοδυτικό άκρο του Μοριά, πολιορκημένο από τον στρατό από την ξηρά και από τον στόλο από τη θάλασσα, παραδόθηκε σε σύντομο χρόνο. Το λιμάνι αυτό, που η Βενετία χρησιμοποιούσε επί διακόσια χρόνια στις εκστρατείες της στην Ανατολική Μεσόγειο, ήταν το αναγκαίο σημείο όπου τα πλοία έπαιρναν νερό και τρόφιμα. Η απώλειά του τερμάτισε την ικανότητα κίνησης του βενετικού στόλου στο Αιγαίο.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Παράδοση της Κορώνης (Koron) — ολοκλήρωση της εκστρατείας του Μοριά", "e4b9c8a4"], "d": ["Με την παράδοση του φρουρίου της Κορώνης, που κρατά την είσοδο του κόλπου της Μεσσηνίας, η βενετική διοίκηση στη χερσόνησο του Μοριά έληξε εντελώς. Η χερσόνησος που χάθηκε στο Κάρλοβιτς ανακτήθηκε ολοκληρωτικά μόλις τρεις μήνες μετά την έναρξη της εκστρατείας. Στη συνέχεια της ίδιας εκστρατείας, τον Σεπτέμβριο του 1715, καταλήφθηκε από τη Βενετία και το νησί της Αγίας Μαύρας (Λευκάδα) στο Ιόνιο. Η ταχύτητα αυτή ανάγκασε τη Βενετία να σύρει την Αυστρία στον πόλεμο και άνοιξε τον δρόμο προς το Πασαρόβιτς τρία χρόνια αργότερα.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Κατάληψη του Τσούχα Αντασί (Çuha Adası, Κύθηρα)", "494de6c6"], "d": ["Το Τσούχα Αντασί στο νότιο άκρο του Μοριά παραλήφθηκε από τον στόλο μετά την ολοκλήρωση της χερσονήσου. Το νησί, που επιτηρεί το πέρασμα ανάμεσα στο Ιόνιο και το Αιγαίο, ήταν το προωθημένο φυλάκιο που χρησιμοποιούσε η Βενετία για να ελέγχει αυτά τα νερά. Ωστόσο δεν παρέμεινε το μοναδικό οθωμανικό νησί που κρατήθηκε: τρία χρόνια αργότερα επεστράφη στη Βενετία στο Πασαρόβιτς.", "42162c0d"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Συνθήκη του Πασαρόβιτς — κερδήθηκε ο Μοριάς, χάθηκαν το Βελιγράδι και το Μπανάτ", "d46aa216"], "d": ["Ο Μοριάς είχε ανακτηθεί από τη Βενετία, ωστόσο η Αυστρία, που μπήκε στον πόλεμο, με τις νίκες που κέρδισε στο Πετροβαραντίν και στο Βελιγράδι επικράτησε στο τραπέζι των διαπραγματεύσεων. Η συνθήκη που υπογράφηκε με τη μεσολάβηση της Αγγλίας και της Ολλανδίας άφησε τον Μοριά στους Οθωμανούς, ενώ σε αντάλλαγμα η Βόρεια Σερβία μαζί με το Βελιγράδι, το Μπανάτ και η Μικρή Βλαχία παραχωρήθηκαν στην Αυστρία· κατά τη διατύπωση του TDV «η Βόρεια Βοσνία παραχωρήθηκε εξ ολοκλήρου στην Αυστρία» — φρούρια όπως το Μπόσνα Ντουμπίτσα και το Μπόσνα Μπροντ κατά μήκος του Σάβα περνούν στον χάρτη από αυτή την ημέρα στην Αυστρία (τα ακριβή σύνορα τα χάραξαν ένα προς ένα επιτροπές, το TDV δεν απαριθμεί αυτά τα φρούρια με το όνομά τους)· η Βενετία, από την άλλη, διατήρησε θέσεις της στην ακτή του Ιονίου όπως η Πρέβεζα και τα Κύθηρα (Çuha). Με τη συμφωνία εμπορίου (ahidnâme) που υπογράφηκε την ίδια ημέρα, ο δασμός που εισπραττόταν από τα αυστριακά εμπορεύματα μειώθηκε από πέντε τοις εκατό σε τρία. Η συνθήκη, ενώ κατοχύρωνε την οθωμανική υποχώρηση στην Κεντρική Ευρώπη, έθεσε το έδαφος της Εποχής των Τουλιπών (Lâle Devri, 1718-1730) με την εικοσιεπτάχρονη ειρήνη που άνοιξε: το πρώτο οθωμανικό τυπογραφείο (1727, Ιμπραήμ Μουτεφερρίκα), οι επιτροπές μετάφρασης, οι παρατηρήσεις για τον εμβολιασμό κατά της ευλογιάς και μια νέα ανακτορική-πολιτιστική ζωή, υπό τη διοίκηση του Νεβσεχιρλί Νταμάτ Ιμπραήμ Πασά, είναι προϊόντα αυτών των ετών ειρήνης. Άλλοι οικισμοί που άλλαξαν χέρια την ίδια ημέρα στον άτλαντα: Craiova (Krayova), Râmnicu Vâlcea (Rimnik) και Turnu Severin (Μικρή Βλαχία/Ολτενία, από τους Οθωμανούς στην Αυστρία) καθώς και η Αγία Μαύρα (Λευκάδα) (από τους Οθωμανούς στη Βενετία· TDV ayamavra: το 1718 με τη Συνθήκη του Πασαρόβιτς το νησί παραχωρήθηκε στη Βενετία). Στη Μικρή Βλαχία επιπλέον το Tırgu Jiu περνά στην Αυστρία· η Βονίτσα (Voniçe, TDV pasarofca-antlasmasi) και το Çuha Adası (Κύθηρα, TDV cuka-adasi: 3ο άρθρο του Πασαρόβιτς) περνούν στη Βενετία.", "ec4430bf"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Εκστρατεία του Ιράν του 1723: είσοδος στο Σιρβάν και στη Γεωργία", "c81189fc"], "d": ["Με την κατάρρευση του Κράτους των Σαφαβιδών λόγω της αφγανικής εισβολής, ξεκίνησε εκστρατεία προς την ανατολή με το πρόσχημα να αποτραπεί η κάθοδος της Ρωσίας στις ακτές της Κασπίας. Ο στρατός του Ερζερούμ μπήκε στην Τιφλίδα μέσω της Γεωργίας και ο κλάδος του Σιρβάν στη Σαμαχί, ανακτώντας εδάφη που είχαν χαθεί εκατόν τριάντα χρόνια πριν. Η εκστρατεία αυτή υπήρξε η τελευταία μεγάλη οθωμανική προέλαση στον Καύκασο.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Κατάληψη του Κερμανσάχ — η πύλη του Ζάγρου", "ad14799f"], "d": ["Ο στρατός της Βαγδάτης, διασχίζοντας τα περάσματα του Ζάγρου, κατέλαβε το Κερμανσάχ, που θεωρείται η δυτική πύλη του Ιράν. Η πόλη βρισκόταν στον δρόμο των καραβανιών και των στρατών από τη Βαγδάτη προς την Ισφαχάν και η κατάληψή της εξασφάλιζε την ανατολική ασφάλεια του έγιαλετ του Ιράκ. Η προέλαση αυτή ξεκίνησε στη διαλυμένη χώρα των Σαφαβιδών τον αγώνα διανομής ανάμεσα στους Οθωμανούς και τη Ρωσία.", "65dba49c"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Κατάληψη του Ναχτσιβάν", "bdf14d0a"], "d": ["Οι οθωμανικές δυνάμεις που προέλαυναν κατά μήκος του Αράξη κατέλαβαν το Ναχτσιβάν και το Ορντουμπάντ· και η Τζούλφα υπήχθη στο λιβά του Ναχτσιβάν. Η πόλη υπήχθη, ως βορειοδυτική πύλη του Ιράν, στο νεοϊδρυθέν έγιαλετ του Ρεβάν. Έτσι τα οθωμανικά σύνορα έφτασαν ξανά στην ανατολικότερη γραμμή της εποχής του Σουλεϊμάν του Μεγαλοπρεπούς.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Κατάκτηση του Χαμαδάν (Hemedan)", "e1339a97"], "d": ["Ο στρατός, βαδίζοντας ανατολικά από το Κερμανσάχ, κατέλαβε έπειτα από μακρά πολιορκία το Χαμαδάν στο δυτικό κατώφλι του ιρανικού οροπεδίου. Η πόλη ήταν ο τελευταίος μεγάλος σταθμός στον δρόμο προς την Ισφαχάν, το ανατολικότερο σημείο που μπόρεσαν να φτάσουν οι οθωμανικοί στρατοί από την Εκστρατεία των Δύο Ιράκ. Η Σύμβαση της Κωνσταντινούπολης (İstanbul Mukavelenâmesi) που υπογράφηκε την ίδια χρονιά με τη Ρωσία έβαλε στο χαρτί τη διανομή του διαλυμένου Ιράν ανάμεσα στους Οθωμανούς και τη Ρωσία.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Εκ νέου κατάκτηση του Ρεβάν", "88acabef"], "d": ["Έπειτα από σκληρή πολιορκία ενενήντα ημερών, το κλειδί φρούριο της κοιλάδας του Αράξη, το Ρεβάν, μπήκε ξανά στην οθωμανική διοίκηση. Το φρούριο, που χτίστηκε το 1583 και χάθηκε το 1604, αυτή τη φορά οχυρώθηκε με ισχυρότερη φρουρά. Η διάρκεια της πολιορκίας ήταν ένδειξη ότι ο οθωμανικός στρατός δεν προχωρούσε πλέον εύκολα. Και οι ναχιγιέδες Karpi (Üçkilise), Şerür, Makû και Şüregel υπήχθησαν στο έγιαλετ του Ρεβάν.", "a989b1eb"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Κατάκτηση της Γκιάντζα — τέλος της εκστρατείας του Καυκάσου", "875bca7a"], "d": ["Η Γκιάντζα, ο τελευταίος στόχος της επιχείρησης του Καυκάσου, παραλήφθηκε ως κέντρο του Καραμπάχ ανάμεσα στον Κουρ και τον Αράξη. Με την ολοκλήρωση της γραμμής Σιρβάν, Ρεβάν, Ναχτσιβάν και Γκιάντζα, το Οθωμανικό Κράτος έφτασε στον Καύκασο στην έκταση που είχε το 1590. Ωστόσο το κέρδος αυτό υπήρξε βραχύβιο: η άνοδος του Ναντίρ Σάχη θα ανακτούσε μέσα σε δέκα χρόνια ολόκληρη την περιοχή.", "265db7e0"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Ο Χεκιμόγλου Αλή Πασάς κατέλαβε το Ρουμιγιέ (Urmiye)", "eac7f64d"], "d": ["Στην εκστρατεία του Ιράν ο Χεκιμόγλου Αλή Πασάς κατέλαβε πρώτα την Ουρμιά (Rûmiye) και έπειτα την Ταμπρίζ, που είχε εκκενωθεί για τους Οθωμανούς, στις 15 Νοεμβρίου 1731. Το TDV δεν δίνει την ημέρα κατάληψης της Ουρμιά· είναι γνωστό μόνο το έτος και ότι προηγήθηκε της Ταμπρίζ.", "f99d74f9"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Θάνατος του Αχμέτ Γ'", "455f7fba"], "d": ["Ο Αχμέτ Γ', που καθαιρέθηκε το 1730 με την εξέγερση του Πατρονά Χαλίλ, πέρασε τα τελευταία έξι χρόνια της ζωής του στο διαμέρισμα των καθαιρεθέντων σουλτάνων του Ανακτόρου Τοπ Καπί και πέθανε σε ηλικία εξήντα τριών ετών. Τάφηκε στο Bahçekapı, στο μαυσωλείο της γιαγιάς του Τουρχάν Σουλτάν δίπλα στο Γενί Τζαμί.", "00cc8767"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Κατασκευή του Φρουρίου της Ανάπα — γραμμή άμυνας του Καυκάσου", "be92a80f"], "d": ["Όταν με το Κιουτσούκ Καϊναρτζί χάθηκε η Κριμαία, για να διατηρηθεί η οθωμανική επιρροή στον Καύκασο ξεκίνησε η κατασκευή ενός νέου φρουρίου στις εκβολές του ποταμού Κουμπάν. Η Ανάπα, που χτίστηκε πάνω στα ερείπια μιας γενοβέζικης αποικίας, με την αγορά της, τα λουτρά της και τα πάνω από διακόσια πενήντα μαγαζιά της έγινε σύντομα πόλη που εξασφάλιζε τη σύνδεση με τις φυλές των Τσερκέζων. Το φρούριο παρέμεινε για σαράντα οκτώ χρόνια το πιο προωθημένο φυλάκιο των Οθωμανών απέναντι στην κάθοδο της Ρωσίας στον Καύκασο.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Καθαίρεση και εκτέλεση του Μέγα Βεζίρη Χαλίλ Χαμίτ Πασά", "c44001ca"], "d": ["Ο μεταρρυθμιστής Μέγας Βεζίρης Χαλίλ Χαμίτ Πασάς, του οποίου την ικανοποίηση για τις υπηρεσίες έδειξε ο Αμπντούλ Χαμίτ Α' σε διάφορες περιστάσεις, καθαιρέθηκε ξαφνικά προς το πρωί της 31ης Μαρτίου 1785 και εξορίστηκε στην Καλλίπολη και όλη η περιουσία του δημεύτηκε. Αρχικά του δόθηκαν το έγιαλετ της Αβησσυνίας (Habeş), το σαντζάκι της Τζέντας και το αξίωμα του σεϊχουλχαρέμ της Μέκκας· ενώ τον Απρίλιο του 1785 έκανε προετοιμασίες για το ταξίδι στην Τένεδο, καθαιρέθηκε και από αυτή τη διοίκηση και με το φιρμάνι εκτέλεσης που εκδόθηκε σκοτώθηκε από τον Καρακεχαγιαζαδέ Αλή, άνθρωπο του Αλγερινού Γαζή Χασάν Πασά. Το κομμένο κεφάλι του στάλθηκε στην Κωνσταντινούπολη και εκτέθηκε στην Ορτακαπί. Σύμφωνα με το TDV, η ξαφνική αυτή πτώση ερμηνεύτηκε με την κατηγορία της συνωμοσίας να καθαιρεθεί ο σουλτάνος και να τεθεί στη θέση του ο Σεχζαντέ Σελίμ, ωστόσο οι πραγματικές αιτίες πρέπει να ήταν η αγανάκτηση για τη σιωπή του απέναντι στην προσάρτηση της Κριμαίας, η έχθρα των κύκλων που έβλαψαν οι μεταρρυθμίσεις του και η αντιπολίτευση του Γαζή Χασάν Πασά.", "6f73b0a5"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Εκκένωση του Ορράν (Vehrân, Oran) από τους Ισπανούς και παράδοσή του στο Αλγέρι", "9f95cee6"], "d": ["Όταν το φρούριο και η πόλη καταστράφηκαν σε μεγάλο βαθμό στον σεισμό του 1790, η Ισπανία, που δεν μπορούσε πλέον να σηκώσει την δαπανηρή φρουρά που διατηρούσε επί τρεις αιώνες, συμφώνησε με το οτζάκι του Αλγερίου και παρέδωσε χωρίς πόλεμο το Ορράν και το Μερς ελ-Κεμπίρ (Mersalkebîr). Έτσι εκκαθαρίστηκε και το τελευταίο ευρωπαϊκό οχυρό στην ακτή της Βόρειας Αφρικής. Το Οθωμανικό Αλγέρι παρέμεινε επί τριάντα οκτώ χρόνια, έως τη γαλλική κατοχή, κύριος ολόκληρης της ακτής.", "c73636aa"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Ανάκτηση της Πρέβεζας από τους Γάλλους — Μάχη της Νικόπολης", "d8e5e892"], "d": ["Όταν η Δημοκρατία της Βενετίας καταλύθηκε το 1797, τα νησιά του Ιονίου και η Πρέβεζα, η Πάργα και η Βονίτσα στην ηπειρωτική χώρα έπεσαν στα χέρια της Γαλλίας. Ο βαλής των Ιωαννίνων Αλή Πασάς Τεπεντελενλή, εκμεταλλευόμενος τον πόλεμο που ξέσπασε με την κατάληψη της Αιγύπτου από τη Γαλλία, βάδισε προς την Πρέβεζα και στα ερείπια της Νικόπολης έξω από την πόλη προκάλεσε βαριά ήττα στη γαλλική φρουρά. Έτσι το λιμάνι αυτό, που είχε αφεθεί στη Βενετία στο Πασαρόβιτς, μπήκε μετά από ογδόντα χρόνια στην οθωμανική διοίκηση. Το Μπουτρίντ (Butrint, Butrinto) έπεσε στις 25 Οκτωβρίου, όταν η γαλλική φρουρά ανατίναξε τις οχυρώσεις και αποσύρθηκε στην Κέρκυρα (Curlin, Preveza B, 2010· η ημέρα του άτλαντα λαμβάνεται από την Πρέβεζα) και μπήκε στην οθωμανική διοίκηση.", "f32e8843"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Το Κάρτλι-Κάχετι (Ανατολική Γεωργία) προσαρτήθηκε στη Ρωσία", "3b650c5e"], "d": ["Το βασίλειο του Κάρτλι-Κάχετι, που το 1783 αποδέχθηκε τη ρωσική προστασία και το 1795 υπέστη την καταστροφική εκστρατεία του Ιράν, καταργήθηκε· με διαταγή της 12ης Σεπτεμβρίου 1801 ανακηρύχθηκε επαρχία της Ρωσίας και άρχισε να εγκαθίσταται το ρωσικό διοικητικό σύστημα. Η Γεωργία από αυτή την ημερομηνία έχασε την ανεξαρτησία της· μέσα σε λίγα χρόνια και η Μεγκρελία (1803), η Ιμερετία και η Γουρία (1804) πέρασαν στη ρωσική κυριαρχία και η Ρωσία έφτασε στα οθωμανικά σύνορα του Καυκάσου. Με το γεγονός αυτό το Γκόρι, το Ντουσέτι (Κάρτλι) και το Τελάβι (Κάχετι) πέρασαν στη Ρωσία.", "f5e0d5d5"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Στραγγαλισμός του Μουσταφά Δ'", "eeb75c20"], "d": ["Όταν ο Αλεμντάρ Μουσταφά Πασάς δέχθηκε επίθεση και πέθανε και οι στασιαστές ήθελαν να βαδίσουν προς το ανάκτορο, ο καθαιρεθείς Μουσταφά Δ' στραγγαλίστηκε με διαταγή του αδελφού του Μαχμούτ Β'. Η σορός του τάφηκε στο Bahçekapı, στο μαυσωλείο του πατέρα του Αμπντούλ Χαμίτ Α'· ανάμεσα στους στασιαστές διαδόθηκε η φήμη ότι το φέρετρο ήταν άδειο.", "8a944508"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Κατάργηση του αξιώματος του ντεφτερντάρη και ίδρυση του Υπουργείου Οικονομικών (Maliye Nezâreti)", "89f8125e"], "d": ["Το αξίωμα του ντεφτερντάρη, κεφαλής του κλασικού οθωμανικού οικονομικού συστήματος, καταργήθηκε και ιδρύθηκε το Υπουργείο Οικονομικών (Maliye Nezâreti), υπουργείο ευρωπαϊκού τύπου· τα διάσπαρτα ταμεία συγκεντρώθηκαν σε ένα χέρι. Την ίδια χρονιά και οι άλλες υπηρεσίες της Υψηλής Πύλης αναδιοργανώθηκαν υπό την ονομασία «nezâret» (υπουργείο) και έγινε μετάβαση σε μια σύγχρονη δομή υπουργικού συμβουλίου. Η ρύθμιση αυτή ήταν ένα από τα σημαντικότερα βήματα που προετοίμασαν τη διοικητική υποδομή του Διατάγματος των Τανζιμάτ, το οποίο επρόκειτο να κηρυχθεί ένα χρόνο αργότερα.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Εγκατάσταση των Βρετανών στο Άντεν", "ddbd556b"], "d": ["Η Αγγλία, βασιζόμενη στη συμφωνία εμπορίου και φιλίας που είχε υπογράψει το 1802 με τον σουλτάνο του Λαχίτζ, Αχμέτ μπ. Αμπντούλ Κερίμ, αποβίβασε στρατό στο λιμάνι του Άντεν και έθεσε την πόλη υπό τον έλεγχό της. Το λιμάνι αυτό, που κρατούσε την είσοδο της Ερυθράς Θάλασσας, μετατράπηκε σε σταθμό ανεφοδιασμού με κάρβουνο στον δρόμο προς την Ινδία και σε κομβικό σημείο της βρετανικής αυτοκρατορικής στρατηγικής. Αν και η αξίωση του Οθωμανικού Κράτους επί της Υεμένης συνεχίστηκε στα χαρτιά, η de facto κυριαρχία του στη νότια ακτή δεν επανήλθε ποτέ μετά από αυτή την ημερομηνία.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Επιστροφή στην ακτή της Τιχάμα: κατάληψη της Ουντάιντα, της Ζαμπίντ και της Μόχα", "353982d2"], "d": ["Στην ακτή της Υεμένης, που έμεινε ακυβέρνητη μετά την αποχώρηση του αιγυπτιακού στρατού το 1840, αποβιβάστηκαν δυνάμεις υπό τη διοίκηση του Τεβφίκ Πασά, υπό την εποπτεία του σερίφη της Μέκκας, και υπήγαγαν στην οθωμανική διοίκηση τα λιμάνια της Ουντάιντα, της Ζαμπίντ και της Μόχα. Παρότι επιχειρήθηκε προέλαση έως τη Σανάα, λόγω της αντίστασης του λαού επέστρεψαν στην Ουντάιντα· έτσι τα υψίπεδα παρέμειναν στους ιμάμηδες των Ζαϊντιτών και η οθωμανική κυριαρχία επί είκοσι τρία χρόνια διατηρήθηκε μόνο στη λωρίδα της Τιχάμα. Η εσωτερική Υεμένη επρόκειτο να ανακτηθεί μόλις το 1872, με την εκστρατεία του Αχμέτ Μουχτάρ Πασά.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Σύμβαση του Μπαλταλιμανί: κοινό οθωμανορωσικό προτεκτοράτο στη Βλαχία και τη Μολδαβία", "d3bb22e9"], "d": ["Όταν οι επαναστάσεις του 1848 εξαπλώθηκαν στη Βλαχία και τη Μολδαβία, οθωμανικές και ρωσικές δυνάμεις είχαν καταλάβει από κοινού τις ηγεμονίες. Με τη σύμβαση που υπογράφηκε στο Μπαλταλιμανί αποφασίστηκε οι βοεβόδες να μη εκλέγονται αλλά να διορίζονται από τον σουλτάνο για επτά έτη και τα δύο κράτη να ασκούν κοινό έλεγχο στην περιοχή. Η συμφωνία, ενώ διατήρησε στα χαρτιά την οθωμανική επικυριαρχία, παραχώρησε στη Ρωσία de facto δικαίωμα συνεταιρισμού και επιτάχυνε την απόσπαση των παραδουνάβιων ηγεμονιών από την Οθωμανική Αυτοκρατορία.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Το ζήτημα των Ούγγρων προσφύγων: η καταφυγή του Κόσουθ και των συντρόφων του στην Οθωμανική Αυτοκρατορία", "1c7d7ef4"], "d": ["Όταν η ουγγρική επανάσταση του 1848-1849 καταπνίγηκε με τη ρωσοαυστριακή επέμβαση, ο Λάγιος Κόσουθ και χιλιάδες Ούγγροι και Πολωνοί πρόσφυγες κατέφυγαν σε οθωμανικά εδάφη. Η Αυστρία και η Ρωσία ζήτησαν με σφοδρότητα την έκδοση των προσφύγων· η Υψηλή Πύλη, με την υποστήριξη της Αγγλίας και της Γαλλίας, αρνήθηκε την έκδοση και εγκατέστησε την ομάδα στην Κιουτάχεια. Ο περίγυρος του Κόσουθ έμεινε εκεί περίπου δεκαοκτώ μήνες· εκατοντάδες πρόσφυγες ασπάστηκαν το Ισλάμ και μπήκαν στην οθωμανική υπηρεσία. Το γεγονός θεωρήθηκε μία από τις σπάνιες διπλωματικές νίκες που ανύψωσαν το κύρος της οθωμανικής αυτοκρατορίας των Τανζιμάτ στην ευρωπαϊκή κοινή γνώμη.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Ίδρυση του Encümen-i Dâniş: η πρώτη οθωμανική ακαδημία στην Κωνσταντινούπολη", "6fda1365"], "d": ["Το Encümen-i Dâniş, που ιδρύθηκε με απόφαση του Meclis-i Maârif-i Umûmiyye (Συμβουλίου Δημόσιας Παιδείας), είναι η πρώτη οθωμανική επιστημονική ακαδημία που συγκροτήθηκε με σκοπό την εκπόνηση επιστημονικών και διδακτικών βιβλίων στα τουρκικά. Εγκαινιάστηκε με τελετή στις 18 Ιουλίου 1851 στο κτίριο του Dârülmaârif· ανάμεσα στα ντόπια και ξένα μέλη του ήταν και ο Αχμέτ Τζεβντέτ Πασάς. Αν και βραχύβιο, έργα όπως το Târih του Τζεβντέτ Πασά και το Kavâid-i Osmâniyye υπήρξαν προϊόντα αυτού του ιδρύματος και θεωρήθηκε ακρογωνιαίος λίθος στη μετατροπή της τουρκικής σε γλώσσα της επιστήμης.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Νίκη στην Ολτενίτσα: η πρώτη οθωμανική επιτυχία στο μέτωπο του Δούναβη", "a660ad2f"], "d": ["Στην αρχική φάση του Κριμαϊκού Πολέμου, ο αρχιστράτηγος (serdâr-ı ekrem) Ομέρ Λουτφή Πασάς πέρασε τον Δούναβη και απώθησε τις ρωσικές δυνάμεις στην Ολτενίτσα με βαριές απώλειες. Η νίκη, σταματώντας τη ρωσική προέλαση ευθύς εξαρχής του πολέμου, έδειξε στην Ευρώπη τη δύναμη που είχε αποκτήσει ο οθωμανικός στρατός με την εκπαίδευση μετά τα Τανζιμάτ. Η επιτυχία αυτή προετοίμασε το ψυχολογικό έδαφος που διευκόλυνε την απόφαση της Αγγλίας και της Γαλλίας να εισέλθουν στον πόλεμο στο πλευρό των Οθωμανών.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Συνθήκη συμμαχίας με την Αγγλία και τη Γαλλία στην Κωνσταντινούπολη", "04809278"], "d": ["Η συνθήκη συμμαχίας που υπογράφηκε στον Κριμαϊκό Πόλεμο ανάμεσα στο Οθωμανικό Κράτος, την Αγγλία και τη Γαλλία εναντίον της Ρωσίας όριζε κοινές πολεμικές επιχειρήσεις των τριών κρατών και την απαγόρευση χωριστής ειρήνης των συμμάχων πριν το τέλος του πολέμου. Έτσι το Οθωμανικό Κράτος μπήκε για πρώτη φορά στην ιστορία του σε στρατιωτική συμμαχία με τις μεγάλες ευρωπαϊκές δυνάμεις ως ισότιμο μέρος. Η συνθήκη αυτή συνιστούσε και το νομικό έδαφος για την επίσημη αποδοχή της Οθωμανικής Αυτοκρατορίας στο ευρωπαϊκό σύστημα κρατών, δύο χρόνια αργότερα στο Παρίσι.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Ίδρυση της Şehremaneti της Κωνσταντινούπολης: η πρώτη σύγχρονη δημοτική οργάνωση", "be4af27f"], "d": ["Η κρίση υποδομών που προκάλεσαν οι συσσωρευμένοι σύμμαχοι στρατιώτες και ο αυξανόμενος πληθυσμός στην Κωνσταντινούπολη κατά τον Κριμαϊκό Πόλεμο αποκάλυψε την ανεπάρκεια της κλασικής διοίκησης της πόλης με επίκεντρο τον καδή. Με τη Şehremaneti (δήμαρχο-διοίκηση), που ιδρύθηκε κατά ευρωπαϊκά πρότυπα, η καθαριότητα, ο καθορισμός τιμών (narh), ο έλεγχος της αγοράς και τα έργα ανοικοδόμησης συγκεντρώθηκαν σε ένα χέρι· το επόμενο έτος στο Πέρα-Γαλατά οργανώθηκε ως πιλοτική περιοχή η Έκτη Δημοτική Περιφέρεια (Altıncı Daire-i Belediye). Το βήμα αυτό θεωρείται η αρχή της σύγχρονης δημοτικής διοίκησης στην Οθωμανική Αυτοκρατορία.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Συνθήκη των Παρισίων: το τέλος του Κριμαϊκού Πολέμου και η αποδοχή της Οθωμανικής Αυτοκρατορίας στο ευρωπαϊκό σύστημα κρατών", "4aee0e2a"], "d": ["Με τη Συνθήκη των Παρισίων, που έληξε τον Κριμαϊκό Πόλεμο, το Οθωμανικό Κράτος ανακηρύχθηκε ισότιμο μέλος του ευρωπαϊκού δημοσίου δικαίου και η εδαφική του ακεραιότητα τέθηκε υπό την κοινή εγγύηση των μεγάλων δυνάμεων. Η Μαύρη Θάλασσα ουδετεροποιήθηκε, η αξίωση της Ρωσίας για προστασία των ορθοδόξων υπηκόων, που είχε αποκτήσει από το Κιουτσούκ Καϊναρτζί, κηρύχθηκε άκυρη, και το νότιο τμήμα της Βεσσαραβίας (οι καζάδες Κιλίας, Κάχουλ, Ισμαήλ και Μπόλγκραντ) δόθηκε στη Μολδαβία. Ωστόσο η ίδια συνθήκη, καθιστώντας το Διάταγμα Μεταρρυθμίσεων (Islahat Fermanı) διεθνή δέσμευση, άνοιξε και την πόρτα στην επέμβαση στις εσωτερικές υποθέσεις.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Εγκαίνια του Ανακτόρου Ντολμάμπαχτσε: μεταφορά του κέντρου διοίκησης από το Τοπ Καπί", "71ad26d0"], "d": ["Το ανάκτορο που ο Αμπντούλ Μετζίτ είχε παραγγείλει το 1842 στην οικογένεια Μπαλιάν εγκαινιάστηκε έπειτα από δεκατέσσερα χρόνια κατασκευής, και το κέντρο διοίκησης του κράτους μεταφέρθηκε από το τετρακόσιων ετών Τοπ Καπί στην όχθη του Βοσπόρου. Με το ευρωπαϊκό του ύφος, τη κρυστάλλινη σκάλα και την Αίθουσα Muayede, το ανάκτορο έγινε η εκ λίθου έκφραση της αξίωσης των Τανζιμάτ για εκδυτικισμό. Το τεράστιο κόστος του έγινε ένα από τα πιο επικριθέντα στοιχεία των ετών κατά τα οποία τα οθωμανικά οικονομικά εισήλθαν στη δίνη του εξωτερικού δανεισμού.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Ένωση της Βλαχίας και της Μολδαβίας υπό τον Κούζα: η γέννηση της Ρουμανίας", "baef4da5"], "d": ["Στις εκλογές που διεξήχθησαν μετά τη Συνθήκη των Παρισίων, και οι δύο ηγεμονίες εξέλεξαν βοεβόδα τον συνταγματάρχη Alexandru Ioan Cuza, πραγματοποιώντας de facto ένωση. Παρότι η Υψηλή Πύλη και η Αυστρία αντιτάχθηκαν, το τετελεσμένο που υποστήριζε η Γαλλία αναγκάστηκαν να το αποδεχθούν. Η ένωση αυτή, που παρέμεινε στα χαρτιά εξαρτημένη από τους Οθωμανούς, θα έπαιρνε το όνομα Ρουμανία το 1862 και θα κήρυσσε μονομερώς την ανεξαρτησία της το 1877· αποτελεί σημείο καμπής στη διάλυση της οθωμανικής κυριαρχίας κατά μήκος του Δούναβη.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Επεισόδιο Κουλελί: η πρώτη απόπειρα πραξικοπήματος κατά του Αμπντούλ Μετζίτ στην Κωνσταντινούπολη", "e3653b21"], "d": ["Μια μυστική εταιρεία μικτής στρατιωτικής-πολιτικής σύνθεσης, που αντιδρούσε στην πολιτική των Τανζιμάτ και στην ισότητα που παρείχε το Διάταγμα Μεταρρυθμίσεων στους μη μουσουλμάνους, ενώ σχεδίαζε να καθαιρέσει τον σουλτάνο, εξαρθρώθηκε κατά τη συνάντησή της στο Τέμενος Κιλίτς Αλί Πασά. Επειδή οι κατηγορούμενοι δικάστηκαν στους Στρατώνες Κουλελί, το γεγονός έμεινε γνωστό με αυτό το όνομα· οι θανατικές ποινές μετατράπηκαν σε εξορία. Θεωρείται η πρώτη απόπειρα ανακτορικού πραξικοπήματος στην οθωμανική ιστορία από οργάνωση που ιδρύθηκε για ιδεολογικούς λόγους.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Εμφύλιος πόλεμος Δρούζων-Μαρωνιτών στο Όρος Λίβανος και τα γεγονότα της Δαμασκού", "5595fdd6"], "d": ["Οι συγκρούσεις που ξέσπασαν τον Μάιο του 1860 με τη δολοφονία δύο Δρούζων κοντά στη Σιδώνα εξελίχθηκαν στον πιο αιματηρό εμφύλιο πόλεμο Δρούζων-Μαρωνιτών του όρους και τον Ιούλιο εξαπλώθηκαν στη Δαμασκό, με αποτέλεσμα το θάνατο χιλιάδων χριστιανών. Μετά την απόβαση της Γαλλίας, η Υψηλή Πύλη έστειλε στην περιοχή τον Φουάτ Πασά με έκτακτες εξουσίες· διεξήχθη σκληρή εκστρατεία καταστολής. Τα γεγονότα αποτέλεσαν αιτιολογία για ευρωπαϊκή επέμβαση και υπήρξαν η άμεση αιτία για την απόκτηση ειδικού καθεστώτος από τον Λίβανο.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Έναρξη της έκδοσης της Tercümân-ı Ahvâl: η πρώτη ιδιωτική τουρκική εφημερίδα στην Κωνσταντινούπολη", "24792957"], "d": ["Η Tercümân-ı Ahvâl, που εξέδιδε ο Αγκάχ Εφέντη και της οποίας τη σύνταξη ανέλαβε ο Σινασί, είναι η πρώτη τουρκική εφημερίδα που εκδόθηκε χωρίς κρατική υποστήριξη. Στον πρόλογο του πρώτου φύλλου υπερασπίστηκε το δικαίωμα του λαού να έχει λόγο για τις υποθέσεις του· η εφημερίδα, δημοσιεύοντας σε συνέχειες το Şair Evlenmesi του Σινασί, άνοιξε και την πόρτα στη σύγχρονη τουρκική λογοτεχνία. Η γέννηση της έννοιας της κοινής γνώμης και του αντιπολιτευτικού Τύπου στην Οθωμανική Αυτοκρατορία χρονολογείται από αυτή την ημερομηνία.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Κανονισμός του Όρους Λίβανος: καθεστώς προνομιούχου μουτασαρριφλικίου για τον Λίβανο", "bf375603"], "d": ["Ο κανονισμός που ετοιμάστηκε μετά τις σφαγές του 1860 υπό την πίεση των μεγάλων δυνάμεων έκανε το Όρος Λίβανος προνομιούχο μουτασαρριφλίκι, εξαρτώμενο απευθείας από την Υψηλή Πύλη και διοικούμενο από διοικητικό συμβούλιο συγκροτημένο με βάση την ισορροπία ανάμεσα στα δόγματα. Ορίστηκε ως όρος ο μουτασαρρίφης να είναι Καθολικός χριστιανός οθωμανός υπήκοος και ο διορισμός του να υποβάλλεται στην έγκριση των μεγάλων δυνάμεων· πρώτος μουτασαρρίφης έγινε ο Νταούντ Πασάς. Το καθεστώς αυτό θα διαρκούσε έως το 1915 και θα αποτελούσε τον πυρήνα του σύγχρονου κράτους του Λιβάνου.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Θάνατος του Αμπντούλ Μετζίτ και ανάρρηση του σουλτάνου Αμπντούλ Αζίζ", "27204d7c"], "d": ["Όταν ο Αμπντούλ Μετζίτ, που κατά την εικοσιδυάχρονη βασιλεία του υπέγραψε τα διατάγματα των Τανζιμάτ και των Μεταρρυθμίσεων, υπέκυψε στη φυματίωση, ο αδελφός του Αμπντούλ Αζίζ ανέβηκε στον θρόνο. Ο νέος σουλτάνος τα πρώτα χρόνια έδωσε ελπίδες με μέτρα λιτότητας και απλή ζωή· έκανε τον στόλο μία από τις λίγες μεγάλες δυνάμεις του κόσμου. Ωστόσο στο τέλος της βασιλείας του το βαρύ εξωτερικό χρέος, η πτώχευση του 1875 και οι βαλκανικές εξεγέρσεις συσσωρεύτηκαν και προετοίμασαν το έδαφος για το κίνημα καθαίρεσης (hal') του 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Οι Ενωμένες Ηγεμονίες παίρνουν το όνομα Ρουμανία", "d960e3fc"], "d": ["Η Βλαχία και η Μολδαβία, που είχαν ενωθεί de facto το 1859 με τη διπλή εκλογή του Κούζα, το 1862, συγκεντρώνοντας τα κοινοβούλιά τους και τις κυβερνήσεις τους στο Βουκουρέστι κάτω από μία στέγη, πήραν επίσημα το όνομα Ρουμανία. Αν και το Οθωμανικό Κράτος νομικά διατήρησε την ιδιότητα του επικυρίαρχου και τον ετήσιο φόρο, de facto έχασε τον έλεγχο επί της ηγεμονίας. Το τέλος της τετρακόσιων ετών οθωμανικής επιρροής βόρεια του Δούναβη συμβολίζεται με αυτή την ημερομηνία.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Υπαγωγή του Σουάκιν, της Μασαουά και του Ντάχλακ στην Αίγυπτο", "a0924860"], "d": ["Η Μασαουά, που το 1846 είχε δοθεί από τον σουλτάνο Αμπντούλ Μετζίτ στον Χεδίβη της Αιγύπτου Μεχμέτ Αλή Πασά μαζί με το Σουάκιν ως sâlyâne (παραχώρηση εσόδων), στην εποχή του Χεδίβη Ισμαήλ Πασά συμπεριλήφθηκε μαζί με το Ντάχλακ και το Σουάκιν στα κτήματα της Αιγύπτου και οργανώθηκε με καθεστώς καϊμακαμλικίου. Έτσι τα τρία αυτά λιμάνια στην αφρικανική ακτή της Ερυθράς Θάλασσας, παραμένοντας νομικά οθωμανικό έδαφος, πέρασαν διοικητικά απευθείας από την Υψηλή Πύλη στο Κάιρο — εντάχθηκαν στο ίδιο εξαρτημένο στρώμα με τη γειτονική Αίγυπτο και το Σουδάν.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Έναρξη της Κρητικής Εξέγερσης (1866-1869)", "3679b861"], "d": ["Η εξέγερση ευρείας κλίμακας που ξέσπασε στο νησί με την ανοιχτή υποστήριξη της Ελλάδας μετέτρεψε για πρώτη φορά σε διεθνές ζήτημα το αίτημα των Κρητών Ρωμιών για ένωση (enosis) με την Ελλάδα. Ο σκληρός ορεινός πόλεμος που διήρκεσε τρία χρόνια προκάλεσε βαριές απώλειες στον οθωμανικό στρατό και είχε μεγάλη απήχηση στην ευρωπαϊκή κοινή γνώμη. Η εξέγερση κατέρρευσε μόλις το 1868, όταν ο Αλή Πασάς πήγε στο νησί και έθεσε σε ισχύ τον κανονισμό που παρείχε ευρέα προνόμια.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Αποχώρηση των τελευταίων οθωμανικών φρουρών από το Βελιγράδι και τα φρούρια της Σερβίας", "b34217db"], "d": ["Υπό την πίεση των μεγάλων δυνάμεων και το επίμονο αίτημα του ηγεμόνα Μιχαήλ, η Υψηλή Πύλη δέχθηκε να εκκενώσει τις τελευταίες στρατιωτικές βάσεις που της απέμεναν στη Σερβία· στις 18 Απριλίου 1867 κατέβηκε η οθωμανική σημαία στο Φρούριο του Βελιγραδίου και τα κλειδιά παραδόθηκαν στον ηγεμόνα. Έτσι έληξε η de facto οθωμανική στρατιωτική παρουσία που διαρκούσε από το 1521 και αφαιρέθηκε το τελευταίο μεγάλο εμπόδιο στον δρόμο της Σερβίας προς την ανεξαρτησία. Η επικυριαρχία του σουλτάνου περιορίστηκε σε ζήτημα μιας συμβολικής σημαίας και ενός φόρου.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Απονομή του τίτλου του χεδίβη στους ηγεμόνες της Αιγύπτου", "09e10c12"], "d": ["Ύστερα από την έντονη προσπάθεια λόμπι του Ισμαήλ Πασά, της τρίτης γενιάς της δυναστείας του Καβαλιώτη, και τα χρήματα που διοχέτευσε στην Κωνσταντινούπολη, ο τίτλος του χεδίβη, που τόνιζε την υπεροχή του έναντι των άλλων βαλήδων, δόθηκε στον βαλή της Αιγύπτου. Τα ίδια χρόνια άλλαξε και το σύστημα διαδοχής ώστε να περνά από πατέρα σε γιο, και στην Αίγυπτο παραχωρήθηκαν εξουσίες χαρακτήρα κυριαρχίας, όπως ο εξωτερικός δανεισμός, η απονομή παρασήμων και η διατήρηση προξενείων. Τα βήματα αυτά είναι ο πρώτος κρίκος της αλυσίδας που επιτάχυνε την νομική απόσπαση της Αιγύπτου από την Οθωμανική Αυτοκρατορία.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Κανονισμός της Κρήτης: ευρέα διοικητικά προνόμια στο νησί", "12052262"], "d": ["Για να τερματιστεί η τριετής εξέγερση, ο Μέγας Βεζίρης Αλή Πασάς πήγε ο ίδιος στο νησί και με τον κανονισμό που δημοσιεύθηκε με την έγκριση του σουλτάνου παραχωρήθηκαν στους Κρήτες μικτά διοικητικά συμβούλια, τοπικά δικαστήρια, η χρήση της ελληνικής στις επίσημες συναλλαγές και φορολογικές διευκολύνσεις. Η ρύθμιση αυτή κράτησε όρθια την οθωμανική κυριαρχία στο νησί για άλλα τριάντα χρόνια. Ωστόσο τα προνόμια που δόθηκαν στον χριστιανικό πληθυσμό αποδυνάμωσαν τη θέση των μουσουλμάνων Κρητών και έσπειραν τους σπόρους της κρίσης του 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Εγκαίνια του Şûrâ-yı Devlet: ίδρυση του Οθωμανικού Συμβουλίου της Επικρατείας", "70b16497"], "d": ["Με το διάταγμα (irade) της 5ης Μαρτίου 1868, το Meclis-i Ahkâm-ı Adliyye χωρίστηκε στα δύο: οι διοικητικο-νομοθετικές υποθέσεις ανατέθηκαν στο Şûrâ-yı Devlet και οι δικαστικές στο Dîvân-ı Ahkâm-ı Adliyye· το ίδρυμα εγκαινιάστηκε με τελετή στην Υψηλή Πύλη και πρώτος πρόεδρός του διορίστηκε ο Μιντχάτ Πασάς. Του ανατέθηκε η προετοιμασία νομοσχεδίων, η επίλυση διοικητικών διαφορών και η διεξαγωγή των δικών των υπαλλήλων. Με τη μικτή σύνθεση μελών μουσουλμάνων και μη μουσουλμάνων θεωρείται η πρώτη θεσμική εφαρμογή της ιδέας της διάκρισης των εξουσιών στην Οθωμανική Αυτοκρατορία.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Εγκαίνια της Διώρυγας του Σουέζ: συντόμευση της οδού προς την Ινδία μέσω Αιγύπτου", "377ccd04"], "d": ["Η κατασκευή που ξεκίνησε το 1859 διήρκεσε δέκα χρόνια και η διώρυγα μήκους 163 χιλιομέτρων, που συνδέει τη Μεσόγειο με την Ερυθρά Θάλασσα, τέθηκε σε λειτουργία με μεγαλοπρεπή τελετή. Όταν ο δρόμος που συνδέει την Ευρώπη με την Ινδία συντομεύτηκε κατά χιλιάδες μίλια, η Αίγυπτος έγινε ξαφνικά κομβικό σημείο του παγκόσμιου εμπορίου. Αυτή η γεωστρατηγική αξία θα ήταν η κύρια αιτία της κατάληψης της Αιγύπτου από την Αγγλία δεκατρία χρόνια μετά τα εγκαίνια της διώρυγας· το χρέος που φόρτωσε η διώρυγα στην Αίγυπτο θα οδηγούσε το χεδιβάτο στην πτώχευση.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Ίδρυση της Βουλγαρικής Εξαρχίας: αποχωρισμός της βουλγαρικής εκκλησίας από το Φανάρι", "33a8272c"], "d": ["Με σουλτανικό διάταγμα ιδρύθηκε μια αυτόνομη βουλγαρική εκκλησία (εξαρχία), χωριστή από το Ρωμαίικο Πατριαρχείο, και το ποιοι καζάδες θα εντάσσονταν στην εξαρχία αφέθηκε σε λαϊκό δημοψήφισμα. Αν και η Υψηλή Πύλη έκανε αυτό το βήμα για να σπάσει την ελληνική επιρροή, το αποτέλεσμα ήταν το αντίθετο: η εκκλησία μετατράπηκε στο οργανωμένο κέντρο της βουλγαρικής εθνικής ταυτότητας και της βουλγαρικής αξίωσης επί της Μακεδονίας. Έτσι τέθηκε το θεσμικό έδαφος του βουλγαρο-ελληνο-σερβικού ανταγωνισμού στα Βαλκάνια και των εξεγέρσεων του 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Υπαγωγή του Ασίρ (Asîr) στην άμεση διοίκηση", "4559e099"], "d": ["Όταν η στρατηγική αξία της Ερυθράς Θάλασσας αυξήθηκε με το άνοιγμα της Διώρυγας του Σουέζ, έγινε σαφές ότι τα βουνά του Ασίρ στο μέσον του χερσαίου δρόμου προς την Υεμένη δεν μπορούσαν να μείνουν χωρίς έλεγχο. Οι δυνάμεις του Ρεντίφ Πασά, που βγήκε στην εκστρατεία της Υεμένης, μπήκαν στην Αμπχά (Ebha), υπήγαγαν την περιοχή απευθείας στην οθωμανική διοίκηση και ιδρύθηκε το σαντζάκι του Ασίρ. Λόγω της ορεινής γεωγραφίας και της επιρροής των Ιντρισιτών, η κυριαρχία αυτή δεν εδραιώθηκε ποτέ πλήρως.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Εκστρατεία του Μιντχάτ Πασά στη Νεγκντ: αποκατάσταση της οθωμανικής κυριαρχίας στη Λαχσά", "7db51461"], "d": ["Ο βαλής της Βαγδάτης Μιντχάτ Πασάς, εκμεταλλευόμενος τη διαμάχη για τον θρόνο εντός της οικογένειας των Σαουδιτών, έστειλε στρατό στη δυτική ακτή του Περσικού Κόλπου και υπήγαγε την περιοχή Λαχσά στο βιλαέτι της Βασόρας με το όνομα σαντζάκι της Νεγκντ. Διορίστηκε μουτασαρρίφης ο Αμπντουλλάχ μπ. Φαϊσάλ και η οθωμανική κυριαρχία εγκαθιδρύθηκε στα χαρτιά. Η εκστρατεία είχε ως στόχο να σταματήσει την εξάπλωση της βρετανικής επιρροής στον Κόλπο και την ίδια χρονιά οδήγησε και στην υπαγωγή του Κατάρ υπό οθωμανικό έλεγχο.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Θάνατος του Μέγα Βεζίρη Αλή Πασά: το τέλος του επιτελείου των Τανζιμάτ", "1cf0141c"], "d": ["Με τον θάνατο του Αλή Πασά, ο οποίος μετά τον θάνατο του Φουάτ Πασά το 1869 σήκωνε μόνος του την πολιτική των Τανζιμάτ, εξαντλήθηκε η γενιά των ικανών διπλωματών που διοικούσαν την εξωτερική πολιτική του κράτους επί τριάντα χρόνια. Η φιλορωσική και αυθαίρετη διοίκηση του Μαχμούτ Νεντίμ Πασά, που ήρθε στη θέση του, ενίσχυσε την προσωπική διακυβέρνηση του Αμπντούλ Αζίζ. Μέσα σε πέντε χρόνια μετά τον θάνατο του Αλή Πασά τα οικονομικά πτώχευσαν, τα Βαλκάνια εξεγέρθηκαν και η αλλαγή βασιλείας κατέστη αναπόφευκτη.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Εγκαθίδρυση οθωμανικού ελέγχου στο Κατάρ", "3b453165"], "d": ["Έπειτα από πρόσκληση του σεΐχη Κασίμ μπ. Θάνι, ο οποίος βρισκόταν υπό βρετανική πίεση, οθωμανικές δυνάμεις αποβιβάστηκαν στη χερσόνησο του Κατάρ και το φθινόπωρο του 1871 εξασφαλίστηκε οθωμανικός έλεγχος στην περιοχή. Το Κατάρ οργανώθηκε ως καζάς εξαρτώμενος από το σαντζάκι της Νεγκντ και ο σεΐχης διορίστηκε καϊμακάμης. Η κίνηση αυτή υπήρξε το πιο απτό κέρδος της πολιτικής προώθησης που ακολουθούσε ο Μιντχάτ Πασάς στον Κόλπο εναντίον της Αγγλίας· η οθωμανική σημαία κυμάτισε στη χερσόνησο έως το 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Φιρμάνι διαδοχής για την Τυνησία — το μπεηλίκι στην οικογένεια του Μεχμέτ Σαντίκ Πασά", "1509ebb0"], "d": ["Με το φιρμάνι που εκδόθηκε με τις προσπάθειες του Χαϊρεντίν Πασά, τον οποίο έστειλε στην Κωνσταντινούπολη ο μπέης της Τυνησίας Μεχμέτ Σαντίκ Πασάς, εκμεταλλευόμενος την ήττα της Γαλλίας από την Πρωσία, η Τυνησία δόθηκε με κληρονομική διαδοχή στον Μεχμέτ Σαντίκ Πασά και στα παιδιά του, παραμένοντας απευθείας εξαρτημένη από την Κωνσταντινούπολη. Δεν θα γίνονταν διαπραγματεύσεις πολέμου και ειρήνης χωρίς την άδεια του σουλτάνου, κανένα έδαφος της χώρας δεν θα δινόταν σε άλλον και θα ικανοποιούνταν το αίτημα των Οθωμανών για στρατό. Η Γαλλία δεν αναγνώρισε το φιρμάνι· δέκα χρόνια αργότερα κατέλαβε την Τυνησία.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Κατάληψη της Σανάα: αποκατάσταση της οθωμανικής εξουσίας στην Υεμένη", "978e20a0"], "d": ["Όταν η στρατηγική αξία της Ερυθράς Θάλασσας αυξήθηκε με το άνοιγμα της Διώρυγας του Σουέζ, η Υψηλή Πύλη έστειλε στην Υεμένη στρατό fırka-i ihtiyâtiyye υπό τη διοίκηση του Αχμέτ Μουχτάρ Πασά. Με την κατάληψη της Σανάα αποκαταστάθηκε η κρατική εξουσία στην εσωτερική Υεμένη, που είχε χαθεί de facto για δύο αιώνες, και η περιοχή έγινε βιλαέτι. Ωστόσο ο αγώνας με τους ιμάμηδες των Ζαϊντιτών δεν τελείωσε ποτέ· οι εξεγέρσεις του 1891, του 1898 και του 1904 αποτέλεσαν το πιο δαπανηρό και μακροχρόνιο εσωτερικό μέτωπο των Οθωμανών. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Έναρξη της Εξέγερσης της Ερζεγοβίνης: νέα ανάφλεξη του Ανατολικού Ζητήματος", "571b18ec"], "d": ["Η εξέγερση των χριστιανών χωρικών γύρω από το Νέβεσινιε εξαιτίας των βαριών φόρων και της πίεσης των αγιάν εξαπλώθηκε σύντομα σε ολόκληρη την Ερζεγοβίνη και τροφοδοτήθηκε από εθελοντές που έφταναν από τη Σερβία και το Μαυροβούνιο. Η εξέγερση, που οδήγησε στην επιβολή μεταρρυθμίσεων από την Αυστρία και τη Ρωσία, προκάλεσε την επόμενη χρονιά τις βουλγαρικές εξεγέρσεις και τις κηρύξεις πολέμου της Σερβίας και του Μαυροβουνίου. Έτσι έσπασε ο πρώτος κρίκος της μεγάλης αλυσίδας που οδήγησε στον Πόλεμο του '93 και στην απώλεια των Βαλκανίων με τη Συνθήκη του Βερολίνου.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Πτώχευση των οθωμανικών οικονομικών: μείωση των πληρωμών του εξωτερικού χρέους στο μισό", "2cac2fa5"], "d": ["Τα συνεχόμενα δάνεια που ελήφθησαν από το 1854, τα έξοδα του Κριμαϊκού Πολέμου, οι ανακτορικές κατασκευές και ο λιμός της Ανατολίας το 1873-74 μετέτρεψαν το έλλειμμα του προϋπολογισμού σε άβυσσο που ξεπερνούσε τα πέντε εκατομμύρια λίρες. Η κυβέρνηση του Μαχμούτ Νεντίμ Πασά, ανακοινώνοντας ότι οι πληρωμές τόκων και κεφαλαίου του χρέους θα μειωθούν στο μισό για πέντε έτη, κήρυξε de facto μορατόριουμ. Η απόφαση αυτή, που προκάλεσε μεγάλη αντίδραση στα ευρωπαϊκά χρηματιστήρια, ξεκίνησε τη διαδικασία που έξι χρόνια αργότερα θα κατέληγε στο Διάταγμα του Μουχαρρέμ και στην ίδρυση της Διοίκησης του Δημοσίου Χρέους (Düyûn-ı Umûmiyye İdaresi).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Καθαίρεση του Μουράτ Ε' και ανάρρηση του Αμπντούλ Χαμίτ Β'", "cffb2271"], "d": ["Ο Μουράτ Ε', που ανέβηκε στον θρόνο μετά την καθαίρεση του Αμπντούλ Αζίζ, λόγω του θανάτου του θείου του και της ψυχικής του υγείας, που κλονίστηκε από το Επεισόδιο του Τσερκές Χασάν, αδυνατούσε να ασκήσει τα καθήκοντά του· μόλις επτά μέρες της τρίτης και ενενήντα ημερών βασιλείας του η κρίση του ήταν διαυγής. Καθαιρέθηκε με φετβά του Σεϊχουλισλάμ και στη θέση του ήρθε ο αδελφός του Αμπντούλ Χαμίτ Β'. Ο νέος σουλτάνος ανέβηκε στον θρόνο δίνοντας υπόσχεση στον Μιντχάτ Πασά ότι θα κηρύξει τη συνταγματική μοναρχία (meşrutiyet)· ξεκινούσε μια εποχή που θα διαρκούσε τριάντα τρία χρόνια.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Διάσκεψη του Ναυστάθμου (Tersane): επιβολή βαλκανικών μεταρρυθμίσεων από τις μεγάλες δυνάμεις", "b5006a2c"], "d": ["Η διάσκεψη που συγκάλεσαν οι μεγάλες δυνάμεις στην Κωνσταντινούπολη για την επίλυση της βαλκανικής κρίσης ζήτησε τη διαίρεση της Βουλγαρίας σε δύο αυτόνομα βιλαέτια και την εφαρμογή μεταρρυθμίσεων υπό διεθνή έλεγχο στη Βοσνία-Ερζεγοβίνη. Η Υψηλή Πύλη, την ημέρα έναρξης της διάσκεψης, ανακοίνωσε με κανονιοβολισμούς τη διακήρυξη του Kanûn-ı Esâsî (Συντάγματος), επιχειρώντας να αντιμετωπίσει τις επιβολές με συνταγματική μεταρρύθμιση. Οι αντιπρόσωποι το θεώρησαν καθυστέρηση και διαλύθηκαν στις 20 Ιανουαρίου 1877· τέσσερις μήνες αργότερα η Ρωσία κήρυξε πόλεμο.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Εγκαίνια της πρώτης Meclis-i Meb'ûsan (Βουλής των Αντιπροσώπων) στο Ντολμάμπαχτσε", "429bb279"], "d": ["Οι 115 βουλευτές που εκλέχθηκαν σύμφωνα με το Kanûn-ı Esâsî συνήλθαν για πρώτη φορά στις 19 Μαρτίου 1877 σε τελετή στην Αίθουσα Muayede του Ανακτόρου Ντολμάμπαχτσε· έτσι ξεκίνησε στην οθωμανική ιστορία η περίοδος του αντιπροσωπευτικού κοινοβουλίου. Οι μουσουλμάνοι και μη μουσουλμάνοι βουλευτές εξέτασαν σκληρά την κυβέρνηση, συζήτησαν τη διεξαγωγή του πολέμου και την ευθύνη των υπουργών. Αυτή η τολμηρή αντιπολίτευση θα ήταν η κύρια αιτία που συντόμευσε τη ζωή της βουλής.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Έναρξη της άμυνας της Πλέβνας: η αντίσταση του Γαζή Οσμάν Πασά", "0e04a878"], "d": ["Ο Οσμάν Πασάς, που στον Πόλεμο του '93 βάδισε από το Βιδίνι προς την Πλέβνα για να αποκόψει τον δρόμο προς την Κωνσταντινούπολη του ρωσικού στρατού που είχε περάσει τον Δούναβη, οχύρωσε την κωμόπολη με προμαχώνες και χαρακώματα και ξεκίνησε μια θρυλική πεντάμηνη άμυνα. Τρεις διαδοχικές μεγάλες ρωσορουμανικές επιθέσεις αποκρούστηκαν με βαριές απώλειες και ο στρατός, τον οποίο διοικούσε ο ίδιος ο Τσάρος Αλέξανδρος Β', αναγκάστηκε σε πολιορκία. Η Πλέβνα καταγράφηκε στην ιστορία ως η λαμπρότερη αμυντική επιτυχία του οθωμανικού στρατού τον 19ο αιώνα.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Πτώση της Πλέβνας: κατάρρευση του μετώπου του Δούναβη", "185e7602"], "d": ["Ο Οσμάν Πασάς, του οποίου εξαντλήθηκαν τα εφόδια στην πεντάμηνη πολιορκία, επιχείρησε έξοδο (huruç) μέσω του ποταμού Βιτ· τραυματίστηκε και αιχμαλωτίστηκε και η πόλη παραδόθηκε. Οι Ρώσοι διοικητές χαιρέτησαν τον αιχμάλωτο πασά επιστρέφοντάς του το σπαθί του και στον Οσμάν Πασά δόθηκε ο τίτλος «Γαζής». Με την πτώση της Πλέβνας άνοιξε ο δρόμος για τον ρωσικό στρατό· μέσα σε δύο μήνες έπεσαν η Σόφια, η Φιλιππούπολη και η Αδριανούπολη και τα ρωσικά προπορευόμενα τμήματα έφτασαν στο Γεσίλκιοϊ.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Κατάληψη της Σόφιας από τις ρωσικές δυνάμεις", "ef369d22"], "d": ["Ο ρωσικός στρατός, που υπερέβη τα Βαλκάνια μετά την πτώση της Πλέβνας, μπήκε στην ανυπεράσπιστη Σόφια. Η πόλη δεν θα επέστρεφε ποτέ στην οθωμανική διοίκηση, θα γινόταν το 1878 στα τέλη πρωτεύουσα de facto της Αυτόνομης Ηγεμονίας της Βουλγαρίας, το 1879. Στον χάρτη η Σόφια από αυτή την ημερομηνία βγαίνει από την άμεση οθωμανική διοίκηση και περνά σε προσωρινή ρωσική κατοχή και έπειτα σε αυτόνομη βουλγαρική διοίκηση.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Ανακωχή της Αδριανούπολης: η σιωπή των όπλων στον Πόλεμο του '93", "1f899180"], "d": ["Με τη διαδοχική πτώση της Σόφιας, της Φιλιππούπολης και της Αδριανούπολης και την έλευση του ρωσικού στρατού στις ακτές της Προποντίδας, η Υψηλή Πύλη αναγκάστηκε να ζητήσει ανακωχή. Η εκεχειρία που υπογράφηκε στην Αδριανούπολη επέβαλε στους Οθωμανούς προκαταρκτικούς όρους ειρήνης, όπως αυτονομία για τη Βουλγαρία, ανεξαρτησία για το Μαυροβούνιο, τη Σερβία και τη Ρουμανία και βαριά πολεμική αποζημίωση. Οι όροι αυτοί ένα μήνα αργότερα θα μετατρέπονταν σε κείμενο συνθήκης στο Αγιος Στέφανος (Ayastefanos).", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Αορίστου χρόνου διακοπή της Meclis-i Meb'ûsan από τον Αμπντούλ Χαμίτ Β'", "e770b540"], "d": ["Μετά τις σκληρές επικρίσεις των βουλευτών που θεωρούσαν την κυβέρνηση και το ανάκτορο υπεύθυνα για την καταστροφική έκβαση του πολέμου, ο Αμπντούλ Χαμίτ Β', βασιζόμενος στην εξουσία που του παρείχε το Kanûn-ı Esâsî, διέκοψε τη βουλή επ' αόριστον. Έτσι έκλεισε το πρώτο οθωμανικό κοινοβούλιο, που λειτούργησε περίπου έντεκα μήνες, και άρχισε η εποχή του istibdat (απολυταρχίας) που θα διαρκούσε τριάντα χρόνια. Η βουλή θα μπορούσε να συνέλθει ξανά μόνο μετά την Επανάσταση του 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Συνθήκη του Αγίου Στεφάνου (Ayastefanos): το σχέδιο της Μεγάλης Βουλγαρίας", "2c7cc611"], "d": ["Η Συνθήκη του Αγίου Στεφάνου, που τερμάτισε τον Πόλεμο του '93, ίδρυε μια τεράστια αυτόνομη Βουλγαρία που εκτεινόταν έως το Αιγαίο και περιελάμβανε τη Μακεδονία· αναγνώριζε την ανεξαρτησία της Σερβίας, του Μαυροβουνίου και της Ρουμανίας· παρέδιδε στη Ρωσία το Καρς, το Αρντάχαν, το Μπατούμ και το Ντογουμπαγιαζίτ και επιπλέον φόρτωνε μια πολεμική αποζημίωση αδύνατο να πληρωθεί. Το κείμενο αυτό, που κατέβαζε τη Ρωσία στη Μεσόγειο, προκάλεσε την έντονη αντίδραση της Αγγλίας και της Αυστρίας. Χωρίς να εφαρμοστεί, μέσα σε τέσσερις μήνες αναδιατάχθηκε με το Συνέδριο του Βερολίνου· παρέμεινε ωστόσο το έγγραφο που ανήγγειλε το τέλος της οθωμανικής Ρούμελης.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Το Καρς, το Αρντάχαν και το Μπατούμ παραχωρήθηκαν στη Ρωσία — elviye-i selâse", "99bdfad2"], "d": ["Με τη Συνθήκη του Βερολίνου το Οθωμανικό Κράτος παραχώρησε το Καρς, το Αρντάχαν και το Μπατούμ στη Ρωσία σε αντάλλαγμα μέρους της πολεμικής αποζημίωσης· το Ντογουμπαγιαζίτ και η κοιλάδα του Ελεσκίρτ, που είχαν δοθεί στη Ρωσία στον Άγιο Στέφανο (Ayastefanos), παρέμειναν στους Οθωμανούς. Αν και το Μπατούμ δόθηκε ως ελεύθερο λιμάνι, μπόρεσε να διατηρήσει το καθεστώς αυτό μόνο έως το 1886. Οι Ρώσοι έκαναν το Καρς βιλαέτι εξαρτημένο από τη γενική διοίκηση της Υπερκαυκασίας με κέντρο την Τιφλίδα· από το elviye-i selâse ένας πληθυσμός που έφτανε τις 100.000 αναγκάστηκε να μεταναστεύσει προς την πλευρά του Ερζερούμ. Με την ίδια συνθήκη η Νότια Βεσσαραβία (Κιλία, Κάχουλ, Μπόλγκραντ) επεστράφη από τη Ρουμανία στη Ρωσία.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Κατάληψη της Βοσνίας-Ερζεγοβίνης και του Νόβι Παζάρ από την Αυστροουγγαρία", "e5f901df"], "d": ["Βασιζόμενοι στην εξουσιοδότηση που παρείχε η Συνθήκη του Βερολίνου, οι στρατοί της Αυστροουγγαρίας μπήκαν στη Βοσνία· αν και η οθωμανική κυβέρνηση είχε δεχθεί να μην αντισταθεί, ο ντόπιος μουσουλμανικός-ορθόδοξος λαός στο Σεράγεβο και στο Μόσταρ πήρε τα όπλα και επέδειξε σκληρή αντίσταση επί τρεις μήνες. Η κατάληψη ολοκληρώθηκε μόλις στις 20 Οκτωβρίου 1878. Η νομική κυριαρχία του σουλτάνου συνεχίστηκε στα χαρτιά έως το 1908, ωστόσο η τετρακοσίων ετών οθωμανική Βοσνία χάθηκε de facto και ξεκίνησε ένα μεγάλο κύμα μουσουλμανικής μετανάστευσης. Άλλοι οικισμοί που χάθηκαν την ίδια ημερομηνία: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Διάταγμα του Μουχαρρέμ και ίδρυση της Διοίκησης του Δημοσίου Χρέους (Düyûn-ı Umûmiyye İdaresi)", "02b7cc03"], "d": ["Οι διαπραγματεύσεις με τους εκπροσώπους των κρατών-πιστωτών μετά την πτώχευση του 1875 κατέληξαν στο διάταγμα της 28ης Μουχαρρέμ 1299 (20 Δεκεμβρίου 1881): το κεφάλαιο του χρέους μειώθηκε περισσότερο από το μισό και σε αντάλλαγμα οι πιο αποδοτικές πηγές εσόδων, όπως τα τέλη αλατιού, καπνού, μεταξιού, χαρτοσήμου και αλιείας, μεταβιβάστηκαν στη Διοίκηση του Δημοσίου Χρέους, που διοικούνταν απευθείας από τους πιστωτές. Η διοίκηση αυτή, που απασχολούσε χιλιάδες υπαλλήλους, μετατράπηκε σε ξεχωριστή οικονομική οργάνωση εντός του κράτους. Θεωρείται η ημερομηνία που τερματίστηκε de facto η οθωμανική οικονομική ανεξαρτησία.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Σουάκιν — το μόνο λιμάνι που δεν έπεσε στον Μαχντί", "5a37b198"], "d": ["Από τον Φεβρουάριο του 1884, ενώ όλες οι περιοχές του ανατολικού Σουδάν εκτός από το Σουάκιν περνούσαν στην κυριαρχία του Μουχάμμαντ Αχμέντ ελ-Μαχντί, το λιμάνι διατηρήθηκε χάρη στη στρατιωτική προστασία μιας βρετανικής δύναμης τριών ταγμάτων υπό τον στρατηγό Graham. Αυτή ήταν η αρχή μιας περιόδου κατά την οποία διαχωρίστηκαν η de facto και η νομική κατάσταση: αν και η ακτή βρισκόταν de facto υπό βρετανικό στρατιωτικό έλεγχο, ο διοικητικός δεσμός της το 1885 θα αφαιρούνταν από την Αίγυπτο και θα συνδεόταν απευθείας με το βιλαέτι της Υεμένης, δηλαδή με την Υψηλή Πύλη — η τάξη αυτή διήρκεσε έως το 1888, όταν η Γαλλία κατέλαβε τη Ζεϊλά.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Δολοφονία του Μιντχάτ Πασά στη φυλακή της Ταΐφ", "f4562261"], "d": ["Ο Μιντχάτ Πασάς, αρχιτέκτονας του Kanûn-ı Esâsî και συμβολικό πρόσωπο της Α' Συνταγματικής Περιόδου (I. Meşrutiyet), είχε κριθεί ένοχος στο Δικαστήριο του Γιλντίζ για τον θάνατο του Αμπντούλ Αζίζ και, αφού η ποινή του θανάτου μετατράπηκε σε εξορία, είχε σταλεί στην Ταΐφ. Σύμφωνα με την καταγραφή του TDV, τη νύχτα της 7ης-8ης Μαΐου 1884 στραγγαλίστηκε στο κελί του και ως επίσημη αιτία δηλώθηκε η νόσος «şîrpençe». Ο θάνατός του έγινε σύμβολο της εκκαθάρισης της συνταγματικής αντιπολίτευσης στην εποχή του Αμπντούλ Χαμίτ Β'.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Παραχώρηση του σιδηροδρόμου Χαϊδάρπασα-Άγκυρα στους Γερμανούς", "5705b163"], "d": ["Με διάταγμα του σουλτάνου, το δικαίωμα κατασκευής και εκμετάλλευσης της γραμμής Χαϊδάρπασα-Άγκυρα δόθηκε στον τραπεζίτη Alfred von Kaulla, εκπρόσωπο της Deutsche Bank, και ιδρύθηκε η Εταιρεία Σιδηροδρόμων της Ανατολίας. Η παραχώρηση αυτή ήταν το σημείο καμπής που έσπασε το αγγλογαλλικό μονοπώλιο στις οθωμανικές μεταφορές και την εξωτερική πολιτική και εγκατέστησε τη γερμανική επιρροή. Έντεκα χρόνια αργότερα, με την παραχώρηση της γραμμής της Βαγδάτης στην ίδια εταιρεία, θα γεννιόταν το όραμα «Βερολίνο-Βαγδάτη», το οποίο έγινε ένας από τους κύριους άξονες του μεγάλου ανταγωνισμού πριν τον Α' Παγκόσμιο Πόλεμο.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Ίδρυση της Οθωμανικής Εταιρείας Ένωσης (İttihâd-ı Osmânî Cemiyeti) στην Κωνσταντινούπολη", "b7187939"], "d": ["Τέσσερις φοιτητές της Στρατιωτικής Ιατρικής Σχολής ίδρυσαν ως μυστική οργάνωση εναντίον της απολυταρχικής διοίκησης την İttihâd-ı Osmânî Cemiyeti· η δομή αυτή μετατράπηκε σύντομα στην Εταιρεία Ένωσης και Προόδου (İttihat ve Terakkî Cemiyeti), η οποία θα συγκέντρωνε κάτω από τη στέγη της όλα τα αντιπολιτευτικά στοιχεία του κινήματος των Νεότουρκων. Η οργάνωση που βασιζόταν σε κυψέλες ενώθηκε με τους εξόριστους στην Ευρώπη και τους αξιωματικούς στη Θεσσαλονίκη. Το επιτελείο που το 1908 θα επέβαλε την Β' Συνταγματική Περίοδο και μετά το 1913 θα κυβερνούσε μόνο του το κράτος προήλθε από αυτή τη μικρή φοιτητική κυψέλη.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Επίθεση στην Οθωμανική Τράπεζα: η ενέργεια των Τασνάκ στον Γαλατά", "08b3095f"], "d": ["Μια ένοπλη ομάδα της αρμενικής οργάνωσης Τασνακτσουτιούν, με σκοπό να στρέψει την προσοχή της Ευρώπης στο Αρμενικό Ζήτημα, εισέβαλε στα κεντρικά της Οθωμανικής Τράπεζας στον Γαλατά, πήρε ομήρους και απείλησε να ανατινάξει το κτίριο. Η κρίση έληξε με την παρέμβαση των πρεσβευτών, με αντάλλαγμα να βγουν οι δράστες από τη χώρα με πλοίο. Τα αιματηρά γεγονότα που ακολούθησαν την επίθεση στην Κωνσταντινούπολη υπήρξαν καθοριστικά για τη μετατροπή του Αρμενικού Ζητήματος σε μοχλό διεθνούς παρέμβασης.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Έναρξη του Οθωμανοελληνικού Πολέμου του 1897: το μέτωπο της Θεσσαλίας", "33e490ab"], "d": ["Μετά την απόβαση ναυτικού και στρατού της Ελλάδας στην Κρήτη και τις επιθέσεις ατάκτων στα σύνορα της Ρούμελης, το Οθωμανικό Κράτος κήρυξε πόλεμο. Ο οθωμανικός στρατός, εκπαιδευμένος από γερμανική αποστολή μεταρρυθμίσεων, προέλασε γρήγορα στη Θεσσαλία και μέσα σε ένα μήνα κατέλαβε τη Λάρισα (Yenişehir), τον Φάρσαλο (Çatalca) και τον Δομοκό (Dömeke)· ο ελληνικός στρατός διαλύθηκε. Με την παρέμβαση των μεγάλων δυνάμεων τα κερδισμένα εδάφη επεστράφησαν, ωστόσο ο πόλεμος παρέμεινε η μοναδική αποφασιστική στρατιωτική νίκη της εποχής του Αμπντούλ Χαμίτ Β' και δεν μπόρεσε να αποτρέψει de facto την απώλεια της Κρήτης.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Παραχώρηση της γραμμής Ικονίου-Βαγδάτης στους Γερμανούς", "fd8b6cbd"], "d": ["Μετά την επίσκεψη του Κάιζερ Γουλιέλμου Β' στην Κωνσταντινούπολη και τη Δαμασκό το 1898, στην Εταιρεία Σιδηροδρόμων της Ανατολίας δόθηκε η προκαταρκτική παραχώρηση της γραμμής που θα εκτεινόταν από το Ικόνιο έως τη Βαγδάτη και τη Βασόρα. Το έργο του Σιδηροδρόμου της Βαγδάτης σήμαινε για τους Οθωμανούς ενίσχυση του κεντρικού ελέγχου επί των αραβικών βιλαετιών και για τη Γερμανία πρόσβαση στον Περσικό Κόλπο. Το έργο αυτό, στο οποίο αντιτάχθηκαν σφοδρά η Αγγλία και η Ρωσία, έγινε ένας από τους πιο αμφιλεγόμενους φακέλους του ιμπεριαλιστικού ανταγωνισμού που οδήγησε στον Α' Παγκόσμιο Πόλεμο.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Έναρξη των εργασιών του Σιδηροδρόμου του Χετζάζ στη Δαμασκό", "62f58f68"], "d": ["Η γραμμή, που διέταξε ο Αμπντούλ Χαμίτ Β' με το διάταγμα της 2ας Μαΐου 1900, ξεκίνησε να κατασκευάζεται στις 1 Σεπτεμβρίου 1900 με επίσημη τελετή στη Δαμασκό. Το έργο, που υλοποιήθηκε εξ ολοκλήρου με δωρεές από τον ισλαμικό κόσμο και με τον μόχθο οθωμανών μηχανικών-στρατιωτών, μείωσε το ταξίδι των προσκυνητών Δαμασκός-Μεδίνα από σαράντα μέρες σε πέντε. Ήταν ταυτόχρονα ένα έργο γοήτρου που ενίσχυε την πνευματική εξουσία του χαλιφάτου και μια στρατηγική επένδυση που ενίσχυε τον στρατιωτικό έλεγχο επί του Χετζάζ.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Πρόγραμμα του Μιρτσστέγκ (Mürzsteg): διεθνής μεταρρυθμιστικός έλεγχος στη Μακεδονία", "4c7464da"], "d": ["Μετά την εξέγερση του Ίλιντεν, οι αυτοκράτορες της Ρωσίας και της Αυστρίας συναντήθηκαν στο Μιρτσστέγκ και ετοίμασαν ένα νέο πακέτο μεταρρυθμίσεων για τη Μακεδονία. Το πρόγραμμα προέβλεπε την τοποθέτηση δύο ξένων πολιτικών πρακτόρων δίπλα στον οθωμανικό γενικό επιθεωρητή, την αναδιοργάνωση της χωροφυλακής από Ευρωπαίους αξιωματικούς και την αλλαγή των διοικητικών συνόρων με βάση την εθνικότητα. Αν και η Υψηλή Πύλη αντιστάθηκε με το σκεπτικό ότι θίγονταν τα δικαιώματα κυριαρχίας, αναγκάστηκε να δεχθεί μπροστά στην κοινή πίεση· το πρόγραμμα ήταν ένας από τους βασικούς παράγοντες που επιτάχυναν την οργάνωση των Ιττιχατικών μεταξύ των νεαρών αξιωματικών.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Θάνατος του Μουράτ Ε'", "396659a7"], "d": ["Ο Μουράτ Ε', που παρέμεινε στον θρόνο περίπου τρεις μήνες το 1876 και καθαιρέθηκε, μετά τις απόπειρες να επανέλθει στον θρόνο έζησε επί είκοσι οκτώ χρόνια φυλακισμένος υπό αυστηρή φρούρηση και πέθανε από διαβήτη. Τάφηκε δίπλα στη μητέρα του στο Μαυσωλείο Cedîd Havâtîn στο Γενί Τζαμί. Έμεινε στην ιστορία ως ο οθωμανός σουλτάνος που έμεινε στον θρόνο το λιγότερο.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Απώλεια της Σανάα από τον Ιμάμη Γιαχιά", "e7f876cb"], "d": ["Η εξέγερση που ξεκίνησε το 1904 ο Ζαϊντίτης Ιμάμης Γιαχιά Χαμιντουντντίν κατέληξε τον Απρίλιο του 1905 στην πτώση της Σανάα έπειτα από πολιορκία· η πόλη βγήκε από την οθωμανική διοίκηση και κατά τη διάρκεια της πολιορκίας εμφανίστηκαν πείνα και επιδημία. Η ορεινή γεωγραφία της Υεμένης, το μήκος των γραμμών ανεφοδιασμού και η τοπική νομιμότητα του ζαϊντιτικού ιμαμάτου έκαναν την οθωμανική κυριαρχία εκεί εύθραυστη από την αρχή της. Η πόλη θα ανακαταλαμβανόταν πέντε μήνες αργότερα με βαριές απώλειες, ωστόσο το ζήτημα της Υεμένης δεν θα έκλεινε έως το 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Απόπειρα του Γιλντίζ: βομβιστική επίθεση κατά του Αμπντούλ Χαμίτ Β'", "1ee2e1a6"], "d": ["Η οργάνωση Τασνακτσουτιούν οργάνωσε απόπειρα δολοφονίας με την έκρηξη ενός landau με βόμβα χρονοδιακόπτη στην άμαξα του σουλτάνου που έβγαινε από την παρασκευιάτικη τελετή selâmlık· η καθυστέρηση του Αμπντούλ Χαμίτ για λίγα λεπτά, επειδή μιλούσε με τον Σεϊχουλισλάμ, του έσωσε τη ζωή. Στην έκρηξη σκοτώθηκαν είκοσι έξι άτομα και τραυματίστηκαν περισσότερα από πενήντα. Το γεγονός έκανε ακόμη πιο σκληρή την εμμονή του σουλτάνου με την ασφάλεια και την απολυταρχική διοίκηση που βασιζόταν στην οργάνωση των κατασκόπων· έγινε και θέμα του ποιήματος «Bir Lahza-i Taahhur» του Τεβφίκ Φικρέτ.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Ανακατάληψη της Σανάα: καταστολή της εξέγερσης του Ιμάμη Γιαχιά", "dec3b8f9"], "d": ["Η εξέγερση που ξεκίνησε το 1904 υπό την ηγεσία του Ζαϊντίτη Ιμάμη Γιαχιά κατέληξε τον Απρίλιο του 1905 στην πτώση της Σανάα και στην πόλη εμφανίστηκαν πείνα και επιδημία. Οι ενισχυτικοί στρατοί υπό τη διοίκηση του Αλή Ριζά Πασά και του Αχμέτ Φεϊζί Πασά, με επιχείρηση που διεξήγαγαν από τις 15 Ιουλίου έως την 1η Σεπτεμβρίου 1905 και την οποία υποστήριξαν και οι δυνάμεις στην Ταΐζ, ανακατέλαβαν την πόλη με βαριές απώλειες και η εξέγερση καταστάλθηκε. Η εκστρατεία της Υεμένης επέφερε στον οθωμανικό στρατό δεκάδες χιλιάδες απώλειες και τεράστιο οικονομικό βάρος· ο φόβος της «εξορίας στην Υεμένη» μεταξύ των αξιωματικών της Ρούμελης ήταν από τα κυριότερα παράπονα που τροφοδοτούσαν την ιττιχατική οργάνωση.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Συνέλευση της πρώτης Meclis-i Meb'ûsan της Β' Συνταγματικής Περιόδου", "e7fd2716"], "d": ["Η βουλή που σχηματίστηκε με διβάθμιες εκλογές μετά από διάλειμμα τριάντα ετών εγκαινιάστηκε στις 17 Δεκεμβρίου 1908 με λόγο του σουλτάνου και πρόεδρός της εξελέγη ο ηγέτης του κινήματος των Νεότουρκων Αχμέτ Ριζά Μπέης. Η βουλή, που αποτελούνταν από Τούρκους, Άραβες, Αλβανούς, Ρωμιούς, Αρμένιους και Εβραίους βουλευτές, ήταν η τελευταία μεγάλη δοκιμή του οθωμανισμού (Osmanlıcılık). Ωστόσο η ανεξαρτησία της Βουλγαρίας, η προσάρτηση της Βοσνίας και η διακήρυξη της ένωσης της Κρήτης με την Ελλάδα είχαν επισκιάσει αυτή την αισιοδοξία πριν καν ανοίξει η βουλή.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Ο Στρατός Κινήσεως (Hareket Ordusu) και η καθαίρεση του Αμπντούλ Χαμίτ Β': ανάρρηση του Μεχμέτ Ρεσάτ Ε'", "6a65a704"], "d": ["Μετά το Επεισόδιο της 31ης Μαρτίου, ο Στρατός Κινήσεως, που ξεκίνησε από τη Θεσσαλονίκη, μπήκε στην Κωνσταντινούπολη από τέσσερις κατευθύνσεις τη νύχτα της 22ας-23ης Απριλίου και στις 24 Απριλίου παραδόθηκε το Ανάκτορο Γιλντίζ. Η Meclis-i Umûmî-i Millî αποφάσισε στις 27 Απριλίου την καθαίρεση του Αμπντούλ Χαμίτ Β'· ο σουλτάνος στάλθηκε στη Θεσσαλονίκη και στη θέση του ανέβηκε στον θρόνο ο αδελφός του Μεχμέτ Ρεσάτ Ε'. Έτσι έληξε η τριάντα τριών ετών προσωπική διακυβέρνηση, ωστόσο τη θέση της πήρε μια νέα περίοδος κατά την οποία ο σουλτάνος έγινε σύμβολο και η Ένωση και Πρόοδος διοικούσε με τη στήριξη του στρατού.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Εξέγερση της Αλβανίας: ένοπλη αντίσταση στο Κοσσυφοπέδιο και στη Σκόδρα", "93ed30c6"], "d": ["Η συγκεντρωτική φορολογική πολιτική της κυβέρνησης των Ιττιχατικών, η εκστρατεία συλλογής όπλων και η συζήτηση για το λατινικό αλφάβητο ξεσήκωσαν τις αλβανικές φυλές, που μέχρι τότε θεωρούνταν από τα πιο πιστά προς το κράτος στοιχεία. Αν και ο στρατός υπό τη διοίκηση του Μαχμούτ Σεβκέτ Πασά κατέστειλε σκληρά την εξέγερση, η αναταραχή αναζωπυρώθηκε το 1911 και το 1912. Οι εξεγέρσεις αυτές, εκτός του ότι φθείρανε τον οθωμανικό στρατό παραμονές του Βαλκανικού Πολέμου, επιτάχυναν και τη γέννηση του αλβανικού εθνικού κινήματος.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Συνθήκη του Ουσί (Uşi): παραχώρηση της Τρίπολης της Λιβύης και της Βεγγάζης στην Ιταλία", "4ffa1fd2"], "d": ["Η Υψηλή Πύλη, που δεν μπορούσε να αντιμετωπίσει μια σύγκρουση σε δύο μέτωπα μπροστά στις πολεμικές προετοιμασίες των βαλκανικών κρατών, υπέγραψε με την Ιταλία μυστική ειρήνη στην ελβετική κωμόπολη Ουσί και εγκατέλειψε την Τρίπολη της Λιβύης και τη Βεγγάζη. Έτσι το Οθωμανικό Κράτος έχασε το τελευταίο του έδαφος στην Αφρική· σε αντάλλαγμα υποσχέθηκε η επιστροφή της Ρόδου και των Δωδεκανήσων που είχε καταλάβει η Ιταλία, αλλά η υπόσχεση αυτή δεν τηρήθηκε ποτέ. Όταν υπογράφηκε η συνθήκη, ο Βαλκανικός Πόλεμος είχε ήδη ξεκινήσει. Με το γεγονός αυτό η Murzuk (Fizan), η Gât, η Sebha, η Ubârî, η Tırgan (Traghan), η Zevîle (Zawila) και η el-Katrûn (Fizan (σαντζάκι του βιλαετιού της Τρίπολης της Λιβύης)) πέρασαν στην ιταλική διοίκηση.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Κατάληψη της Λήμνου από την Ελλάδα", "9555af1d"], "d": ["Στον Α' Βαλκανικό Πόλεμο ο ελληνικός στόλος κατέλαβε τη Λήμνο· το λιμάνι του Μούδρου του νησιού έγινε βάση για τον αποκλεισμό του Στενού των Δαρδανελίων. Το νησί αφέθηκε στην Ελλάδα στη Λωζάνη (24 Ιουλίου 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Κατάληψη της Θάσου από την Ελλάδα", "6c03c7f0"], "d": ["Στον Α' Βαλκανικό Πόλεμο η Ελλάδα κατέλαβε τη Θάσο και τη Σαμοθράκη.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Κατάληψη της Σαμοθράκης από την Ελλάδα", "911e82a3"], "d": ["Στον Α΄ Βαλκανικό Πόλεμο η Ελλάδα κατέλαβε τη Σαμοθράκη.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Κατάληψη της Μυτιλήνης από την Ελλάδα", "6b2b07ba"], "d": ["Ο ελληνικός στόλος αποβιβάστηκε στη Μυτιλήνη· το νησί καταλήφθηκε από τον ελληνικό στρατό και στόλο στο τέλος του Α΄ Βαλκανικού Πολέμου. Η Διάσκεψη του Λονδίνου (Μάιος 1913) επιβεβαίωσε την κατάσταση.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Ελληνική απόβαση στη Χίο", "901c6539"], "d": ["Στη Χίο, που βομβαρδίστηκε στις 7 Απριλίου 1912 στον Α' Βαλκανικό Πόλεμο, οι Έλληνες πραγματοποίησαν απόβαση· η οθωμανική φρουρά παραδόθηκε στις 3 Ιανουαρίου 1913. Το νησί αφέθηκε στην Ελλάδα με τη Συνθήκη της Λωζάνης (24 Ιουλίου 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Δολοφονία του Μέγα Βεζίρη Μαχμούτ Σεβκέτ Πασά στην Κωνσταντινούπολη", "68e60e63"], "d": ["Ο Μαχμούτ Σεβκέτ Πασάς, που διορίστηκε Μέγας Βεζίρης μετά την Επιδρομή στην Υψηλή Πύλη (Bâb-ı Âli Baskını), σκοτώθηκε με πυρά που άνοιξαν στην άμαξά του κοντά στην Τσαρσικαπί καθώς πήγαινε στο Υπουργείο Πολέμου. Η Ένωση και Πρόοδος, φορτώνοντας τη δολοφονία στην αντιπολίτευση, ξεκίνησε ένα ευρύ κύμα συλλήψεων και εκτελέσεων και το Κόμμα Ελευθερίας και Συμφωνίας (Hürriyet ve İtilâf Fırkası) εκκαθαρίστηκε de facto. Με το γεγονός αυτό η μονοκομματική δικτατορία των Ιττιχατικών, που βασιζόταν στην τριάδα Ενβέρ-Ταλάτ-Τζεμάλ, εγκαθιδρύθηκε οριστικά.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Έναρξη του Β' Βαλκανικού Πολέμου: η διαμάχη των συμμάχων για τη διανομή", "48d088a2"], "d": ["Οι βαλκανικοί σύμμαχοι, που δεν μπόρεσαν να μοιράσουν τα εδάφη που πήραν από τους Οθωμανούς με τη Συνθήκη του Λονδίνου, στράφηκαν ο ένας εναντίον του άλλου· με την επίθεση της Βουλγαρίας στις σερβικές και ελληνικές θέσεις άρχισε ο δεύτερος πόλεμος. Όταν η Ρουμανία και το Μαυροβούνιο μπήκαν στο μέτωπο εναντίον της Βουλγαρίας, ο βουλγαρικός στρατός κατέρρευσε. Το Οθωμανικό Κράτος, αξιοποιώντας την ευκαιρία, ξεπέρασε τη γραμμή Μίδια-Ενέζ που είχε χαράξει η Συνθήκη του Λονδίνου και ανέκτησε την Ανατολική Θράκη μαζί με την Αδριανούπολη.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Συνθήκη της Κωνσταντινούπολης: ειρήνη με τη Βουλγαρία και νομική κατοχύρωση της Αδριανούπολης", "c8c18b2d"], "d": ["Η συνθήκη που υπογράφηκε ανάμεσα στο Οθωμανικό Κράτος και τη Βουλγαρία μετά τον Β' Βαλκανικό Πόλεμο, αποδεχόμενη τον ποταμό Έβρο (Meriç) ως σύνορο, κατοχύρωσε νομικά την παραμονή της Αδριανούπολης, της Λουλέ Μπουργκάς (Kırklareli), του Διδυμοτείχου και της Ανατολικής Θράκης στους Οθωμανούς. Η Αλεξανδρούπολη (Dedeağaç) αφέθηκε στη Βουλγαρία (ενώ η Καβάλα είχε περάσει στην Ελλάδα τον Ιούλιο του 1913 μετά τη βουλγαρική κατοχή του φθινοπώρου του 1912 και κατοχυρώθηκε στην Ελλάδα με τη Συνθήκη του Βουκουρεστίου της 10ης Αυγούστου 1913), ρυθμίστηκαν η αμοιβαία ανταλλαγή πληθυσμών μεταξύ των δύο χωρών και τα δικαιώματα των μουσουλμάνων στη Βουλγαρία. Η εγγύηση του μοναδικού τμήματος εδάφους που μπόρεσε να ανακτηθεί από τη βαλκανική καταστροφή είναι αυτό το κείμενο. Άλλα μέρη που προσαρτήθηκαν την ίδια ημερομηνία: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Ανακατάληψη της Τενέδου και της Ίμβρου — Συνθήκη της Αθήνας", "ec084d09"], "d": ["Από τα νησιά του Βορείου Αιγαίου που κατέλαβε η Ελλάδα στον Βαλκανικό Πόλεμο, η Τένεδος και η Ίμβρος, που κρατούν την είσοδο του Στενού, θεωρήθηκαν στις διαπραγματεύσεις της Συνθήκης της Αθήνας απαραίτητα για την άμυνα των Δαρδανελίων και επεστράφησαν στους Οθωμανούς. Τα άλλα νησιά παρέμειναν στην Ελλάδα. Τα δύο αυτά νησιά ήταν τα τελευταία εδάφη που κρατούσε η αυτοκρατορία στο Αιγαίο και στη Λωζάνη αφέθηκαν και αυτά στην Τουρκία.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Συνθήκη της Αθήνας: ειρήνη με την Ελλάδα και παραχώρηση της Θεσσαλονίκης και των Ιωαννίνων", "8e94def7"], "d": ["Η συνθήκη που υπογράφηκε ανάμεσα στο Οθωμανικό Κράτος και την Ελλάδα αναγνώρισε επίσημα την παραχώρηση στην Ελλάδα της Θεσσαλονίκης, των Ιωαννίνων και της Νότιας Μακεδονίας που χάθηκαν στον Βαλκανικό Πόλεμο και αποποιήθηκε τα οθωμανικά δικαιώματα επί της Κρήτης. Ρυθμίστηκαν λεπτομερώς τα θρησκευτικά και ιδιοκτησιακά δικαιώματα των μουσουλμάνων που παρέμεναν στην Ελλάδα, το καθεστώς των βακουφίων και ο διορισμός των μουφτήδων. Το καθεστώς των νησιών του Αιγαίου αφέθηκε άλυτο και παρέμεινε πηγή διαρκούς έντασης μεταξύ των δύο κρατών.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Υπογραφή της μυστικής οθωμανογερμανικής συμφωνίας συμμαχίας στην Κωνσταντινούπολη", "0472efb3"], "d": ["Μόλις ξέσπασε ο πόλεμος στην Ευρώπη, στο αρχοντικό του Μέγα Βεζίρη Σαΐντ Χαλίμ Πασά υπογράφηκε μυστική συμφωνία συμμαχίας ανάμεσα στο Οθωμανικό Κράτος και τη Γερμανία· το κείμενο προέβλεπε ότι σε περίπτωση που η Ρωσία εισερχόταν στον πόλεμο εναντίον της Γερμανίας, θα τάσσονταν και οι Οθωμανοί στο πλευρό της Γερμανίας. Η συμφωνία κρύφτηκε ακόμη και από το υπουργικό συμβούλιο και ήταν γνωστή μόνο σε τέσσερα άτομα. Τρεις μήνες αργότερα, με την Επιδρομή στη Μαύρη Θάλασσα, το Οθωμανικό Κράτος θα παρασυρόταν de facto στον πόλεμο και η μοίρα της αυτοκρατορίας θα δενόταν με αυτό το έγγραφο.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Μονομερής κατάργηση των Capitulations (Kapitülasyonlar)", "ec773d18"], "d": ["Η οθωμανική κυβέρνηση, σε μια στιγμή που η Ευρώπη ήταν απασχολημένη με τον πόλεμο, ανακοίνωσε ότι καταργεί μονομερώς από την 1η Οκτωβρίου 1914 τις συνθήκες Capitulations που παρείχαν στους ξένους δικαστικά, οικονομικά και τελωνειακά προνόμια. Το τέλος αυτού του τετρακοσίων ετών καθεστώτος προνομίων υποδέχθηκε στη χώρα με μεγάλο ενθουσιασμό ανεξαρτησίας και στην Κωνσταντινούπολη έγιναν εορτασμοί. Όλα τα κράτη, μεταξύ των οποίων και η σύμμαχος Γερμανία, διαμαρτυρήθηκαν για την απόφαση· οι Capitulations θα έβγαιναν οριστικά από την ιστορία μόλις το 1923 στη Λωζάνη.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Επιδρομή στη Μαύρη Θάλασσα: βομβαρδισμός ρωσικών λιμανιών από τον οθωμανικό στόλο", "8ad4ef61"], "d": ["Τα Goeben και Breslau (Yavuz και Midilli), που είχαν διαφύγει από τη Γερμανία και προσχώρησαν στον οθωμανικό στόλο σαν να είχαν «αγοραστεί», βγήκαν στη Μαύρη Θάλασσα υπό τη διοίκηση του ναυάρχου Souchon, βομβάρδισαν ρωσικά λιμάνια και βύθισαν πλοία. Η εντολή αυτή που έδωσε ο Ενβέρ Πασάς κρυφά από το υπουργικό συμβούλιο έβαλε de facto τέλος στην ουδετερότητα. Μέσα σε μια εβδομάδα η Ρωσία, η Αγγλία και η Γαλλία κήρυξαν πόλεμο και το Οθωμανικό Κράτος μπήκε αμετάκλητα στον Α' Παγκόσμιο Πόλεμο.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Κατάληψη του Φάβ (Fâv) από βρετανοϊνδικές δυνάμεις — άνοιγμα του μετώπου του Ιράκ", "08663813"], "d": ["Το πρωί της επομένης της ημέρας που τα κράτη της Αντάντ κήρυξαν πόλεμο στο Οθωμανικό Κράτος, η βρετανοϊνδική ταξιαρχία που περίμενε στο Μπαχρέιν αποβιβάστηκε στο Φάβ, στις εκβολές του Σατ ελ-Αράμπ. Η μικρή οθωμανική μονάδα στο ερειπωμένο φρούριο του Φάβ αποσύρθηκε υπό τα πυρά των πολεμικών πλοίων και ο σταθμός της τηλεγραφικής γραμμής της Ινδίας έπεσε στα χέρια των Βρετανών. Το μέτωπο του Ιράκ άνοιξε έτσι.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Κήρυξη του Cihâd-ı Ekber: ανάγνωση της φετβά του τζιχάντ στο Τέμενος του Φατίχ", "2a6174e8"], "d": ["Οι πέντε φετβάδες που εξέδωσε ο Σεϊχουλισλάμ Ουργκιουπλού Χαϊρή Εφέντη διαβάστηκαν στο Τέμενος του Φατίχ εξ ονόματος του χαλίφη-σουλτάνου και όλοι οι μουσουλμάνοι κλήθηκαν σε τζιχάντ εναντίον των κρατών της Αντάντ. Η κίνηση αυτή, στην οποία η Γερμανία είχε εναποθέσει μεγάλες ελπίδες, στόχευε στην εξέγερση των μουσουλμάνων στις βρετανικές και γαλλικές αποικίες. Η αναμενόμενη γενική εξέγερση δεν πραγματοποιήθηκε· αντιθέτως, η εξέγερση του Εμίρη της Μέκκας Σερίφη Χουσεΐν δύο χρόνια αργότερα με βρετανική υποστήριξη έδειξε οδυνηρά τα όρια της πολιτικής επιρροής του χαλιφάτου.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Παράδοση της Κούρνα στους Βρετανούς", "621d36b0"], "d": ["Οι δυνάμεις του βαλή της Βασόρας Σουμπχί Μπέη, που είχαν υποχωρήσει στην Κούρνα, όπου ενώνονται ο Τίγρης και ο Ευφράτης, μετά την πτώση της Βασόρας, παραδόθηκαν το πρωί της 9ης Δεκεμβρίου 1914 μετά τις συγκρούσεις της 4ης-8ης Δεκεμβρίου.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Θέση της Αιγύπτου υπό βρετανική προστασία και ανακήρυξη σουλτανάτου", "55d4e520"], "d": ["Με την είσοδο του Οθωμανικού Κράτους στον πόλεμο, η Αγγλία ανακοίνωσε ότι θέτει επίσημα υπό την προστασία της την Αίγυπτο, την οποία κρατούσε de facto υπό κατοχή από το 1882· ο Χεδίβης Αμπάς Χιλμή Πασάς, που παρέμενε πιστός στους Οθωμανούς, καθαιρέθηκε και στη θέση του τοποθετήθηκε ο Χουσεΐν Καμίλ με τον τίτλο του «σουλτάνου». Έτσι τερματίστηκε μονομερώς η νομική οθωμανική κυριαρχία που διαρκούσε από το 1517. Η Υψηλή Πύλη δεν αναγνώρισε την απόφαση και δύο μήνες αργότερα επιχείρησε να ανακτήσει την Αίγυπτο με την Επιχείρηση της Διώρυγας.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Επιχείρηση του Σαρίκαμις (Sarıkamış): καταστροφή στο μέτωπο του Καυκάσου", "5cbde7f0"], "d": ["Ο Ενβέρ Πασάς, με σκοπό να ανακτήσει το Καρς-Αρντάχαν-Μπατούμ που χάθηκαν το 1878 και να εξεγείρει τους Τούρκους του Καυκάσου, οδήγησε τον Γ' Στρατό τον χειμώνα σε ελιγμό περικύκλωσης των ρωσικών δυνάμεων πάνω από τα όρη Αλλαχουεκμπέρ. Λόγω του ανεπαρκούς χειμερινού εξοπλισμού, του εξαντλημένου ανεφοδιασμού και της χιονοθύελλας που έφτανε τους μείον τριάντα βαθμούς, ο στρατός διαλύθηκε πριν καν μπει στη μάχη· δεκάδες χιλιάδες στρατιώτες πέθαναν από το κρύο. Η επιχείρηση υπήρξε μία από τις βαρύτερες καταστροφές των Οθωμανών στον πόλεμο και άφησε το ανατολικό μέτωπο ανυπεράσπιστο για δύο χρόνια.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Πρώτη Επιχείρηση της Διώρυγας: επίθεση στο Σουέζ μέσω της ερήμου του Σινά", "02dd72f5"], "d": ["Ο διοικητής του Δ' Στρατού Τζεμάλ Πασάς, με σκοπό να ελευθερώσει την Αίγυπτο από τη βρετανική κατοχή και να κλείσει τη Διώρυγα του Σουέζ στη ναυσιπλοΐα, οργάνωσε επίθεση που διέσχιζε την έρημο του Σινά. Αν και οι οθωμανικές μονάδες έφτασαν στην ανατολική όχθη της διώρυγας και μέρος τους κατάφερε να περάσει απέναντι, υποχώρησαν λόγω της βρετανικής υπεροχής και επειδή δεν πραγματοποιήθηκε η αναμενόμενη λαϊκή εξέγερση στην Αίγυπτο. Η επιχείρηση δεν πέτυχε τον στόχο της, δημιούργησε ωστόσο έμμεση στρατηγική επίδραση αναγκάζοντας την Αγγλία να διατηρεί μεγάλη δύναμη στην Αίγυπτο.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Έκδοση του Νόμου Αποστολής και Εγκατάστασης (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["Μετά την εξέγερση του Βαν και την ρωσική προέλαση, η κυβέρνηση εξέδωσε τον προσωρινό νόμο που επέτρεπε στους διοικητές του στρατού να μεταφέρουν σε άλλες περιοχές τον πληθυσμό που θεωρούνταν ότι διαταράσσει την ασφάλεια στα μετόπισθεν του μετώπου, και ο σουλτάνος τον επικύρωσε στις 27 Μαΐου 1915. Ως αποτέλεσμα της εφαρμογής, το μεγαλύτερο μέρος του αρμενικού πληθυσμού των ανατολικών και νότιων βιλαετιών της Ανατολίας στάλθηκε προς τη Συρία και τη Μοσούλη· κατά τη διάρκεια της αποστολής σημειώθηκαν πολύ μεγάλες απώλειες ζωών λόγω ασθενειών, πείνας και επιθέσεων. Η απόφαση παραμένει το βαρύτερο και ακόμη και σήμερα πιο αμφιλεγόμενο ζήτημα των τελευταίων ετών των Οθωμανών.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Οθωμανικές μονάδες ανακατέλαβαν το Μους από τη ρωσική κατοχή", "fb1be113"], "d": ["Έξι μήνες μετά την πρώτη ρωσική κατοχή του Μους, το οθωμανικό 16ο Σώμα Στρατού μπήκε στην κωμόπολη στην αντεπίθεση Μπιτλίς-Μους.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Το Μους πέρασε ξανά στα ρωσικά χέρια", "43ad8a03"], "d": ["Με τη ρωσική αντεπίθεση το οθωμανικό απόσπασμα εκκένωσε το Μους· η κωμόπολη μπήκε ξανά υπό ρωσική κατοχή μεταξύ 22 και 25 Αυγούστου 1916 και παρέμεινε σε αυτήν έως την άνοιξη του 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Το Μους απελευθερώθηκε οριστικά από τη ρωσική κατοχή", "f0e89703"], "d": ["Το Μους, που είχε περάσει υπό ρωσική κατοχή στον Α' Παγκόσμιο Πόλεμο, ανακαταλήφθηκε οριστικά από τις οθωμανικές δυνάμεις την 1η Μαΐου 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Θάνατος του Αμπντούλ Χαμίτ Β' στο Ανάκτορο Μπεϊλερμπέη", "c9662582"], "d": ["Ο Αμπντούλ Χαμίτ Β', που καθαιρέθηκε το 1909 και μεταφέρθηκε πρώτα στη Θεσσαλονίκη και, με την απώλεια της πόλης στον Βαλκανικό Πόλεμο, στην Κωνσταντινούπολη, όπου τον κρατούσαν σε κατ' οίκον περιορισμό στο Ανάκτορο Μπεϊλερμπέη, πέθανε. Κατά την τριάντα τριών ετών βασιλεία του προσπάθησε να κερδίσει χρόνο κρατώντας το κράτος μακριά από πολέμους, αλλά ήταν γνωστός και για την απολυταρχική διοίκηση. Η κηδεία του έγινε με μεγάλο πλήθος και τάφηκε στο Μαυσωλείο του Μαχμούτ Α' στη Divanyolu· ο θάνατός του συνέπεσε με μια πολεμική χρονιά κατά την οποία το καθεστώς που είχε οικοδομήσει είχε ήδη εκκαθαριστεί.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Συνθήκη του Μπρεστ-Λιτόφσκ: ανάκτηση του Καρς, του Αρντάχαν και του Μπατούμ", "da82636f"], "d": ["Η συνθήκη που υπογράφηκε ανάμεσα στη Ρωσία, που αποσύρθηκε από τον πόλεμο μετά την μπολσεβίκικη επανάσταση, και τις Κεντρικές Δυνάμεις έκλεισε το Ανατολικό μέτωπο και έδωσε πίσω στο Οθωμανικό Κράτος το Καρς, το Αρντάχαν και το Μπατούμ (Elviye-i Selâse) που είχε χάσει με τη Συνθήκη του Βερολίνου του 1878. Αυτό ήταν το μοναδικό εδαφικό κέρδος που αποκτήθηκε στην οθωμανική ιστορία μετά από σαράντα χρόνια. Ωστόσο μετά την Ανακωχή του Μούδρου η περιοχή θα χανόταν ξανά και η οριστική λύση θα ερχόταν με τη Συνθήκη του Καρς το 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Οθωμανικές μονάδες μπήκαν στο Αρτβίν", "ca7d1778"], "d": ["Οι οθωμανικές μονάδες που στις 25 Μαρτίου ξεπέρασαν τα σύνορα του 1914 βάδισαν προς το Elviye-i Selâse, του οποίου το Μπρεστ-Λιτόφσκ επέστρεφε τα σύνορα πριν το 1878, και μπήκαν στο Αρτβίν στις 28 Μαρτίου 1918. Το Αρτβίν είχε παραχωρηθεί στη Ρωσία το 1878 ως τμήμα του σαντζακιού του Μπατούμ· το λήμμα Artvin του TDV γράφει την επιστροφή μόνο ως «Μάρτιος 1918», την ημέρα την δίνει ο Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Το Αρντάχαν πέρασε στα χέρια του τουρκικού στρατού", "7fd9e3db"], "d": ["Στην επιχείρηση Elviye-i Selâse ο οθωμανικός στρατός, μετά το Αρτβίν, κατέλαβε το Αρντάχαν στις 3 Απριλίου 1918· το Αρντάχαν είχε πέσει το 1877 στον Πόλεμο του Ενενήντα Τρία και είχε αφεθεί στη Ρωσία το 1878. Το Καρς θα καταλαμβανόταν ένα μήνα αργότερα, στις 25 Απριλίου.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Ανάκτηση του Μπατούμ", "d37a1a0d"], "d": ["Ο οθωμανικός στρατός, που προέλασε προς την ανατολή όταν η Ρωσία αποσύρθηκε από τον πόλεμο με τη Συνθήκη του Μπρεστ-Λιτόφσκ, ανέκτησε μετά από σαράντα χρόνια το λιμάνι του Μπατούμ, που είχε χαθεί το 1878. Το λιμάνι αυτό, στο ανατολικό άκρο της Μαύρης Θάλασσας, ήταν η θαλάσσια έξοδος του πετρελαίου του Μπακού. Το κέρδος διήρκεσε μόλις επτά μήνες· μετά την Ανακωχή του Μούδρου η περιοχή θα εκκενωνόταν.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: το Καρς μπήκε στην οθωμανική διοίκηση", "02cbf0b3"], "d": ["Στο Μπρεστ-Λιτόφσκ αποφασίστηκε η επιστροφή των τριών σαντζακιών — Καρς, Αρντάχαν και Μπατούμ — που χάθηκαν με τη Συνθήκη του Βερολίνου του 1878· ο οθωμανικός στρατός μπήκε στο Αρντάχαν στις 3 Απριλίου, στο Μπατούμ στις 14 Απριλίου και στο Καρς στις 25 Απριλίου 1918 και η διοίκηση εγκαθιδρύθηκε de facto. Τα εδάφη αυτά, που αναφέρονται με το όνομα «Elviye-i Selâse», θεωρήθηκαν αποζημίωση για την απώλεια που συνεχιζόταν από τον Πόλεμο του Ενενήντα Τρία (Doksanüç Harbi). Μετά την ανακωχή θα χάνονταν ξανά και θα ενσωματώνονταν οριστικά στην Τουρκία μόλις με τη Συνθήκη του Καρς το 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Κατάληψη του Ιγδίρ — προέλαση στην κοιλάδα του Αράξη", "87ebf4d3"], "d": ["Στο πλαίσιο της επιχείρησης προέλασης που ξεκίνησε τον Φεβρουάριο του 1918, οι τουρκικές μονάδες νίκησαν αρμενικές μονάδες στο Σερντεραμπάντ (Serderabad), βόρεια του Αράξη, και κατέλαβαν το Ιγδίρ στις 20 Μαΐου 1918. Το Ιγδίρ δεν ανήκε στο Elviye-i Selâse αλλά ήταν ο καζάς Sürmeli της γκουμπερνίας του Ερεβάν· για πρώτη φορά μετά από περίπου 180 χρόνια εγκαθιδρύθηκε οθωμανική διοίκηση στην περιοχή.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Θάνατος του Μεχμέτ Ρεσάτ Ε' και ανάρρηση του Μεχμέτ Βαχντεντίν Στ'", "d302ba07"], "d": ["Ο Μεχμέτ Ρεσάτ Ε', του οποίου η εννιάχρονη βασιλεία πέρασε με τους πολέμους της Λιβύης, των Βαλκανίων και τον Παγκόσμιο Πόλεμο, πέθανε στην πιο κρίσιμη περίοδο του πολέμου και στη θέση του ανέβηκε στον θρόνο ο αδελφός του Βαχντεντίν με το όνομα Μεχμέτ Στ'. Ο νέος σουλτάνος προσπάθησε να ελευθερωθεί από την κηδεμονία του ιττιχατικού επιτελείου· τέσσερις μήνες αργότερα, όταν υπογράφηκε η ανακωχή, θα αναγκαζόταν να διαχειριστεί τη διάλυση της αυτοκρατορίας. Ήταν ο τριακοστός έκτος και τελευταίος σουλτάνος της οθωμανικής δυναστείας.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Άφιξη του στόλου της Αντάντ μπροστά στην Κωνσταντινούπολη και de facto κατοχή της πόλης", "d10cb14d"], "d": ["Μετά την Ανακωχή του Μούδρου, ο συμμαχικός στόλος, που αποτελούνταν από περισσότερα από εξήντα βρετανικά, γαλλικά, ιταλικά και ελληνικά πλοία, ναυλόχησε μπροστά στο Ντολμάμπαχτσε και η Κωνσταντινούπολη τέθηκε de facto υπό κατοχή. Μετά από τετρακόσια εξήντα πέντε χρόνια η πρωτεύουσα πέρασε για πρώτη φορά στον έλεγχο ξένων στρατιωτών. Η φράση «Όπως ήρθαν, έτσι θα φύγουν», που κατά την παράδοση είπε την ίδια μέρα ο Μουσταφά Κεμάλ Πασάς, όταν κατέβηκε στο Χαϊδάρπασα και αντίκρισε το θέαμα, θα γινόταν μία από τις συμβολικές φράσεις του Εθνικού Αγώνα.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Υποχώρηση στην περιοχή του Αράξη: εκκένωση του Ιγδίρ", "57572ab4"], "d": ["Σύμφωνα με τη διάταξη της Ανακωχής του Μούδρου για υποχώρηση πίσω από τα σύνορα του 1914, ο Γιακούπ Σεβκί Πασάς με την εντολή (emirname) της 21ης Νοεμβρίου διέταξε να αποσυρθούν έως τις 4 Δεκεμβρίου οι μονάδες που βρίσκονταν εκτός των συνόρων του Μπρεστ-Λιτόφσκ· το Ιγδίρ και η γύρω περιοχή εκκενώθηκαν εντελώς την ημερομηνία αυτή. Ακολούθως η Τουρκική Κυβέρνηση του Αράξη (Aras-Türk Hükûmeti) ανατράπηκε από τους Αρμενίους στα τέλη Δεκεμβρίου 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Οι Βρετανοί εγκαταστάθηκαν στο Αρτβίν", "e2cb3153"], "d": ["Επειδή η Ανακωχή του Μούδρου της 30ής Οκτωβρίου 1918 όριζε την υποχώρηση του οθωμανικού στρατού πίσω από τα σύνορα του 1914, το Αρτβίν εκκενώθηκε και καταλήφθηκε από τους Βρετανούς στις 17 Δεκεμβρίου 1918. Σύμφωνα με το λήμμα Artvin του TDV, η βρετανική κατοχή διήρκεσε έως τον Απρίλιο του 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Βρετανική διοίκηση στο Μπατούμ μετά το Μούδρο", "9dd768fc"], "d": ["Σύμφωνα με την Ανακωχή του Μούδρου της 30ής Οκτωβρίου 1918 το Οθωμανικό Κράτος αναγκάστηκε να αποχωρήσει από το Μπατούμ· η πόλη καταλήφθηκε από βρετανικές μονάδες στις 24 Δεκεμβρίου 1918. Το Μπατούμ, που τον Απρίλιο του 1918 έγινε αυτόνομο κέντρο σαντζακιού, από αυτή την ημερομηνία έως τον Ιούλιο του 1920 παρέμεινε υπό βρετανικό έλεγχο.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Το Αρντάχαν πέρασε στη γεωργιανή κυριαρχία", "97cf47f6"], "d": ["Το Αρντάχαν, που εκκενώθηκε μετά το Μούδρο, καταλήφθηκε στις 20 Απριλίου 1919 από γεωργιανές δυνάμεις, τις ημέρες που η Κυβέρνηση του Νοτιοδυτικού Καυκάσου (Cenûb-ı Garbî Kafkas Hükûmeti) διαλύθηκε από τους Βρετανούς. Η γεωργιανή κυριαρχία επρόκειτο να διαρκέσει έως τις 23 Φεβρουαρίου 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Ο Πρέστον παρέδωσε τη διοίκηση του Καρς στον Αρμένιο βαλή", "efa81cb0"], "d": ["Ο Βρετανός διοικητής Πρέστον (Preston), που διέλυσε την Κυβέρνηση του Νοτιοδυτικού Καυκάσου στις 12-13 Απριλίου 1919, κατήργησε στις 30 Απριλίου 1919 την προσωρινή κυβέρνηση συμβουλίου και μεταβίβασε τη διοίκηση της πόλης στον Αρμένιο Karganof, που έγινε βαλής του Καρς· στο Καρς ξεκίνησε η περίοδος της αρμενικής διοίκησης και διήρκεσε έως τη νίκη του Καζίμ Καραμπεκίρ στις 30 Οκτωβρίου 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Συνέδριο του Ερζερούμ: απόφαση εθνικής αντίστασης των ανατολικών βιλαετιών", "41ef0457"], "d": ["Το συνέδριο που συγκάλεσε η Εταιρεία Υπεράσπισης Δικαιωμάτων της Ανατολικής Ανατολίας (Şarkî Anadolu Müdafaa-i Hukuk Cemiyeti), αφού αναβλήθηκε λόγω βρετανικής πίεσης, άνοιξε με πενήντα έξι αντιπροσώπους και πρόεδρός του εξελέγη ο Μουσταφά Κεμάλ Πασάς, ο οποίος είχε παραιτηθεί από τον στρατό. Το συνέδριο διακήρυξε ότι εντός των εθνικών συνόρων η πατρίδα είναι ενιαία, ότι δεν μπορεί να γίνει αποδεκτή εντολή (manda) ή προστασία και ότι σε περίπτωση διάλυσης της κυβέρνησης το έθνος θα πάρει στα χέρια του τη μοίρα του. Οι αποφάσεις αυτές έξι μήνες αργότερα θα αποτελούσαν τον πυρήνα του κειμένου του Εθνικού Συμφώνου (Misâk-ı Millî).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Συνέδριο της Σεβάστειας (Sivas): ένωση της εθνικής αντίστασης κάτω από μία στέγη", "0e9ad36b"], "d": ["Το συνέδριο που ξεκίνησε τις εργασίες του στις 4 Σεπτεμβρίου 1919 στο Λύκειο Sivas Sultânîsi ένωσε τις εταιρείες υπεράσπισης δικαιωμάτων από όλες τις γωνιές της χώρας κάτω από το όνομα Εταιρεία Υπεράσπισης Δικαιωμάτων της Ανατολίας και της Ρούμελης και εξέλεξε μια Αντιπροσωπευτική Επιτροπή (Heyet-i Temsîliyye). Η πρόταση για αμερικανική εντολή απορρίφθηκε έπειτα από μακρές συζητήσεις. Με τη διακήρυξη που δημοσιεύθηκε στις 11 Σεπτεμβρίου, ο Εθνικός Αγώνας έγινε ένα νόμιμο πολιτικό κίνημα με ενιαίο κέντρο και ξεκίνησε ανοιχτός αγώνας ισχύος με την κυβέρνηση της Κωνσταντινούπολης.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Πρωτόκολλο της Αμάσειας: συνάντηση της κυβέρνησης της Κωνσταντινούπολης με την Αντιπροσωπευτική Επιτροπή", "40e6a6ab"], "d": ["Μετά την πτώση του Νταμάτ Φερίτ και τη σύσταση της κυβέρνησης του Αλή Ριζά Πασά, ο Υπουργός Ναυτικών Σαλίχ Πασάς στάλθηκε στην Αμάσεια για να συναντηθεί με την Αντιπροσωπευτική Επιτροπή. Με τα πρωτόκολλα που συμφωνήθηκαν, η κυβέρνηση της Κωνσταντινούπολης αναγνώρισε de facto την ύπαρξη του κινήματος της Ανατολίας· συμφωνήθηκε η σύγκληση της Meclis-i Meb'ûsan, η διεξαγωγή ελεύθερων εκλογών και η προστασία των εθνικών συνόρων. Αυτό είναι το πρώτο επίσημο πολιτικό κέρδος του Εθνικού Αγώνα έναντι της Κωνσταντινούπολης.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Αποδοχή του Εθνικού Συμφώνου (Misâk-ı Millî) στην τελευταία Οθωμανική Βουλή", "6322865e"], "d": ["Το κείμενο του Ahd-i Millî, που υπέγραψαν 121 βουλευτές στην τελευταία οθωμανική Meclis-i Meb'ûsan, όριζε την αδιαίρετη ακεραιότητα των εδαφών που έμεναν εντός της γραμμής του Μούδρου και στα οποία ζούσε μουσουλμανική-τουρκική πλειοψηφία, δημοψήφισμα στα αραβικά βιλαέτια και στη Δυτική Θράκη, την κατάργηση των Capitulations και την πλήρη πολιτική και οικονομική ανεξαρτησία. Το κείμενο εγκρίθηκε ομόφωνα στις 17 Φεβρουαρίου 1920 και ανακοινώθηκε στον κόσμο. Η διακήρυξη αυτή ήταν τόσο το πολιτικό πρόγραμμα του Εθνικού Αγώνα όσο και ο χάρτης των συνόρων που θα υπερασπίζονταν στη Λωζάνη· υπήρξε η άμεση αιτία για την επίσημη κατοχή της Κωνσταντινούπολης από τις δυνάμεις της Αντάντ στις 16 Μαρτίου.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Καθώς οι Βρετανοί αποχωρούσαν, το Αρτβίν έμεινε στη Γεωργία", "6d086b06"], "d": ["Σύμφωνα με το λήμμα Artvin του TDV, η βρετανική κατοχή διήρκεσε έως τον Απρίλιο του 1920· αποχωρώντας οι Βρετανοί άφησαν την πόλη στη Γεωργία. Το Αρτβίν παρέμεινε στα χέρια της Γεωργίας έως το τελεσίγραφο της 23ης Φεβρουαρίου 1921 της ΜΕΤΕ (TBMM).", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Το Μπατούμ παραδόθηκε στη γεωργιανή διοίκηση", "6523d095"], "d": ["Η επίσημη παράδοση του Μπατούμ από τους Βρετανούς στους Γεωργιανούς πραγματοποιήθηκε στις 7 Ιουλίου 1920 (το λήμμα Batum του TDV γράφει μόνο «Ιούλιος 1920»). Η κυβέρνηση της Άγκυρας στις 25 Ιουλίου διαμαρτυρήθηκε για την παράδοση ως «κατοχή».", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Συνθήκη του Γκιουμρί (Gümrü): η πρώτη διεθνής συνθήκη της κυβέρνησης της ΜΕΤΕ (TBMM)", "9232c690"], "d": ["Όταν ο στρατός του Ανατολικού μετώπου υπό τη διοίκηση του Καζίμ Καραμπεκίρ ανέκτησε το Σαρίκαμις και το Καρς, η Αρμενία ζήτησε ειρήνη και με τη συνθήκη που υπογράφηκε στο Γκιουμρί αποδέχθηκε ότι δεν αναγνωρίζει τη Συνθήκη των Σεβρών και εγκατέλειψε τις εδαφικές διεκδικήσεις της στα ανατολικά. Η πρώτη αυτή συνθήκη που υπέγραψε η κυβέρνηση της Άγκυρας ήταν το πρώτο διεθνές έγγραφο που απέρριπτε de facto τη Συνθήκη των Σεβρών και άνοιξε τον δρόμο της νομικής αναγνώρισης για τη Μεγάλη Εθνοσυνέλευση της Τουρκίας (TBMM). Έτσι, με την εξασφάλιση των ανατολικών συνόρων κατέστη δυνατή η μετακίνηση δυνάμεων προς το Δυτικό μέτωπο.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Πρώτη Μάχη του Ινονού (İnönü): η πρώτη νίκη του τακτικού στρατού", "4add3719"], "d": ["Ο νεοσύστατος τακτικός στρατός σταμάτησε στις θέσεις του Ινονού τις ελληνικές δυνάμεις που προέλαυναν από την κατεύθυνση της Προύσας και τις ανάγκασε να υποχωρήσουν. Η επιτυχία αυτή, αν και περιορισμένης κλίμακας από στρατιωτική άποψη, ήταν πολύ μεγάλη ως προς τα πολιτικά της αποτελέσματα: η κυβέρνηση της Άγκυρας προσκλήθηκε στη Διάσκεψη του Λονδίνου, άνοιξε ο δρόμος για τη Συνθήκη της Μόσχας με τη Σοβιετική Ρωσία και εγκρίθηκε ο Νόμος Teşkilât-ı Esâsiyye (Θεμελιώδης Νόμος). Και η εμπιστοσύνη της εσωτερικής κοινής γνώμης προς τον τακτικό στρατό ενισχύθηκε με αυτή τη νίκη.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Δεύτερη Μάχη του Ινονού: δεύτερη αναχαίτιση της ελληνικής επίθεσης", "a974521c"], "d": ["Ο ελληνικός στρατός, που δεν πέτυχε αποτέλεσμα στη Διάσκεψη του Λονδίνου, ξεκίνησε νέα επίθεση από τις κατευθύνσεις της Προύσας και του Ουσάκ, ωστόσο σταμάτησε και πάλι στους λόφους του Ινονού και αναγκάστηκε να υποχωρήσει. Το τηλεγράφημα που έστειλε ο Μουσταφά Κεμάλ Πασάς στον Ισμέτ Πασά «Εσείς εκεί δεν νικήσατε μόνο τον εχθρό, αλλά και τη κακή μοίρα του έθνους» γράφτηκε μετά από αυτή τη νίκη. Η μάχη ανύψωσε το διεθνές γόητρο του Εθνικού Αγώνα και επιτάχυνε τη διαδικασία αποχώρησης της Ιταλίας από την Ανατολία.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Συμφωνία της Άγκυρας (Ankara İtilâfnâmesi): ειρήνη με τη Γαλλία και κλείσιμο του νότιου μετώπου", "35fc32db"], "d": ["Με τη συμφωνία (itilâfnâme) που υπογράφηκε με τη Γαλλία στην Άγκυρα μετά τη νίκη στον Σαγγάριο έληξε ο πόλεμος στο νότιο μέτωπο· οι γαλλικές δυνάμεις εκκένωσαν την Κιλικία (Çukurova) και τα νοτιοανατολικά, συμπεριλαμβανομένων των Άδανα, Αντιντάμπ (Antep), Μαράς και Ουρφά, και αποσύρθηκαν στα σύνορα της Συρίας. Έτσι ένα από τα κράτη της Αντάντ αναγνώρισε de facto την κυβέρνηση της Άγκυρας και άνοιξε η πρώτη ρωγμή στο μέτωπο των Σεβρών. Τα όπλα που παραλήφθηκαν από τις εκκενωθείσες περιοχές και οι μονάδες που ελευθερώθηκαν έπαιξαν κρίσιμο ρόλο στην προετοιμασία της Μεγάλης Επίθεσης.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Ανακωχή των Μουδανιών: παράδοση της Κωνσταντινούπολης και των Στενών χωρίς πόλεμο", "ac0d9baf"], "d": ["Όταν μετά τη Μεγάλη Επίθεση ο τουρκικός στρατός βρέθηκε αντιμέτωπος με τις βρετανικές δυνάμεις στα Δαρδανέλια και στη Νικομήδεια, η διάσκεψη που συγκλήθηκε στα Μουδανιά κατέληξε σε ανακωχή μετά από έντεκα ημέρες σκληρών διαπραγματεύσεων. Συμφωνήθηκε η εκκένωση της Ανατολικής Θράκης έως τον Έβρο από την Ελλάδα μέσα σε δεκαπέντε ημέρες και η παράδοσή της στην τουρκική διοίκηση, και η παράδοση της Κωνσταντινούπολης και των Στενών με συνθήκη ειρήνης. Έτσι η ένοπλη φάση του Εθνικού Αγώνα έκλεισε με μια διπλωματική νίκη που κερδήθηκε χωρίς να ριχτεί ούτε μία σφαίρα και άνοιξε η πόρτα για τη Λωζάνη.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Αναχώρηση του Μεχμέτ Βαχντεντίν Στ' από την Κωνσταντινούπολη και εκλογή του Αμπντούλ Μετζίτ Εφέντη ως χαλίφη", "8ab0e847"], "d": ["Ο Μεχμέτ Βαχντεντίν Στ', ο τελευταίος σουλτάνος, του οποίου η θέση έγινε αμφιλεγόμενη μετά την κατάργηση του σουλτανάτου, αναχώρησε από την Κωνσταντινούπολη το πρωί της Παρασκευής 17 Νοεμβρίου 1922 με το βρετανικό θωρηκτό Malaya και πήγε στη Μάλτα. Η ΜΕΤΕ (TBMM) δύο ημέρες αργότερα, στις 19 Νοεμβρίου, εξέλεξε τον Αμπντούλ Μετζίτ Εφέντη ως χαλίφη χωρίς πολιτική εξουσία. Έτσι έληξε de facto η εξακοσίων είκοσι τριών ετών βασιλεία της οθωμανικής δυναστείας· το χαλιφάτο θα συνεχιζόταν συμβολικά για άλλους δεκαπέντε μήνες. Ο Βαχντεντίν, που πέρασε στη Μάλτα και έπειτα στην Ιταλία, εγκαταστάθηκε στη Villa Nobel στο Σαν Ρέμο· δεν πέτυχε αποτέλεσμα από τις αιτήσεις που έκανε για να γίνει δεκτός σε μια μουσουλμανική χώρα και πέθανε εκεί στις 16 Μαΐου 1926, επαναλαμβάνοντας ότι δεν είχε παραιτηθεί ποτέ από τα δικαιώματά του στο σουλτανάτο και στο χαλιφάτο.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Θάνατος του τελευταίου σουλτάνου Μεχμέτ Βαχντεντίν Στ' στο Σαν Ρέμο", "7149ed0e"], "d": ["Ο Μεχμέτ Βαχντεντίν, ο τελευταίος οθωμανός σουλτάνος, που εγκαταστάθηκε στην ιταλική πόλη Σαν Ρέμο μετά την αναχώρησή του από την Κωνσταντινούπολη, πέθανε στις 16 Μαΐου 1926 χωρίς να μάθει ότι συνήλθε το συνέδριο του χαλιφάτου (13 Μαΐου 1926), στο οποίο δήλωσε ότι δεν είχε παραιτηθεί ποτέ από τα δικαιώματά του στο σουλτανάτο και το χαλιφάτο. Βρισκόταν σε μεγάλη οικονομική στενότητα· χρωστούσε 60.000 λίρες στους εμπόρους του Σαν Ρέμο και οι πιστωτές, μαθαίνοντας τον θάνατό του, έβαλαν κατάσχεση στα έπιπλα του σπιτιού του.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Η κατάκτηση της περιοχής του Μπολού από τον Κονουραλπ — Μουντουρνού, Κονουράπα και Μπολού", "e245cd27"], "d": ["Ο Κονουραλπ, ένας από τους διοικητές του Ορχάν Γαζή, στράφηκε προς την ορεινή περιοχή ανατολικά του Σαγγάριου και υπήγαγε την περιοχή του Μουντουρνού, της Κονουράπα και του Μπολού στην οθωμανική διοίκηση· η κωμόπολη στην πεδιάδα του Ντούζτζε ονομάστηκε από το όνομά του. Η ακριβής ημερομηνία της κατάκτησης δεν είναι γνωστή· η διήγηση στηρίζεται στην παράδοση του Aşıkpaşazâde. Η περιοχή ήταν τότε μια παραμεθόρια ζώνη που άλλαζε χέρια ανάμεσα στους Τζανδαρογλου και το Βυζάντιο· η κατάκτηση έφερε για πρώτη φορά τους Οθωμανούς κοντά στη δυτική ακτή της Μαύρης Θάλασσας. Μετά τη Μάχη της Άγκυρας η περιοχή επρόκειτο να περάσει ξανά στους Τζανδαρογλου, αλλά επί Μωάμεθ του Πορθητή θα ανακτηθεί οριστικά.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Η κατάληψη των βυζαντινών κωμοπόλεων νότια της Προποντίδας — Μιχαλίτσι, Κιρμαστί, Γκιόλγιαζι", "9c61b8d4"], "d": ["Μετά την κατάληψη της Νίκαιας και της Νικομήδειας, οι κωμοπόλεις που παρέμεναν στα χέρια του Βυζαντίου δυτικά της πεδιάδας της Προύσας πέρασαν η μία μετά την άλλη στην οθωμανική διοίκηση. Το Γκιόλγιαζι γύρω από τη λίμνη Ουλουαμπάτ, το Κιρμαστί στις όχθες του ποταμού Σουσουρλούκ και το Μιχαλίτσι ολοκλήρωσαν τον διάδρομο που συνέδεε τη νότια ακτή της Προποντίδας με τα εδάφη του Καρεσί. Οι κωμοπόλεις αυτές παραδόθηκαν για πολύ καιρό χωρίς πολιορκία, με την αποκοπή του περίγυρού τους· η βυζαντινή παρουσία στην περιοχή περιορίστηκε έτσι στον κόλπο της Μουδανιών (Γκεμλίκ).", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Το Γκόρντους (Κόρινθος) πέρασε στον Δεσποτάτο του Μοριά", "392495eb"], "d": ["Η Κόρινθος, που από το 1358 ήταν τιμάριο της φλωρεντινής οικογένειας Acciajuoli, εξαρτώμενο από το πριγκιπάτο της Αχαΐας, το 1395 πέρασε στα χέρια του Θεόδωρου, του βυζαντινού δεσπότη του Μοριά. Από εκεί και πέρα η πόλη παρέμεινε στη διοίκηση του δεσποτάτου έως την οθωμανική κατάκτηση.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Η προσάρτηση του Εμιράτου των Χατζιεμιρογλου — Ορντού και Ουνιέ", "c064f07f"], "d": ["Το τουρκμενικό εμιράτο που ίδρυσε ο Μπαϊράμ Μπέης γύρω από το Ορντού και επεκτάθηκε τη δεκαετία του 1350 από τον γιο του Χατζή Εμίρ ήταν ένα μικρό αλλά στρατηγικό παράκτιο κράτος με έδρα το σημερινό Εσκιπαζάρ: ήταν η μόνη ανεξάρτητη κυριαρχία ανάμεσα στη Σαμψούντα και την Τραπεζούντα. Ο Εμίρ Σουλεϊμάν το 1398, στην επιχείρηση του Γιλντιρίμ Βαγιαζήτ στο Τζανίκ, δήλωσε υποταγή· μετά τη Μάχη της Άγκυρας το εμιράτο είχε ξαναγίνει ελεύθερο. Επί Μουράτ Β΄, τα ίδια χρόνια με τη διάλυση των Τατζεντινογλου, τα εδάφη του εμιράτου υπήχθησαν απευθείας στην οθωμανική διοίκηση και η ακτή της Μαύρης Θάλασσας από τη Σαμψούντα έως την Κερασούντα ενώθηκε σε ένα χέρι.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Η κατάκτηση του Γκόρντους (Κόρινθος)", "87a2bc59"], "d": ["Στην εκστρατεία του Πορθητή στον Μοριά το κάστρο του Ακροκορίνθου πολιορκήθηκε τρεις μήνες και τελικά παραδόθηκε ειρηνικά. Ο ισθμός της Κορίνθου, που θεωρούνταν η πύλη του Μοριά, πέρασε έτσι στους Οθωμανούς.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Η υπαγωγή του Μαυροβουνίου στην οθωμανική διοίκηση — Τσέτινιε", "7fdb7cc8"], "d": ["Όταν η δυναστεία των Τσέρνογιεβιτς, που κυβερνούσε τη Ζέτα, εγκατέλειψε την κυριαρχία το 1496, η ορεινή περιοχή του Μαυροβουνίου, που ήταν το πίσω μέρος της Σκόδρας, τέθηκε απευθείας υπό οθωμανική διοίκηση και οργανώθηκε πρώτα ως ξεχωριστό σαντζάκι και έπειτα ως τμήμα του σαντζακίου της Σκόδρας. Το μοναστήρι του Τσέτινιε παρέμεινε στη θέση του ως θρησκευτικό κέντρο της περιοχής. Λόγω της δυσκολίας του εδάφους η διοίκηση εδώ δεν λειτούργησε ποτέ τόσο αυστηρά όσο στις πεδιάδες· δύο αιώνες αργότερα η διοίκηση των βλαδικών, που προήλθε από το ίδιο μοναστήρι, θα γινόταν ο πυρήνας της de facto ανεξαρτησίας.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Η αποδοχή της οθωμανικής κυριαρχίας από το Κάστρο του Βαγιαζήτ κατά την Εκστρατεία του Ιράκ-ι Αρακέυν", "f29e2e17"], "d": ["Όταν ο μέγας βεζίρης Ιμπραήμ Πασάς έφτασε στην περιοχή του Μπιγκιόλ στην Εκστρατεία του Ιράκ-ι Αρακέυν, μαζί με πολλές κουρδικές φυλές της περιοχής συμφώνησαν να υπαχθούν στην οθωμανική κυριαρχία τα κάστρα του Βαν, του Τοπράκκαλε, του Αβνίκ και του Βαγιαζήτ. Ο Βαγιαζήτ είχε προσχωρήσει στους Οθωμανούς στην εκστρατεία του Γιαβούζ το 1514, αλλά όταν ο στρατός επέστρεψε οι Σαφαβίδες είχαν ανακτήσει την περιοχή.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Η νέα μετάβαση της Ταυρίδας (Τεμπρίζ) στους Σαφαβίδες — η επιστροφή από το Ιράκ-ι Αρακέυν", "80b8b761"], "d": ["Στην Εκστρατεία του Ιράκ-ι Αρακέυν ο στρατός μπήκε στην Ταυρίδα, αλλά επειδή ο κύριος στόχος ήταν η Βαγδάτη δεν αφέθηκε μόνιμη φρουρά στην πόλη. Καθώς ο στρατός που πέρασε τον χειμώνα στη Βαγδάτη επέστρεφε προς τα δυτικά, ο Σάχης Ταχμάσπ μπήκε ξανά στο εκκενωμένο Αζερμπαϊτζάν και ανακατέλαβε την Ταυρίδα. Αυτό ήταν το επαναλαμβανόμενο μοτίβο των οθωμανοσαφαβιδικών πολέμων: η Ταυρίδα καταλήφθηκε πέντε φορές και τις πέντε δεν μπόρεσε να κρατηθεί· η πόλη θα αποκτούσε μακροχρόνια οθωμανική φρουρά μόνο το 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Η πτώση του Βαν και του Ερτσίς στα χέρια του Ταχμάσπ (η οθωμανική στάση έληξε το 1534-35)", "cb93d561"], "d": ["Στην περιοχή που είχε υποταχθεί στην οθωμανική κυριαρχία το 1534, ο Ουλαμά Πασάς άντεξε στο Κάστρο του Βαν την πολιορκία των Σαφαβιδών· το κάστρο πέρασε στα χέρια των Σαφαβιδών, ενώ οι σαφαβιδικές δυνάμεις που πολιορκούσαν το Ερτσίς είχαν υποχωρήσει με οθωμανική βοήθεια. Όταν ο Σουλεϊμάν ο Μεγαλοπρεπής έφτασε στο Αχλάτ (23 Σεπτεμβρίου 1535), το Βαν βρισκόταν πλέον στα χέρια του Ταχμάσπ. Το Βαν παρέμεινε σαφαβιδικό μέχρι το 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Η μετάβαση του σαντζακίου του Βαγιαζήτ στη σαφαβιδική κυριαρχία (το Βαν και το Ερτσίς ήταν ήδη σαφαβιδικά από το 1535)", "806a2cf1"], "d": ["Το σαντζάκι του Βαγιαζήτ, στο μέσο των οθωμανοσαφαβιδικών συνόρων, πέρασε ξανά στα χέρια της Περσίας (ο Kaya 2017 το αναφέρει «μαζί με το Βαν και το Ερτσίς»· όμως το Βαν και το Ερτσίς, σύμφωνα με τον Karataş 2025 και το TDV, είχαν επιστρέψει στους Σαφαβίδες στις 22 Σεπτεμβρίου 1535 — βλ. προηγούμενο λήμμα)· σε αυτή την αλλαγή χεριών ορισμένα μέρη του σαντζακίου καταστράφηκαν. Το σαντζάκι άλλαξε χέρια επανειλημμένα ανάμεσα στα δύο κράτη μέχρι το τελευταίο τέταρτο του 16ου αιώνα.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Η νέα μετάβαση του σαντζακίου του Βαγιαζήτ στους Οθωμανούς κατά την Εκστρατεία του Ναχιτσεβάν", "cf0171fa"], "d": ["Κατά την τρίτη εκστρατεία του Σουλεϊμάν του Μεγαλοπρεπούς στην Περσία (Ναχιτσεβάν), το σαντζάκι του Βαγιαζήτ υπήχθη ξανά στην οθωμανική διοίκηση. Στην εκστρατεία του 1554 το Βαγιαζήτ έγινε σημαντική βάση για τον στρατό· το σαντζάκι πέρασε οριστικά στην οθωμανική κυριαρχία το 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Η απώλεια του Ερεβάν προς τον Σάχη Αμπάς", "34413cf2"], "d": ["Όταν, τα χρόνια που οι εξεγέρσεις των Τζελαλήδων κλείδωναν την Ανατολία, το ανατολικό μέτωπο έμεινε αφύλακτο, ο Σάχης Αμπάς, που είχε αναδιοργανώσει τον στρατό του με ευρωπαϊκό πρότυπο, πέρασε στην επίθεση. Το Κάστρο του Ερεβάν, που είχε χτίσει ο Φερχάτ Πασάς το 1583, παραδόθηκε μετά από πολιορκία επτά μηνών. Ο πρώτος κρίκος της γραμμής του Καυκάσου που είχε κερδηθεί με τη Συνθήκη του Φερχάτ Πασά είχε σπάσει· μέσα στα επόμενα τρία χρόνια ολόκληρος ο Νότιος Καύκασος επρόκειτο να χαθεί.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Η απώλεια της Τιφλίδας και της Γκιντζέ", "3fb51753"], "d": ["Μετά την πτώση του Ερεβάν, ο σαφαβιδικός στρατός προχώρησε κατά μήκος της κοιλάδας του Κουρ· η Γκιντζέ, το κέντρο του Καραμπάγκ, και η Τιφλίδα, η πρωτεύουσα της Γεωργίας, χάθηκαν η μία μετά την άλλη. Το Οθωμανικό Κράτος εκείνη τη στιγμή διεξήγε στο αυστριακό μέτωπο τον μακρύ πόλεμο των δεκατριών ετών και ήταν απασχολημένο με τους Τζελαλήδες στην Ανατολία· δεν υπήρχαν δυνάμεις να σταλούν στα ανατολικά. Έτσι η εκτεταμένη τάξη των επαρχιών του Καυκάσου, που είχε εγκαθιδρυθεί με τη Συνθήκη του Φερχάτ Πασά του 1590, έληξε de facto.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Η απώλεια του Σιρβάν — Σαμαχί, Μπακού και Ντερμπέντ", "81beab11"], "d": ["Η επαρχία του Σιρβάν στην ακτή της Κασπίας, που είχε κατακτηθεί με τις εκστρατείες του Οζντεμιρογλου Οσμάν Πασά το 1578-1585, είχε προσφέρει σημαντικά έσοδα στα οθωμανικά οικονομικά ως κύρια πηγή του εμπορίου μεταξιού. Η επιχείρηση του Σάχη Αμπάς προς τον βορρά κατέλαβε το ένα μετά το άλλο το Σαμαχί, το Μπακού και το Ντερμπέντ και διέλυσε την επαρχία αυτή. Η απώλεια δεν ήταν μόνο εδαφική: και ο δρόμος του περσικού μεταξιού προς την Ευρώπη μέσω των Οθωμανών βγήκε από τον έλεγχο, και το Σαφαβιδικό Κράτος άρχισε να διοχετεύει το μετάξι μέσω του Ινδικού Ωκεανού.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Η απώλεια της Ταΐζ", "65f20d53"], "d": ["Οι Οθωμανοί το 1038 (1629) εγκατέλειψαν την Ταΐζ μαζί με την κυριαρχία στην Υεμένη, που παραχωρήθηκε στη διοίκηση των Κασιμιτών της Σαναά — το πρώτο μεγάλο βήμα της διαδικασίας με την οποία οι ζαϊντίτες ιμάμηδες ανέκτησαν την εσωτερική Υεμένη.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Η απώλεια της Υεμένης — η κυριαρχία των ιμάμηδων Κασιμιτών", "49e83e3c"], "d": ["Η Υεμένη ήταν οθωμανική επαρχία από το 1538· όμως η αντίσταση των ζαϊντιτών ιμάμηδων δεν διακόπηκε ποτέ. Η εξέγερση που ξεκίνησε ο Ιμάμης Κασίμ εξαπλώθηκε σε ολόκληρη τη χώρα επί του γιου του ελ-Μουεγιγέντ Μουχαμμάντ και οι οθωμανικές φρουρές πολιορκήθηκαν η μία μετά την άλλη. Τα χρόνια που ο Μουράτ Δ΄ επικεντρωνόταν στη Βαγδάτη και στο Ερεβάν δεν μπόρεσαν να σταλούν ενισχύσεις· η Ταΐζ είχε χαθεί το 1629, ενώ η Μόκα είχε εκκενωθεί στις 22 Οκτωβρίου 1635, στην τελευταία φάση της ίδιας κατάρρευσης. Το 1635 και οι τελευταίες μονάδες στη Σαναά και στη Ζεμπίντ εκκένωσαν την Υεμένη. Έτσι η ανατολική ακτή της Ερυθράς Θάλασσας έμεινε εκτός της αυτοκρατορίας για διακόσια τριάντα επτά χρόνια και ανακτήθηκε μόλις το 1872. Το Λαχίτζ (ελ-Χάβτα), σύμφωνα με την Εγκυκλοπαίδεια Ισλάμ του TDV, ήταν στα χέρια των Οθωμανών έως το 1635· από εκείνη την ημερομηνία κυριάρχησαν οι ζαϊντίτες ιμάμηδες.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Η εκκένωση της Μόκα", "c6b3061a"], "d": ["Ο Μουσταφά Μπέης στις 10 Τζεμαζιελέββελ 1045 (22 Οκτωβρίου 1635) εκκένωσε τη Μόκα με τις δυνάμεις και τα όπλα που του απέμεναν· στη συνέχεια ο Χασάν μπιν Κασίμ, γιος του Ιμάμη Κασίμ, διόρισε δικούς του ανθρώπους στη Ζεμπίντ και στη Μόκα και εγκαθίδρυσε τον έλεγχο των Κασιμιτών και στην ακτή της Τιχάμα.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Η απώλεια της Λαχσά προς το Εμιράτο των Μπενί Χαλίντ", "a9b6131a"], "d": ["Η Λαχσά ήταν επαρχία που ιδρύθηκε το 1550 για να κλείσει τη δυτική ακτή του Κόλπου της Βασόρας στους Πορτογάλους· όμως βρισκόταν πολύ μακριά από την Κωνσταντινούπολη, στο άκρο ενός μοναδικού δρόμου της ερήμου. Τα χρόνια που η πολιορκία της Κρήτης εξάντλησε τους πόρους, η φυλή των Μπενί Χαλίντ της περιοχής, υπό την ηγεσία του Μπερράκ μπ. Γκουρέιρ, έδιωξε την οθωμανική φρουρά και ίδρυσε δικό της εμιράτο. Η δυτική ακτή του Κόλπου έμεινε επί ενάμισι αιώνα στα φυλετικά εμιράτα· το 1795 επρόκειτο να περάσει στους Σαουδίτες και το 1871 ξανά στους Οθωμανούς.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Η απώλεια της Πρέβεζας και της Βονίτσας προς τη Βενετία — το άνοιγμα της ακτής της Ηπείρου", "1201204c"], "d": ["Η Βενετία, που προσχώρησε στην Ιερά Συμμαχία, πριν ξεκινήσει την εκστρατεία του Μοριά κατέλαβε τα δύο κάστρα που ελέγχουν το στόμιο του Αμβρακικού κόλπου: την Πρέβεζα και απέναντι στην ακτή τη Βονίτσα. Το ίδιο καλοκαίρι είχε πέσει και η Αγία Μαύρα (Λευκάδα). Αυτές οι τρεις θέσεις επέτρεψαν στον στόλο να εισέλθει με ασφάλεια από το Ιόνιο Πέλαγος στο εσωτερικό της Ελλάδας και έγιναν η βάση της εκστρατείας του Μοριά που θα ξεκινούσε την επόμενη χρονιά. Η Πρέβεζα και η Βονίτσα αφέθηκαν στη Βενετία και στο Πασάροβιτς· στην οθωμανική διοίκηση θα επέστρεφαν μόλις το 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Η απώλεια του Σολνόκ — η διάλυση της γραμμής του Τίσα", "51c2c8ef"], "d": ["Μετά την πτώση του Νόυχοϊζελ τον Αύγουστο, ο Αψβουργικός στρατός στράφηκε νότια και κατέλαβε το Σολνόκ, προγεφύρωμα στον ποταμό Τίσα. Η πόλη ήταν το μοναδικό ασφαλές πέρασμα ανάμεσα στη Βούδα και στην Τρανσυλβανία· η απώλειά της σήμαινε ότι τα οθωμανικά κάστρα στο ανατολικό μισό της Ουγγαρίας αποκόπηκαν το ένα από το άλλο. Στην πολιορκία της Βούδας την επόμενη χρονιά αποφασιστικός υπήρξε ο διακοπείς δρόμος ανεφοδιασμού.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Η απώλεια της Μεθώνης προς τη Βενετία", "114c9cc0"], "d": ["Η Μεθώνη, στο νοτιοδυτικό άκρο της χερσονήσου του Μοριά, ήταν το λιμάνι που η Βενετία είχε χάσει τρεις αιώνες πριν και ονόμαζε «ένα από τα δύο μάτια του κράτους». Το κάστρο, που πολιορκήθηκε μετά την πτώση της Κορώνης, βομβαρδίστηκε ταυτόχρονα από ξηρά και θάλασσα και παραδόθηκε. Η εκστρατεία του Μοροζίνι στον Μοριά κατέλαβε έτσι ολόκληρη τη δυτική ακτή της χερσονήσου και άνοιξε ο δρόμος προς το εσωτερικό.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Η απώλεια του Πετσούι (Πέτς)", "99d54cf4"], "d": ["Μετά την πτώση της Βούδας τον Σεπτέμβριο, οι αψβουργικές δυνάμεις κατέβηκαν νότια δυτικά του Δούναβη και κατέλαβαν το Πετσούι, που ήταν οθωμανικό από την εποχή του Σουλεϊμάν του Μεγαλοπρεπούς. Η πόλη, γνωστή από το Τζαμί του Γαζή Κασίμ Πασά, ήταν από τα πιο ανεπτυγμένα κέντρα σαντζακίων της επαρχίας της Βούδας. Η απώλειά της σήμαινε το άνοιγμα του δρόμου που κατεβαίνει στην πεδιάδα του Μοχάτς· την επόμενη χρονιά η ήττα του Δεύτερου Μοχάτς θα συνέβαινε ακριβώς εκεί.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Η απώλεια του Σεγκέντ", "9fbee1b2"], "d": ["Το Σεγκέντ, στο σημείο συνάντησης των ποταμών Τίσα και Μάρος, ήταν η νότια πύλη της ουγγρικής πεδιάδας και ήλεγχε τον δρόμο προς την επαρχία του Τεμεσβάρ. Μετά την πτώση της Βούδας και του Πετσούι το ίδιο φθινόπωρο, το κάστρο που πολιορκήθηκε παραδόθηκε σύντομα. Η απώλεια τριών κάστρων μέσα σε μία εποχή ήταν σημάδι ότι η οθωμανική διοικητική δομή στην Ουγγαρία, που υπήρχε από το 1541, άρχιζε να καταρρέει. Ο άτλαντας θεωρεί ότι την ίδια ημέρα και η Ζέντα στις όχθες του Τίσα πέρασε από τους Οθωμανούς στην αψβουργική πλευρά (η ημέρα παράδοσης ειδική για τη Ζέντα δεν διαβάστηκε στην πηγή, η ημέρα πάρθηκε από το Σεγκέντ· TDV zenta: από τον Οκτώβριο του 1686 άρχισαν συγκρούσεις ανάμεσα στους Οθωμανούς και τους συμμάχους υπό την ηγεσία των Αψβούργων — δηλωμένη προσέγγιση).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Η απώλεια του Μπαλιαμπάντρα (Πάτρα) — η βόρεια πύλη του Μοριά", "b9cff63c"], "d": ["Το Μπαλιαμπάντρα, στο στόμιο του Κορινθιακού κόλπου, ήταν το λιμάνι που έλεγχε το πέρασμα ανάμεσα στον Μοριά και τη Ρούμελη. Αφού ο βενετικός στρατός κατέλαβε την πόλη, και τα κάστρα στις δύο όχθες του κόλπου έπεσαν το ένα μετά το άλλο και η χερσόνησος απομονώθηκε πλήρως από την ξηρά. Στο τέλος αυτής της επιχείρησης ολόκληρος ο Μοριάς πέρασε στη Βενετία· η περιοχή θα διοικούνταν έως το 1715 με την ονομασία «Regno di Morea».", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Η παραχώρηση του Γκόρντους (Κόρινθος) στη Βενετία", "9a25b6b9"], "d": ["Μετά την πτώση του Μπαλιαμπάντρα η Κόρινθος παραχωρήθηκε ειρηνικά στους Βενετούς και ο μουσουλμανικός πληθυσμός εγκατέλειψε την πόλη. Τον Αύγουστο του 1687 ο στρατός του Μοροζίνι συγκεντρωνόταν στην Κόρινθο για την εκστρατεία της Αθήνας.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Η απώλεια του Έγκρι (Ερλάου)", "983391aa"], "d": ["Το Έγκρι είχε καταληφθεί το 1596 με την εκστρατεία στην οποία συμμετείχε αυτοπροσώπως ο Μωάμεθ Γ΄ και είχε γίνει κέντρο επαρχίας με το δικό του όνομα. Αυτό το τελευταίο μεγάλο οθωμανικό κάστρο της βόρειας Ουγγαρίας, μετά την ήττα του Δεύτερου Μοχάτς, αντιστάθηκε έναν χρόνο περικυκλωμένο πλήρως και παραδόθηκε λόγω πείνας. Με την απώλειά του ο βόρειος κλάδος του Οθωμανικού Κράτους στην Ουγγαρία διαλύθηκε εντελώς.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Η απώλεια του Ιστολνί Μπελγκράντ (Σέκεσφεχερβάρ) — η πόλη στέψης των Ούγγρων βασιλέων", "c6147255"], "d": ["Η πόλη όπου επί αιώνες στέφονταν και θάβονταν οι Ούγγροι βασιλείς είχε καταληφθεί το 1543 από τον Σουλεϊμάν τον Μεγαλοπρεπή και είχε γίνει ένα από τα σημαντικότερα κέντρα σαντζακίων της επαρχίας της Βούδας. Περίπου δύο χρόνια μετά την πτώση της Βούδας, το κάστρο, που είχε αποκοπεί πλήρως από τον περίγυρό του, παραδόθηκε. Με αυτή την απώλεια η οθωμανική παρουσία δυτικά του Δούναβη περιορίστηκε στην περιοχή του Σιρμίου και του Οσιέκ.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Η απώλεια του Ζιγκετβάρ", "834910a7"], "d": ["Το Ζιγκετβάρ ήταν το κάστρο όπου ο Σουλεϊμάν ο Μεγαλοπρεπής πέθανε το 1566, εν μέσω της πολιορκίας, στη δέκατη τρίτη και τελευταία εκστρατεία του· γι' αυτό είχε συμβολική θέση στην οθωμανική μνήμη. Εκατόν είκοσι τρία χρόνια αργότερα, αφού έπεσαν όλα τα κάστρα γύρω του, παραδόθηκε και το κάστρο που προστατευόταν από έλη. Το μαυσωλείο όπου ήταν θαμμένα τα εντόσθια του Σουλεϊμάν και η γύρω κωμόπολη καταστράφηκαν αφού πέρασαν στην αψβουργική διοίκηση. Άλλος οικισμός που πέρασε την ίδια ημερομηνία στον άτλαντα από τους Οθωμανούς στους Αψβούργους: Barcs — ακολουθεί την αλυσίδα του αδελφού-κέντρου του Ζιγκετβάρ (Bánlaky 0017/1449· δηλωμένη προσέγγιση).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Η απώλεια του Βαράντ (Ορράδεα)", "6cce360d"], "d": ["Το Βαράντ ήταν το κομβικό κάστρο που άνοιγε προς την Τρανσυλβανία, που είχε καταληφθεί το 1660 από τον Κιοπρουλού Μεχμέτ Πασά και είχε γίνει κέντρο επαρχίας με το δικό του όνομα. Το κάστρο, που έμεινε εντελώς μόνο μετά την ήττα του Σαλανκεμέν, παραδόθηκε από πείνα έπειτα από αποκλεισμό σχεδόν δύο ετών. Με την απώλειά του η οθωμανική επιρροή στην Τρανσυλβανία έληξε de facto και η αψβουργική κυριαρχία εγκαταστάθηκε ανατολικά του Τίσα.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Η απώλεια της Γιάνοβα (Ινέου) — το κλείσιμο του δρόμου προς την Τρανσυλβανία", "4b5e30d8"], "d": ["Η Γιάνοβα ήταν κάστρο που είχε καταληφθεί το 1658 και κρατούσε τη σύνδεση ανάμεσα στο Βαράντ και στο Τεμεσβάρ. Όταν αμέσως μετά την πτώση του Βαράντ αποκόπηκε ο περίγυρός της, χάθηκε κι αυτή. Έτσι η επαρχία του Τεμεσβάρ απομονώθηκε πλήρως από τον βορρά και συνέχισε να υπάρχει ως το μοναδικό ουγγρικό έδαφος που έμεινε στα χέρια των Οθωμανών έως το Καρλόβιτς.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Η εγκαθίδρυση της διοίκησης των βλαδικών στο Μαυροβούνιο — η de facto απόσχιση του Τσέτινιε", "a924b778"], "d": ["Τα χρόνια που ο Πόλεμος της Ιεράς Συμμαχίας χαλάρωσε τον οθωμανικό έλεγχο στα Βαλκάνια, η μητρόπολη επικεφαλής του μοναστηριού του Τσέτινιε έγινε στην οικογένεια Πέτροβιτς αξίωμα που περνούσε από πατέρα σε γιο και η περιοχή απέκτησε de facto ξεχωριστή διοίκηση. Χάρη στην απρόσιτη φύση των βουνών, αυτή η βλαδικία διατηρήθηκε επί δύο αιώνες σε θέση ούτε πλήρως ανεξάρτητη ούτε πλήρως εξαρτημένη· η ανεξαρτησία της θα αναγνωριζόταν νομικά μόνο με τη Συνθήκη του Βερολίνου το 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Η ανάκτηση του Γκόρντους (Κόρινθος)", "26f53e3a"], "d": ["Ο πρώτος μεγάλος σταθμός της εκστρατείας του Μοριά του Νταμάτ Αλή Πασά ήταν η Κόρινθος· οι Οθωμανοί τον Ιούνιο του 1715 ανέκτησαν την πόλη από τους Βενετούς και από εκεί προχώρησαν στο υπόλοιπο της χερσονήσου.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Η επίθεση του Ναντίρ: απώλεια της Ταυρίδας (Τεμπρίζ), του Ναχιτσεβάν, του Χαμαδάν, του Κερμανσάχ, του Μεράγα και του Κασρ-ι Σιρίν", "d95efd59"], "d": ["Οι πόλεις της δυτικής Περσίας που είχαν καταληφθεί το 1723-1727 εκμεταλλευόμενες την κατάρρευση του κράτους των Σαφαβιδών χάθηκαν η μία μετά την άλλη με την επίθεση του Ναντίρ Χαν, ο οποίος είχε αναλάβει de facto την εξουσία στην Περσία. Στο Αζερμπαϊτζάν το Αρντεμπίλ και το Χαλχάλ πέρασαν επίσης στον Ναντίρ. Η απώλεια του Χαμαδάν, του Κερμανσάχ και του Κασρ-ι Σιρίν προκάλεσε βαθιά αίσθηση στην Κωνσταντινούπολη· το ότι ο στρατός δεν βγήκε σε εκστρατεία αλλά περίμενε στο Σκούταρι και το ότι έγινε προσπάθεια συγκάλυψης της απώλειας υπήρξαν από τις άμεσες αιτίες της εξέγερσης του Πατρόνα Χαλίλ, που ξέσπασε έξι εβδομάδες αργότερα. Ο άτλαντας θεωρεί ότι και το Κοτούρ, που ακολουθεί την αλυσίδα του Χόι, πέρασε αυτή την ημέρα από τους Οθωμανούς στους Σαφαβίδες (Uluerler 2015, Turkish Studies 10/5, σ. 6· ημέρα ειδική για το Κοτούρ δεν υπάρχει στην πηγή — δηλωμένη προσέγγιση).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Η ήττα του Μπαγκαβάρντ (Αρπαΐτσαϊ) — η απώλεια του Καυκάσου προς τον Ναντίρ Χαν", "4262f54c"], "d": ["Οι επαρχίες του Καυκάσου που είχαν καταληφθεί το 1723-1725 εκμεταλλευόμενες την κατάρρευση του Σαφαβιδικού Κράτους μπόρεσαν να κρατηθούν δέκα χρόνια. Ο Ναντίρ Χαν, που είχε αναλάβει de facto την εξουσία στην Περσία, επέφερε βαριά ήττα στον οθωμανικό στρατό στο Μπαγκαβάρντ κοντά στο Ερεβάν· ο σερασκέρης Αμπντουλλάχ Κιοπρουλού Πασάς έχασε τη ζωή του στο πεδίο της μάχης. Μετά την ήττα, το Ερεβάν, η Τιφλίδα, η Γκιντζέ και το Σιρβάν εκκενώθηκαν μέσα σε λίγους μήνες. Τα ανατολικά σύνορα επέστρεψαν στη γραμμή του Κασρ-ι Σιρίν του 1639, όπως θα επιβεβαιωνόταν το 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Η απώλεια του Μπεντέρ προς τους Ρώσους", "0daca453"], "d": ["Μετά την ήττα στην Πεδιάδα του Κάρταλ ο οθωμανικός στρατός είχε υποχωρήσει νότια του Δούναβη και τα κάστρα ανάμεσα στη Μολδαβία και το Οζί είχαν μείνει μόνα τους. Το Μπεντέρ, που κρατούσε το σημείο διάβασης του ποταμού Τούρλα, καταλήφθηκε με έφοδο έπειτα από πολιορκία δύο μηνών· η πόλη λεηλατήθηκε. Η απώλεια του κάστρου έσπασε τον μεσαίο κρίκο της αμυντικής γραμμής της βόρειας Μαύρης Θάλασσας· μετά έπεσαν και το Ακκερμάν και το Κίλια. Στο Κιουτσούκ Καϊναρτζά το Μπεντέρ επρόκειτο να επιστραφεί, αλλά να χαθεί ξανά το 1806.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Η υπαγωγή του εμιράτου των Σαμπάχ στο Κουβέιτ στην οθωμανική προστασία", "3584dba0"], "d": ["Σύμφωνα με το λήμμα Κουβέιτ του TDV, την προβλήτα ίδρυσε στις αρχές του 18ου αιώνα η φυλή των Ουτούμπ, που ήρθε από το Νεζντ, και η οικογένεια Σαμπάχ ανέλαβε τη διοίκηση προς τα τέλη του αιώνα. Τα ίδια χρόνια που η Λαχσά πέρασε στους Σαουδίτες, το εμιράτο, που απέναντι στην πίεση των Βαχαβιτών δεν είχε άλλη επιλογή από το να στηριχθεί στη Βασόρα, τέθηκε υπό οθωμανική προστασία. Ο δεσμός θα επισημοποιούνταν το 1871 με τη ρύθμιση της Βασόρας από τον Μιντχάτ Πασά και το Κουβέιτ θα θεωρούνταν ένα από τα τρία καζά του σαντζακίου της Βασόρας· και η μεταγενέστερη εδαφική αξίωση του Ιράκ στηρίζεται σε αυτή την καταγραφή.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Η απώλεια της Μέκκας προς τους Βαχαβίτες", "2da23acd"], "d": ["Το βαχαβιτικό κίνημα, που γεννήθηκε στο Νεζντ, στράφηκε προς το Χιτζάζ την εποχή του Σουούντ μπιν Αμπντουλαζίζ· μετά την Ταΐφ και τη Μεδίνα, και η Μέκκα παραδόθηκε για δεύτερη φορά — ο Εμίρης της Μέκκας Σερίφης Γκαλίμπ παρέδωσε την πόλη στους Βαχαβίτες με τον όρο να παραμείνει στο εμιράτο. Τα μαυσωλεία κατεδαφίστηκαν και ο δρόμος των καραβανιών των προσκυνητών από τη Δαμασκό και το Κάιρο αποκόπηκε· και το σουρρέ που ο σουλτάνος έστελνε κάθε χρόνο στα Χαραμέιν διακόπηκε αυτά τα χρόνια — μοναδική εξαίρεση αυτής της ακατάπαυστης έως το 1915 χορηγίας είναι η περίοδος της βαχαβιτικής κυριαρχίας. Επειδή η ιδιότητα του προστάτη των Χαραμέιν ήταν από τα βασικά στηρίγματα της νομιμοποίησης του σουλτάνου, η απώλεια αυτή αποτέλεσε, πέρα από εδαφική απώλεια, βαρύ πολιτικό πλήγμα· η ανάκτησή της θα διαρκούσε επτά χρόνια και θα ήταν δυνατή με τον στρατό του Καβαλιώτη Μεχμέτ Αλή Πασά.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Το τέλος της Δημοκρατίας του Δουβρόβνικ — η γαλλική κατοχή", "f8e27bf1"], "d": ["Οι Γάλλοι, που με τη Συνθήκη του Καμπο Φόρμιο (1797) εγκαταστάθηκαν στη δαλματική ακτή, στις 27 Μαΐου 1806 κατέλαβαν το Δουβρόβνικ και έβαλαν τέλος στη μικρή εμπορική δημοκρατία. Έτσι έληξε το τριάμισι αιώνων καθεστώς υποτέλειας του Δουβρόβνικ, που από το 1458 πλήρωνε φόρο στους Οθωμανούς και διατηρούσε την αυτονομία και τα εμπορικά προνόμιά του· η πόλη και το νησί Μλιέτ (Mljet) της δημοκρατίας περνούν στον χάρτη απευθείας στη γαλλική διοίκηση.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Η απώλεια του Σουχούμι προς τους Ρώσους — το άνοιγμα της ανατολικής ακτής της Μαύρης Θάλασσας", "adc96bd4"], "d": ["Στον οθωμανορωσικό πόλεμο του 1806-1812 ο ρωσικός στόλος στράφηκε προς την ανατολική ακτή της Μαύρης Θάλασσας και κατέλαβε το Σουχούμκαλε, στο οποίο στηριζόταν η οθωμανική κυριαρχία στην Αμπχαζία. Το κάστρο ήταν το κέντρο της σύνδεσης με τις φυλές του Καυκάσου και του παράκτιου εμπορίου. Με την απώλειά του η Ρωσία εγκαταστάθηκε για πρώτη φορά μόνιμα στην ανατολική ακτή της Μαύρης Θάλασσας· η οθωμανική επιρροή στον Καύκασο περιορίστηκε στην περιοχή της Ανάπας και του Πότι.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Η παράδοση της Πάργας στην οθωμανική διοίκηση", "66e0cc5d"], "d": ["Η Πάργα ήταν στα χέρια της Βενετίας από το 1401 και δεν είχε περάσει ποτέ στην οθωμανική διοίκηση· μετά την πτώση της Βενετίας πέρασε διαδοχικά στη Γαλλία και στην Αγγλία. Το λήμμα του TDV για τον Τεπεντελενλή Αλή Πασά συνοψίζει την κατάσταση ως εξής: η πόλη παραδόθηκε στους Άγγλους και παραχωρήθηκε στη διοίκηση του Αλή Πασά μόλις το 1819. Η παράδοση είχε ως αποτέλεσμα τη μετανάστευση του μεγαλύτερου μέρους του πληθυσμού στα Ιόνια Νησιά. Έτσι και ο τελευταίος της τριάδας Πρέβεζα-Πάργα-Βονίτσα, που είχε αφεθεί στη Βενετία στο Πασάροβιτς, προσαρτήθηκε στην αυτοκρατορία· η Πάργα επρόκειτο να παραμείνει οθωμανική ενενήντα τέσσερα χρόνια.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Η μετάβαση του Γκόρντους (Κόρινθος) στους Έλληνες επαναστάτες", "892dcdc6"], "d": ["Κατά τον ελληνικό πόλεμο της ανεξαρτησίας ο Ακροκόρινθος πέρασε στα χέρια των επαναστατών και ο διοικητής του κάστρου Καμίλ Μπέης αιχμαλωτίστηκε.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Η απώλεια του Αναπλίου (Ναύπλιο) προς τους επαναστάτες", "1a67fa50"], "d": ["Το Ανάπλι, το λιμάνι με τις ισχυρότερες οχυρώσεις του Μοριά, παραδόθηκε από πείνα έπειτα από αποκλεισμό που διήρκεσε περισσότερο από ένα έτος. Το κάστρο ήταν από την αρχή της επανάστασης το τελευταίο μεγάλο στήριγμα του οθωμανικού ελέγχου στη χερσόνησο· με την απώλειά του ολόκληρος ο Μοριάς πέρασε στα χέρια των επαναστατών. Η πόλη επρόκειτο λίγο αργότερα να γίνει η πρώτη πρωτεύουσα του νέου ελληνικού κράτους.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Η μετάβαση της Ναυπάκτου (Ινεμπαχτί) στην ελληνική διοίκηση", "c9d19d4b"], "d": ["Η Ναύπακτος (Ινεμπαχτί), στη βόρεια ακτή του Κορινθιακού κόλπου, που παρέμενε στα οθωμανικά χέρια μέχρι την ελληνική εξέγερση, χάθηκε τον Απρίλιο του 1829 και πέρασε στην ελληνική διοίκηση· το όνομα της κωμόπολης μετατράπηκε στο αρχαίο Ναύπακτος. Ο μουσουλμανικός και ο εβραϊκός πληθυσμός της πόλης εξαφανίστηκε εντελώς και η πόλη μετατράπηκε σε μικρή κωμόπολη.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Η γαλλική κατοχή του Αλγερίου — το τέλος της τριακοσιόχρονης Εστίας", "0be8f568"], "d": ["Με πρόσχημα το επεισόδιο του βεντάλιου, που προήλθε από διαφωνία για μια οφειλή, η Γαλλία κράτησε την ακτή του Αλγερίου υπό αποκλεισμό επί τρία χρόνια και έπειτα αποβίβασε στρατό στο Σιντί Φερρούχ. Στο τέλος μιας τρίστηβδομαδιαίας επιχείρησης ο Δεύτερος Χουσεΐν Ντέης παραδόθηκε και η Οθωμανική Εστία του Αλγερίου, που διαρκούσε από το 1516, έληξε. Η κατοχή δεν περιορίστηκε στην πρωτεύουσα· και το Τλεμσέν, το Σερσέλ και η Μεντέα στο εσωτερικό χάθηκαν το ίδιο καλοκαίρι. Η υπαγωγή ολόκληρης της ακτής στον γαλλικό έλεγχο επρόκειτο να διαρκέσει άλλα είκοσι τέσσερα χρόνια.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Η παραχώρηση της Εύβοιας (Έγριπος) στην Ελλάδα — μαζί με το νησί (Κάρυστος, Ωρεοί)", "7b524aa4"], "d": ["Η Εύβοια (Έγριπος), που υπήρξε σκηνή έντονων συγκρούσεων στον ελληνικό πόλεμο της ανεξαρτησίας αλλά παρέμεινε στα οθωμανικά χέρια, παραχωρήθηκε το 1831 στους Έλληνες μετά την έναρξη ισχύος της συνθήκης ειρήνης. Ο μουσουλμανικός πληθυσμός της πόλης, που από το 1470 ήταν σημαντική ναυτική βάση, πούλησε όλα του τα υπάρχοντα σε πολύ χαμηλές τιμές και μετανάστευσε μαζικά σε οθωμανικά εδάφη· η πόλη έμεινε για πολύ καιρό άδεια και ο Γερμανός περιηγητής Fallmerayer την χαρακτήρισε το 1842 ως πόλη-φάντασμα.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Η γαλλική κατοχή του Βεχράν (Οράν)", "a8415d66"], "d": ["Το Βεχράν, που η Ισπανία είχε παραδώσει το 1792 χωρίς πόλεμο, ήταν το μεγαλύτερο λιμάνι στα δυτικά του Αλγερίου. Έξι μήνες μετά την πτώση της πρωτεύουσας οι γαλλικές μονάδες μπήκαν στην πόλη. Η δυτική επιχείρηση που ξεκίνησε από εδώ επρόκειτο σύντομα να συναντήσει την αντίσταση του Εμίρη Αμπντελκαντέρ, που θα διαρκούσε δεκαπέντε χρόνια.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Η κατοχή της Ανναμπά (Μπον)", "21f37fb1"], "d": ["Η Ανναμπά, το λιμάνι του ανατολικού Αλγερίου κοντά στα σύνορα με την Τυνησία, καταλήφθηκε από γαλλικές δυνάμεις και έγινε βάση για την πορεία προς την Κωνσταντίνη. Η πόλη ήταν ταυτόχρονα το πλησιέστερο αφρικανικό λιμάνι απέναντι από το νησί της Σαρδηνίας.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Η παράδοση της Αθήνας στο νέο ελληνικό κράτος (η ημέρα που οι βαυαρικές μονάδες παρέλαβαν την Ακρόπολη)", "deee4d37"], "d": ["Η Αθήνα, οθωμανική από το 1456, είχε αλλάξει χέρια αρκετές φορές κατά τον ελληνικό αγώνα της ανεξαρτησίας και η φρουρά της Ακρόπολης είχε περάσει ξανά υπό οθωμανικό έλεγχο το 1827. Επειδή έμεινε βόρεια των συνόρων που χαράχτηκαν με το Πρωτόκολλο του Λονδίνου, η πόλη παραδόθηκε στο νέο βασίλειο και η φρουρά εκκένωσε την Ακρόπολη. Η ημέρα του άτλαντα είναι η ημέρα που οι βαυαρικές μονάδες παρέλαβαν την Ακρόπολη· η de facto αποχώρηση της οθωμανικής φρουράς έγινε λίγες ημέρες αργότερα (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, κεφ. 13· Finlay, Journals and Letters, τ. I, σ. 67). Την επόμενη χρονιά η Αθήνα ανακηρύχθηκε πρωτεύουσα της Ελλάδας στη θέση του Αναπλίου.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Η κατοχή της Μπιτζάγιε (Μπουζί)", "a8927e00"], "d": ["Το λιμάνι της Μπιτζάγιε, εκεί όπου τα όρη της Καμπυλίας ανοίγουν προς τη θάλασσα, ήταν ο τελευταίος ανεξάρτητος κρίκος της παράκτιας γραμμής ανάμεσα στο Αλγέρι και την Ανναμπά. Καταλήφθηκε με την υποστήριξη του ναυτικού πυροβολικού· όμως η ορεινή ενδοχώρα πίσω της δεν επρόκειτο να περάσει στον γαλλικό έλεγχο για άλλα τριάντα χρόνια. Αυτές οι κατοχές κατά μήκος της ακτής συνθέτουν τη συρρίκνωση του Οθωμανικού Αλγερίου στον χάρτη χρόνο με τον χρόνο.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Η κατοχή της Σετίφ", "2073731a"], "d": ["Μετά την πτώση της Κωνσταντίνης ένα χρόνο νωρίτερα, οι γαλλικές δυνάμεις ανέβηκαν στο οροπέδιο και κατέλαβαν την αρχαία ρωμαϊκή πόλη Σετίφ, ιδρύοντας εκεί μόνιμη φρουρά. Η Σετίφ ήταν το σημείο τομής των δρόμων των καραβανιών ανάμεσα στην ακτή και τη Σαχάρα· η κατοχή της έδειξε ότι η Γαλλία πλέον άρχισε να ελέγχει όχι μόνο τα λιμάνια αλλά και το εσωτερικό εμπορικό δίκτυο.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Η κατοχή της Μπισκρά — η απώλεια της πύλης της Σαχάρας", "d895cad0"], "d": ["Η Μπισκρά ήταν στους νότιους πρόποδες των βουνών του Άτλαντα η πύλη που ανοίγει προς τη Σαχάρα και το κέντρο των φοινικοειδών οάσεων. Με την κατάληψή της, τα χρόνια που η αντίσταση του Εμίρη Αμπντελκαντέρ άρχιζε να σπάει, ο γαλλικός έλεγχος έφτασε για πρώτη φορά στη βόρεια ακτή της ερήμου. Από εδώ και πέρα θα ήταν πλέον μια επιχείρηση της ερήμου που προχωρούσε οάση προς οάση.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Η κατοχή του Τουγκούρτ — η απώλεια ολόκληρου του Αλγερίου", "33c056e2"], "d": ["Με την κατάληψη του Τουγκούρτ, της πόλης-όασης στα βόρεια της Σαχάρας, η κατοχή που είχε ξεκινήσει το 1830 ολοκληρώθηκε στο βόρειο μισό του σημερινού Αλγερίου. Το Οθωμανικό Κράτος αυτά τα χρόνια πολεμούσε στον Κριμαϊκό Πόλεμο στην ίδια πλευρά με τη Γαλλία· αν και δεν παραιτήθηκε ποτέ επίσημα από τη νομική αξίωσή του επί του Αλγερίου, de facto δεν μπόρεσε να κάνει ούτε ένα βήμα. Το μοναδικό έδαφος που απέμενε στη Βόρεια Αφρική ήταν η Τρίπολη της Λιβύης (Τραπλουσγκάρπ).", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Η πτώση του Ουμπεΐντ — η μετάβαση του Κορντοφάν στις δυνάμεις του Μαχντί", "58299f62"], "d": ["Το κίνημα που ξεκίνησε ο Μουχαμμάντ Αχμάντ, ο οποίος ανακήρυξε τον εαυτό του μαχντί, εξαπλώθηκε γρήγορα εναντίον της αιγυπτιακής διοίκησης στο Σουδάν. Το Ουμπεΐντ, το κέντρο του Κορντοφάν, έπεσε μετά από πολιορκία τεσσάρων μηνών και έγινε η πρωτεύουσα της εξέγερσης· ο θησαυρός και οι αποθήκες όπλων της πόλης επέτρεψαν στο κίνημα να γίνει στρατός. Το Σουδάν ήταν νομικά ακόμη έδαφος του Χεδιβάτου της Αιγύπτου, που εξαρτιόταν από τους Οθωμανούς, επομένως η απώλεια στον χάρτη αφαιρείται από το σώμα της αυτοκρατορίας.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Η πτώση του Χαρτούμ — η απώλεια ολόκληρου του Σουδάν", "d4b98464"], "d": ["Έπειτα από πολιορκία δέκα μηνών οι δυνάμεις του Μαχντί μπήκαν στο Χαρτούμ, στο σημείο όπου συναντώνται ο Γαλάζιος και ο Λευκός Νείλος· ο κυβερνήτης της πόλης Γκόρντον σκοτώθηκε και η βρετανική φάλαγγα που στάλθηκε για βοήθεια άργησε δύο ημέρες. Από αυτή την ημερομηνία ολόκληρο το Σουδάν, συμπεριλαμβανομένων του Σενάρ, της Δόνγκολα και του Κορντοφάν, παρέμεινε επί δεκατέσσερα χρόνια υπό τη διοίκηση του Κράτους του Μαχντί. Η περιοχή θα περνούσε στη βρετανοαιγυπτιακή κοινή διοίκηση μόλις το 1899, με τον οθωμανικό δεσμό πλήρως κομμένο.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Η ιταλική κατοχή της Μασσαουά — η απώλεια της δυτικής ακτής της Ερυθράς Θάλασσας", "c333b95b"], "d": ["Το λιμάνι της Μασσαουά, κέντρο της επαρχίας της Αβησσυνίας, καταλήφθηκε από την Ιταλία, που εκμεταλλεύτηκε την αναταραχή με την οποία η εξέγερση του Μαχντί κάλυψε το Σουδάν· αυτό αποτέλεσε τον πυρήνα της Ιταλικής Ερυθραίας. Και το Σεβακίν στα βόρεια και το αρχιπέλαγος Ντάχλακ στην ανοιχτή θάλασσα χάθηκαν στην ίδια διαδικασία. Έτσι έληξε η οθωμανική κυριαρχία στη δυτική ακτή της Ερυθράς Θάλασσας που διαρκούσε από την εποχή του Σελίμ του Γιαβούζ, και η θάλασσα έγινε πλέον ένα νερό ξένο και στις δύο όχθες.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Η ιταλική κατοχή της Ρόδου", "e08662c5"], "d": ["Στον Τριπολιτικό Πόλεμο η Ιταλία, θέλοντας να φέρει το Οθωμανικό Κράτος στο τραπέζι των διαπραγματεύσεων, μετέφερε τον πόλεμο στη Μεσόγειο και αποβίβασε στρατό στη Ρόδο. Το νησί παραδόθηκε μέσα σε λίγες ημέρες. Η Ρόδος, που ο Σουλεϊμάν ο Μεγαλοπρεπής είχε καταλάβει με μακρά πολιορκία το 1522 και κρατούσε επί τριακόσια ενενήντα χρόνια, έπαψε έτσι να είναι η μεγαλύτερη νησιωτική βάση της αυτοκρατορίας στην Ανατολική Μεσόγειο· αν και στη Συνθήκη του Ουσί θεωρήθηκε προσωρινή κατοχή, δεν ανακτήθηκε ποτέ ξανά.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Η ιταλική κατοχή του Δωδεκανήσου", "200aacf2"], "d": ["Μέσα στην εβδομάδα μετά την κατάληψη της Ρόδου, ο ιταλικός στόλος κατέλαβε και τα γύρω νησιά· σε αυτό το αρχιπέλαγος θα δινόταν αργότερα το όνομα «Δωδεκάνησα». Τα περισσότερα νησιά απείχαν λίγα μίλια από την ακτή της Ανατολίας και ήλεγχαν το νοτιοανατολικό πέρασμα του Αιγαίου. Η κατοχή θεωρήθηκε προσωρινή στη Συνθήκη του Ουσί με αντάλλαγμα την εγκατάλειψη της Τρίπολης της Λιβύης, αλλά η Ιταλία δεν εκκένωσε ποτέ τα νησιά· το 1947 επρόκειτο να παραχωρηθούν στην Ελλάδα.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Η κατοχή της Κω", "ab246c62"], "d": ["Η Κως, ο τελευταίος κρίκος της επιχείρησης στο Δωδεκάνησο, ήταν ένα εύφορο και πολυάνθρωπο νησί ακριβώς απέναντι από τη χερσόνησο του Μπόντρουμ. Με την κατοχή, όλα τα νησιά στη νοτιοανατολική γωνία του Αιγαίου πέρασαν στον ιταλικό έλεγχο και η νοτιοδυτική ακτή της Ανατολίας περικυκλώθηκε από άκρη σε άκρη από μια αλυσίδα ξένων νησιών.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Η διακήρυξη ανεξαρτησίας της Ικαρίας", "c4452033"], "d": ["Στο μικρό νησί της Ικαρίας, ανάμεσα στη Σάμο και στη Χίο, ο λαός, μέσα στο κλίμα αβεβαιότητας που δημιούργησαν οι ιταλικές κατοχές, εξεγέρθηκε, έδιωξε την οθωμανική χωροφυλακή από το νησί και ανακήρυξε ένα «ελεύθερο κράτος» με δική του σημαία, γραμματόσημο και συνέλευση, που διήρκεσε πέντε μήνες. Τον Νοέμβριο του 1912 το νησί προσαρτήθηκε στην Ελλάδα. Παρά το μικρό του μέγεθος, αυτό το γεγονός είναι σαφής ένδειξη του πώς διαλυόταν η κεντρική διοίκηση στο Αιγαίο.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Η αποχώρηση της Σάμου από την οθωμανική διοίκηση", "3a862f2b"], "d": ["Η Σάμος ήταν από το 1832 ένα αυτόνομο ηγεμονικό κράτος (εμαρέτ) που πλήρωνε φόρο στους Οθωμανούς και διοικούνταν από έναν μπέη που διόριζε η Κωνσταντινούπολη. Στο κενό που δημιούργησε ο Τριπολιτικός Πόλεμος, το ενωτικό κίνημα στο νησί ανέλαβε τη διοίκηση και το αυτόνομο καθεστώς της ηγεμονίας έληξε de facto· το νησί μέσα στην ίδια χρονιά ανακήρυξε την ένωσή του με την Ελλάδα. Αυτό το νησί, που απέχει δύο χιλιόμετρα από την ακτή της Ανατολίας, ήταν από τα πρώτα εδάφη που χάθηκαν στο Αιγαίο.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Η πτώση των Ιωαννίνων — η απώλεια της Ηπείρου και της Πάργας", "d42fce18"], "d": ["Τα Ιωάννινα, που πολιορκήθηκαν επί πέντε μήνες στον Βαλκανικό Πόλεμο, παραδόθηκαν μετά την πτώση των οχυρώσεων του Μπιζανίου· μαζί με την πόλη ολόκληρη η Ήπειρος πέρασε στην Ελλάδα. Και η Πάργα, που υπαγόταν στο σαντζάκι των Ιωαννίνων, χάθηκε αυτή την ημερομηνία και η οθωμανική διοίκηση των ενενήντα τεσσάρων ετών έληξε. Η απώλεια των Ιωαννίνων σήμαινε το κλείσιμο του τελευταίου παραθύρου της αυτοκρατορίας προς την Αδριατική.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Η πτώση της Αδριανούπολης στους Βουλγάρους", "459d2e56"], "d": ["Έπειτα από πολιορκία πέντε και μισού μηνών, η Αδριανούπολη, της οποίας εξαντλήθηκαν τα πυρομαχικά και τα εφόδια, παραδόθηκε· ο Σιουκρού Πασάς αιχμαλωτίστηκε. Η πτώση της πόλης, που ήταν οθωμανική από το 1361 και είχε υπάρξει πρωτεύουσα επί ενενήντα δύο χρόνια, θεωρήθηκε το βαρύτερο πλήγμα του Βαλκανικού Πολέμου. Η Αδριανούπολη επρόκειτο να ανακτηθεί τέσσερις μήνες αργότερα, στον Δεύτερο Βαλκανικό Πόλεμο, εκμεταλλευόμενη την κατάρρευση της Βουλγαρίας στα άλλα μέτωπα.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Η απώλεια του Γιανμπού προς τις δυνάμεις του Σερίφη Χουσεΐν", "e291c816"], "d": ["Η εξέγερση που ξεκίνησε ο Σερίφης Χουσεΐν τον Ιούνιο εξαπλώθηκε στην ακτή της Ερυθράς Θάλασσας· το Γιανμπού, το λιμάνι της Μεδίνας, πέρασε στα χέρια των επαναστατών με την υποστήριξη του βρετανικού στόλου. Το λιμάνι έγινε η κύρια πύλη της ροής όπλων και χρημάτων που έρχονταν στην εξέγερση από έξω. Έτσι η σύνδεση των δυνάμεων του Φαχρεντίν Πασά στη Μεδίνα με τη θάλασσα κόπηκε και η πόλη έμεινε μόνη στο άκρο του σιδηροδρόμου του Χιτζάζ.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Η Τρίτη Μάχη της Γάζας — η απώλεια της Γάζας και του Χαν Γιουνίς", "c142a069"], "d": ["Έπειτα από δύο αποτυχημένες απόπειρες, ο Άλενμπι στην τρίτη επίθεσή του διέρρηξε το μέτωπο παρακάμπτοντας το Μπερσεβά και η γραμμή της Γάζας, που είχε κρατηθεί έξι μήνες, κατέρρευσε. Η Γάζα και το Χαν Γιουνίς νότια αυτής εκκενώθηκαν την ίδια ημέρα. Αυτή η διάρρηξη έγινε η αρχή της διάλυσης του μετώπου της Παλαιστίνης· η Ιερουσαλήμ επρόκειτο να πέσει πέντε εβδομάδες αργότερα.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Η κατοχή της Κομοτηνής — η απώλεια της Δυτικής Θράκης", "904d813c"], "d": ["Η Δυτική Θράκη, που μετά το Μούδρος πέρασε πρώτα υπό τον έλεγχο των δυνάμεων της Αντάντ, παραχωρήθηκε στην Ελλάδα με απόφαση της διάσκεψης του Σαν Ρέμο και ο ελληνικός στρατός μπήκε στην Κομοτηνή. Η περιοχή, που είχε ανακτηθεί από τη Βουλγαρία το 1913, ήταν το τελευταίο έδαφος που έχασε η αυτοκρατορία στη Ρούμελη. Το καθεστώς του τουρκικού πληθυσμού της περιοχής επρόκειτο να ρυθμιστεί τρία χρόνια αργότερα στη Λωζάνη με το καθεστώς της μειονότητας. Με αυτή την κατοχή τα καζά της Κομοτηνής, της Ξάνθης, του Δεδεαγάτς και του Σουφλίου της Δυτικής Θράκης πέρασαν στην Ελλάδα.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Η διάλυση του Κράτους των Ιλχανιδών: ο θάνατος του Αμπού Σαΐντ Μπαχαντούρ Χαν", "0f187469"], "d": ["Σύμφωνα με το λήμμα Ιλχανίδες της Εγκυκλοπαίδειας Ισλάμ του TDV, ο θάνατος του Αμπού Σαΐντ χωρίς να αφήσει διάδοχο προκάλεσε τον κατακερματισμό του Κράτους των Ιλχανιδών, που επί έναν αιώνα κυριαρχούσε στην Περσία· οι εμίρηδες, εκμεταλλευόμενοι τους αγώνες για τον θρόνο, ίδρυσαν τοπικές δυναστείες όπως οι Τζελαϊρίδες, οι Καρακογιουνλού, οι Μουζαφφαρίδες, οι Σερμπεντάρηδες του Χορασάν και οι Ερετναογλου. Αυτή η διάλυση διαίρεσε την περιοχή σε ένα μωσαϊκό εμιράτων που θα διαρκούσε έναν αιώνα· τελικά θα επανενωνόταν με τις εκστρατείες του Ταμερλάνου.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Ο Ταμερλάνος υπέταξε το μεγαλύτερο μέρος της Περσίας", "1cee2b82"], "d": ["Σύμφωνα με το λήμμα Ταμερλάνος της Εγκυκλοπαίδειας Ισλάμ του TDV, ο Ταμερλάνος, που από τις αρχές της δεκαετίας του 1380 εκκαθάριζε ένα προς ένα τις τοπικές δυναστείες μετά τους Ιλχανίδες, όπως τους Σερμπεντάρηδες, τους Κερτίδες και τους Μουζαφφαρίδες, κατά την «τριετή εκστρατεία» του 1386-1388 υπέταξε de facto το μεγαλύτερο μέρος της Περσίας· το οριστικό τέλος της δυναστείας των Μουζαφφαρίδων θα δινόταν το 1393. Η περιοχή έτσι, έπειτα από έναν αιώνα κατακερματισμού, υπήχθη ξανά σε μία κεντρική εξουσία.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Η νίκη στον Άρακα: ο Κάρα Γιουσούφ νίκησε τον Τιμουρίδη Αμπού Μπεκρ Μιρζά", "4b61a75a"], "d": ["Ο Κάρα Γιουσούφ, ο μπέης των Καρακογιουνλού, που επέστρεψε από την εξορία μετά τον θάνατο του Ταμερλάνου το 1405, αφού κατέλαβε το Αβνίκ και ξαναπήρε τα εδάφη του στην Ανατολική Ανατολία, βάδισε εναντίον του Αμπού Μπεκρ Μιρζά, εγγονού του Ταμερλάνου, που θεωρούνταν κύριος του Αζερμπαϊτζάν και των δύο Ιράκ, και τον νίκησε στις όχθες του Άρακα. Αυτή η νίκη δεν έδωσε την Ταυρίδα στους Καρακογιουνλού: το TDV `tebriz` γράφει ότι η πόλη το 1408 ήταν στα χέρια του Αμπού Μπεκρ Μιρζά· ο πόλεμος που κέρδισε το Αζερμπαϊτζάν είναι ο Σερντρούντ της 13ης Απριλίου 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Η νίκη στο Σερντρούντ: η Ταυρίδα και το Αζερμπαϊτζάν πέρασαν στους Καρακογιουνλού", "1f0a429d"], "d": ["Ο Κάρα Γιουσούφ νίκησε τον Τιμουρίδη Αμπού Μπεκρ Μιρζά για δεύτερη φορά μετά τον Άρακα, στο Σερντρούντ κοντά στην Ταυρίδα· αυτή η νίκη έδωσε το Αζερμπαϊτζάν στους Καρακογιουνλού. Ο Κάρα Γιουσούφ στη συνέχεια ανέθεσε στον Μπιστάμ Μπέη την κατάκτηση του Ιράκ-ι Αζάμ (Περσικού Ιράκ);", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Επιδημία πανούκλας στην Κωνσταντινούπολη και μεταφορά των ανακτόρων στην Αδριανούπολη", "70c7a163"], "d": ["Σύμφωνα με το λήμμα Κωνσταντινούπολη της Εγκυκλοπαίδειας Ισλάμ του TDV, ο ταχύς και πυκνός εποικισμός της πόλης προετοίμασε το έδαφος για την εξάπλωση επιδημικών ασθενειών κατά διαστήματα· κατά την επιδημία πανούκλας του έτους 1466 τα ανάκτορα και οι αξιωματούχοι του κράτους αποσύρθηκαν προσωρινά στην Αδριανούπολη. Ο πληθυσμός της πόλης έχασε σοβαρό αριθμό ανθρώπων σε τέτοιες επιδημίες.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Ο Ουζούν Χασάν έβαλε τέλος στο Κράτος των Καρακογιουνλού", "ef68399e"], "d": ["Σύμφωνα με το λήμμα Ουζούν Χασάν της Εγκυκλοπαίδειας Ισλάμ του TDV, ο ηγεμόνας των Ακκογιουνλού Ουζούν Χασάν νίκησε και σκότωσε τον ηγεμόνα των Καρακογιουνλού Τζιχάν Σαχ στην περιοχή Μπιγκιόλ-Σαντζάκ στις 12 Ρεμπιυλαχίρ 872 / 10 Νοεμβρίου 1467· ο γιος του Τζιχάν Σαχ, Χασάν Αλί, ηττήθηκε στο Μερέντ τον Σεπτέμβριο του 1468, σκοτώθηκε μπροστά στο Χαμαδάν τον Απρίλιο-Μάιο του 1469 και το Κράτος των Καρακογιουνλού έληξε οριστικά. Τα εδάφη πέρασαν στην κυριαρχία των Ακκογιουνλού· το κράτος τη δεκαετία που ακολουθούσε επρόκειτο να επεκταθεί έως το εσωτερικό της Περσίας.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Άνοιγμα των μεντρεσέδων του Σαχν-ι Σεμάν στη διδασκαλία", "021f2a83"], "d": ["Σύμφωνα με το λήμμα Σαχν-ι Σεμάν της Εγκυκλοπαίδειας Ισλάμ του TDV, αυτές οι οκτώ μεντρεσέδες που ιδρύθηκαν στο πλαίσιο του Συγκροτήματος του Πορθητή σχεδιάστηκαν ως το ανώτατου επιπέδου εκπαιδευτικό ίδρυμα της εποχής και αποτέλεσαν την κορυφή της οθωμανικής ιεραρχίας των ουλεμάδων. Η διδασκαλία εκεί και η αποφοίτηση από αυτές θεωρούνταν στους επόμενους αιώνες το πιο έγκυρο σκαλοπάτι στη σταδιοδρομία του κατή και του μουδερρίση.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Η ολοκλήρωση του Ανακτόρου Τοπκαπί (Σαράι-ι Τζεντίντ)", "d2db6323"], "d": ["Σύμφωνα με το λήμμα Ανάκτορο Τοπκαπί της Εγκυκλοπαίδειας Ισλάμ του TDV, οι πηγές της εποχής διαφέρουν ως προς την έναρξη και το τέλος των εργασιών· σύμφωνα με την ημερομηνία 883 (1478) της επιγραφής της Πύλης Μπαμπ-ι Χουμαγιούν, οι εργασίες που είχαν ξεκινήσει πιθανότατα το 1465 με διαταγή του Πορθητή είχαν σε μεγάλο βαθμό ολοκληρωθεί έως αυτό το έτος και το ανάκτορο πήρε τη θέση του κέντρου του κράτους στο παλιό ανάκτορο. Έτσι ο σουλτάνος μετακόμισε στη νέα κατοικία που επρόκειτο να είναι για τρεις αιώνες η διοικητική και τελετουργική καρδιά του κράτους.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Η ανάρρηση του Βαγιαζήτ Β΄ στην Κωνσταντινούπολη", "9b686d04"], "d": ["Σύμφωνα με το λήμμα Βαγιαζήτ Β΄ της Εγκυκλοπαίδειας Ισλάμ του TDV, ο πρίγκιπας Βαγιαζήτ, διοικητής του σαντζακίου της Αμάσειας, μόλις έμαθε τον θάνατο του πατέρα του ήρθε γρήγορα στην Κωνσταντινούπολη και ανέβηκε στον θρόνο· με την υποστήριξη των γενιτσάρων άφησε πίσω την αναχώρηση του αδελφού του Τζεμ από το Ικόνιο. Κατά την ανάρρηση μοιράστηκε στους γενίτσαρους το συνηθισμένο δώρο ανάρρησης. Αυτή η αλλαγή θρόνου άναψε και το φιτίλι του αγώνα ανάμεσα στους δύο αδελφούς.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Ο Τζεμ Σουλτάν ανακήρυξε τον εαυτό του σουλτάνο στην Προύσα", "b355168a"], "d": ["Σύμφωνα με το λήμμα Τζεμ Σουλτάν της Εγκυκλοπαίδειας Ισλάμ του TDV, ο Τζεμ, που έφτασε στην Προύσα μέσω Καραμανίας, κατέλαβε την πόλη, ανακήρυξε τον εαυτό του σουλτάνο και έκανε να διαβαστεί το χουτμπέ. Αυτή η βραχύβια σουλτανία έληξε όταν οι δυνάμεις που έστειλε ο μεγαλύτερος αδελφός του Βαγιαζήτ Β΄ νίκησαν τον Τζεμ στη Γενισεχίρ. Μετά την ήττα ο Τζεμ αναγκάστηκε να καταφύγει προς την Αίγυπτο.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Η εκτέλεση του Γκεντίκ Αχμέτ Πασά", "6d75a58c"], "d": ["Σύμφωνα με το λήμμα Γκεντίκ Αχμέτ Πασάς της Εγκυκλοπαίδειας Ισλάμ του TDV, ο πασάς, γνωστός από την εκστρατεία του Οτράντο και το αξίωμα του μεγάλου βεζίρη, εκτελέστηκε στην Αδριανούπολη με διαταγή του Βαγιαζήτ Β΄ λόγω της στάσης του στο ζήτημα του Τζεμ Σουλτάν και των ανησυχιών για την επιρροή του. Ο θάνατος ενός από τους πιο έμπειρους διοικητές της εποχής του Πορθητή προκάλεσε ευρεία αίσθηση στα ανάκτορα.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Ίδρυση του πρώτου τυπογραφείου στην Κωνσταντινούπολη", "04475930"], "d": ["Σύμφωνα με το λήμμα Τυπογραφείο της Εγκυκλοπαίδειας Ισλάμ του TDV, οι Εβραίοι μετανάστες από την Ισπανία, αδελφοί David και Samuel ibn Nahmias, ίδρυσαν στην Κωνσταντινούπολη το πρώτο τυπογραφείο που τύπωνε με εβραϊκούς χαρακτήρες. Αυτό καταγράφηκε ως η πρώτη τυπογραφική πρωτοβουλία που δραστηριοποιήθηκε σε οθωμανικά εδάφη· η εκτύπωση στα τουρκικά με αραβικούς χαρακτήρες θα ήταν δυνατή πολύ αργότερα, τον 18ο αιώνα.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Ο Σάχης Ισμαήλ κατέλαβε την Ταυρίδα: η ίδρυση του Κράτους των Σαφαβιδών", "014d81e6"], "d": ["Σύμφωνα με τα λήμματα Σαφαβίδες και Ακκογιουνλού της Εγκυκλοπαίδειας Ισλάμ του TDV, ο νεαρός σεΐχης του τεκκέ του Αρντεμπίλ Ισμαήλ, με τον στρατό που είχε συγκροτήσει από τους Κιζιλμπάσηδες μουρίτες της Ανατολίας, επέφερε βαριά ήττα στον σουλτάνο των Ακκογιουνλού Αλβέντ στην περιοχή του Ναχιτσεβάν· ο Αλβέντ διέφυγε στο Ντιγιαρμπακίρ, ο Ισμαήλ μπήκε στην Ταυρίδα, κάθισε στον θρόνο και ανακήρυξε την ιμαμική (δωδεκαδική) σιϊτική πίστη επίσημο δόγμα. Έτσι έκλεισε και η κυριαρχία των Ακκογιουνλού και η περίοδος των μετα-ιλχανιδικών εμιράτων της περιοχής· ιδρύθηκε το Κράτος των Σαφαβιδών που επρόκειτο να διαρκέσει τρεις αιώνες.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Ο σεισμός της «Μικρής Συντέλειας» στην Κωνσταντινούπολη", "53e3b1d6"], "d": ["Σύμφωνα με το λήμμα Κωνσταντινούπολη της Εγκυκλοπαίδειας Ισλάμ του TDV, ο σφοδρός σεισμός που έπληξε την πόλη στην εποχή του ονομάστηκε από τον λαό «Μικρή Συντέλεια»· προκλήθηκαν σοβαρές ζημιές στα τείχη, στα τζαμιά και σε πολλά κτίρια και υπήρξαν πολλές απώλειες ζωών. Με διαταγή του Βαγιαζήτ Β΄ ξεκίνησε στην πόλη μια ευρείας κλίμακας κινητοποίηση για επισκευές και ανοικοδόμηση.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Η έναρξη της εξέγερσης του Σαχκουλού", "3d9a4a90"], "d": ["Σύμφωνα με το λήμμα Σαχκουλού Μπαμπά Τεκελί της Εγκυκλοπαίδειας Ισλάμ του TDV, ο Σαχκουλού, τροφοδοτούμενος από τη σαφαβιδική προπαγάνδα, συγκέντρωσε γύρω του μεγάλο πλήθος Τουρκμένων στην περιοχή της Τεκέ και ξεκίνησε μεγάλη εξέγερση θρησκευτικού-κοινωνικού χαρακτήρα. Η εξέγερση, ως μία από τις σοβαρότερες κρίσεις εσωτερικής ασφάλειας της εποχής, κλόνισε βαθιά την κεντρική εξουσία του κράτους.", "3e064ec6"]}
});
